import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { API_BASE_URL } from "@/config/api";
import { useAuth } from "@/contexts/AuthContext";
import { toast } from "@/components/ui/sonner";
import { useRolePermissions } from "@/hooks/useRolePermissions";
import {
  AlertDialog,
  AlertDialogContent,
  AlertDialogHeader,
  AlertDialogFooter,
  AlertDialogTitle,
  AlertDialogCancel,
  AlertDialogAction,
} from "@/components/ui/alert-dialog";
import { useState } from "react";

export default function RekeningTable({
  data,
  onEdit,
  onDelete,
  selectedRows,
  setSelectedRows,
}) {
  const { token, user, logout } = useAuth();
  const { canRead, canUpdate: canEdit, canDelete } = useRolePermissions(user?.role, token);
  const [deleteId, setDeleteId] = useState(null);
  const [openDeleteDialog, setOpenDeleteDialog] = useState(false);

  const handleSelectRow = (id) => {
    setSelectedRows((prev) =>
      prev.includes(id) ? prev.filter((x) => x !== id) : [...prev, id]
    );
  };

  const handleSelectAll = (e) => {
    if (e.target.checked) {
      setSelectedRows(data.map((r) => r.id));
    } else {
      setSelectedRows([]);
    }
  };

  const handleDelete = async (id) => {
    try {
      const res = await fetch(`${API_BASE_URL}/api/rekening/${id}`, {
        method: "DELETE",
        headers: {
          Authorization: `Bearer ${token}`,
        },
      });

      if (res.status === 401) {
        logout();
        return;
      }

      toast.success("Rekening berhasil dihapus");
      setOpenDeleteDialog(false);
      setDeleteId(null);
      onDelete?.();
    } catch (err) {
      console.error("Gagal hapus rekening", err);
      toast.error("Gagal menghapus rekening");
    }
  };

  return (
    <>
      <Table>
        <TableHeader>
          <TableRow className="dark:border-gray-700 dark:hover:bg-gray-800">
            <TableHead className="w-10 dark:text-gray-300">
              <input
                type="checkbox"
                checked={selectedRows.length === data.length && data.length > 0}
                onChange={handleSelectAll}
                className="h-4 w-4 dark:accent-cyan-500"
              />
            </TableHead>
            <TableHead className="dark:text-gray-300">Kode Bank</TableHead>
            <TableHead className="dark:text-gray-300">No Rekening</TableHead>
            <TableHead className="dark:text-gray-300">Nama Pemilik</TableHead>
            <TableHead className="dark:text-gray-300">Status</TableHead>
             {canRead('rekening') && canEdit('rekening') && (<TableHead className="text-right dark:text-gray-300">Aksi</TableHead>)}
          </TableRow>
        </TableHeader>
        <TableBody>
          {data.map((rekening) => (
            <TableRow key={rekening.id} className="dark:border-gray-700 dark:hover:bg-gray-800">
              <TableCell>
                <input
                  type="checkbox"
                  checked={selectedRows.includes(rekening.id)}
                  onChange={() => handleSelectRow(rekening.id)}
                  className="h-4 w-4 dark:accent-cyan-500"
                />
              </TableCell>
              <TableCell className="dark:text-gray-300">{rekening.kode_bank}</TableCell>
              <TableCell className="dark:text-gray-300">{rekening.nomor_rekening}</TableCell>
              <TableCell className="dark:text-gray-300">{rekening.nama_pemilik}</TableCell>
              <TableCell>
                <span className={rekening.aktif ? "text-green-600 dark:text-green-400" : "text-red-600 dark:text-red-400"}>
                  {rekening.aktif ? "✓ Aktif" : "✗ Tidak Aktif"}
                </span>
              </TableCell>
              <TableCell className="text-right space-x-2">
                {canRead('rekening') && canEdit('rekening') && (
                  <button
                    onClick={() => onEdit(rekening)}
                    className="inline-flex items-center rounded-md bg-[#ed6f5c] px-4 py-2 text-sm font-semibold text-white hover:bg-[#ed6f5c] dark:bg-[#ed6f5c] dark:hover:bg-blue-700"
                  >
                    Edit
                  </button>
                )}
               
              </TableCell>
            </TableRow>
          ))}
        </TableBody>
      </Table>

      {/* DELETE DIALOG */}
      <AlertDialog open={openDeleteDialog} onOpenChange={setOpenDeleteDialog}>
        <AlertDialogContent className="bg-[#f7f1de] dark:bg-gray-900 dark:text-gray-100">
          <AlertDialogHeader>
            <AlertDialogTitle>Hapus Rekening?</AlertDialogTitle>
          </AlertDialogHeader>
          <p className="text-sm text-gray-600 dark:text-gray-400">
            Tindakan ini tidak dapat dibatalkan.
          </p>
          <AlertDialogFooter>
            <AlertDialogCancel className="dark:bg-gray-800 dark:text-gray-200">
              Batal
            </AlertDialogCancel>
            <AlertDialogAction
              onClick={() => handleDelete(deleteId)}
              className="bg-red-600 hover:bg-red-700"
            >
              Hapus
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </>
  );
}
