import { useEffect, useState } from "react";

import { API_BASE_URL } from "@/config/api";
import { countryCodeToFlag } from "@/utils/countryFlag";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import { Input } from "@/components/ui/input";
import { Button } from "@/components/ui/button";
import { toast } from "@/components/ui/sonner";
import { useAuth } from "@/contexts/AuthContext";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";

export default function WargaForm({ open, onOpenChange, warga, onSaved }) {
  const { token } = useAuth(); // 🔐 JWT
  const [loading, setLoading] = useState(false);
  const [rumahList, setRumahList] = useState([]); // 🏠 Rumah list for dropdown
  const [strataOpsi, setStrataOpsi] = useState([]); // opsi strata ekonomi dari referensi
  const [bantuanOpsi, setBantuanOpsi] = useState([]); // opsi bantuan sosial dari referensi
  const [negaraOpsi, setNegaraOpsi] = useState([]); // opsi negara (kewarganegaraan) dari referensi
  const [statusWargaOpsi, setStatusWargaOpsi] = useState([]); // opsi status warga dari referensi
  const [pekerjaanOpsi, setPekerjaanOpsi] = useState([]); // opsi pekerjaan dari referensi
  const [posisiKeluargaOpsi, setPosisiKeluargaOpsi] = useState([]); // opsi posisi keluarga dari referensi
  const [agamaOpsi, setAgamaOpsi] = useState([]); // opsi agama dari referensi
  const [jenisKelaminOpsi, setJenisKelaminOpsi] = useState([]); // opsi jenis kelamin dari referensi

  const [form, setForm] = useState({
    nama_lengkap: "",
    country_code: "+62",          // ✅ DEFAULT
    whatsapp: "",
    tanggal_lahir: "",
    tempat_lahir: "",
    jenis_kelamin: "Laki-laki",
    agama: "",
    pekerjaan: "",
    posisi_keluarga: "Kepala Keluarga",
    block_house: "",
    status: "active",
    status_detail: "Aktif",
    status_changed_at: "",       // 🔥 tgl pindah/meninggal (manual, opsional)
    strata_ekonomi: "",
    bantuan_diterima: [],
    kewarganegaraan: "ID",
  });

  // --------------------------------------------------
  // HELPER: Format rumah display text
  // --------------------------------------------------
  const getDisplayText = (rumah) => {
    let text = rumah.blok_no;
    if (rumah.pemilik_sah) {
      text += ` - ${rumah.pemilik_sah}`;
    }
    if (rumah.nama_jalan) {
      text += ` (${rumah.nama_jalan})`;
    }
    return text;
  };

  // --------------------------------------------------
  // FETCH OPSI REFERENSI (strata & bantuan) — public endpoint
  // --------------------------------------------------
  const fetchOpsiReferensi = async () => {
    try {
      const [strataRes, bantuanRes, negaraRes, statusRes, pekerjaanRes, posisiRes, agamaRes, genderRes] = await Promise.all([
        fetch(`${API_BASE_URL}/api/referensi/strata-ekonomi`),
        fetch(`${API_BASE_URL}/api/referensi/bantuan-sosial`),
        fetch(`${API_BASE_URL}/api/referensi/negara`),
        fetch(`${API_BASE_URL}/api/referensi/status-warga`),
        fetch(`${API_BASE_URL}/api/referensi/pekerjaan`),
        fetch(`${API_BASE_URL}/api/referensi/posisi-keluarga`),
        fetch(`${API_BASE_URL}/api/referensi/agama`),
        fetch(`${API_BASE_URL}/api/referensi/jenis-kelamin`),
      ]);
      if (strataRes.ok) setStrataOpsi(await strataRes.json());
      if (bantuanRes.ok) setBantuanOpsi(await bantuanRes.json());
      if (negaraRes.ok) setNegaraOpsi(await negaraRes.json());
      if (statusRes.ok) setStatusWargaOpsi(await statusRes.json());
      if (pekerjaanRes.ok) setPekerjaanOpsi(await pekerjaanRes.json());
      if (posisiRes.ok) setPosisiKeluargaOpsi(await posisiRes.json());
      if (agamaRes.ok) setAgamaOpsi(await agamaRes.json());
      if (genderRes.ok) setJenisKelaminOpsi(await genderRes.json());
    } catch (err) {
      console.error("Gagal load opsi referensi:", err);
    }
  };

  // --------------------------------------------------
  // FETCH RUMAH LIST
  // --------------------------------------------------
  const fetchRumah = async () => {
    try {
      const res = await fetch(`${API_BASE_URL}/api/rumah`, {
        headers: {
          Authorization: `Bearer ${token}`,
        },
      });

      if (res.ok) {
        const data = await res.json();
        setRumahList(data);
      }
    } catch (err) {
      console.error("Gagal load rumah:", err);
    }
  };

  // --------------------------------------------------
  // LOAD DATA SAAT EDIT
  // --------------------------------------------------
  useEffect(() => {
    if (open) {
      fetchRumah();
      fetchOpsiReferensi();
    }
  }, [open]);

  // --------------------------------------------------
  // LOAD DATA SAAT EDIT
  // --------------------------------------------------
  useEffect(() => {
    if (warga && rumahList.length > 0) {
      // Find matching rumah to get formatted display text
      const matchingRumah = rumahList.find(r => r.blok_no === warga.block_house);
      const displayValue = matchingRumah ? getDisplayText(matchingRumah) : (warga.block_house || "");
      
      setForm({
        nama_lengkap: warga.nama_lengkap || "",
        country_code: warga.country_code || "+62",
        whatsapp: warga.whatsapp || "",
        tanggal_lahir: warga.tanggal_lahir ? warga.tanggal_lahir.split("T")[0] : "",
        tempat_lahir: warga.tempat_lahir || "",
        jenis_kelamin: warga.jenis_kelamin || "Laki-laki",
        agama: warga.agama || "",
        pekerjaan: warga.pekerjaan || "",
        posisi_keluarga: warga.posisi_keluarga || "Kepala Keluarga",
        block_house: displayValue,
        status: warga.status || "active",
        strata_ekonomi: warga.strata_ekonomi || "",
        bantuan_diterima: Array.isArray(warga.bantuan_diterima) ? warga.bantuan_diterima : [],
        kewarganegaraan: warga.kewarganegaraan || "ID",
        status_detail: warga.status_detail || (warga.status === "active" ? "Aktif" : "Tidak Aktif"),
        status_changed_at: warga.status_changed_at ? warga.status_changed_at.split("T")[0] : "",
      });
    } else {
      setForm({
        nama_lengkap: "",
        country_code: "+62",
        whatsapp: "",
        tanggal_lahir: "",
        tempat_lahir: "",
        jenis_kelamin: "Laki-laki",
        agama: "",
        pekerjaan: "",
        posisi_keluarga: "Kepala Keluarga",
        block_house: "",
        status: "active",
        status_detail: "Aktif",
        status_changed_at: "",
        strata_ekonomi: "",
        bantuan_diterima: [],
        kewarganegaraan: "ID",
      });
    }
  }, [warga, rumahList]);

  // --------------------------------------------------
  // SAVE
  // --------------------------------------------------
  const save = async () => {
    if (!form.nama_lengkap.trim()) {
      toast.error("Nama lengkap harus diisi");
      return;
    }

    if (!form.whatsapp.trim()) {
      toast.error("Nomor WhatsApp harus diisi");
      return;
    }

    setLoading(true);

    const url = warga
      ? `${API_BASE_URL}/api/warga/${warga.id}`
      : `${API_BASE_URL}/api/warga`;

    const method = warga ? "PUT" : "POST";

    try {
      // Convert empty strings to null untuk optional fields
      let blockHouseValue = form.block_house;
      
      // Extract blok_no from the full display text if it's not "none"
      if (blockHouseValue && blockHouseValue !== "none") {
        blockHouseValue = blockHouseValue.split(" - ")[0]; // Extract first part (blok_no)
      }
      
      const payload = {
        nama_lengkap: form.nama_lengkap || null,
        country_code: form.country_code,
        whatsapp: form.whatsapp || null,
        tanggal_lahir: form.tanggal_lahir ? form.tanggal_lahir : null,
        tempat_lahir: form.tempat_lahir || null,
        jenis_kelamin: form.jenis_kelamin || null,
        agama: form.agama || null,
        pekerjaan: form.pekerjaan || null,
        posisi_keluarga: form.posisi_keluarga || null,
        block_house: blockHouseValue === "none" ? null : (blockHouseValue || null),
        status: form.status,
        strata_ekonomi: form.strata_ekonomi || null,
        bantuan_diterima: form.bantuan_diterima,
        kewarganegaraan: form.kewarganegaraan || null,
        status_detail: form.status_detail || "Aktif",
        // 🔥 Tanggal manual hanya dikirim kalau status Pindah/Meninggal & tanggal diisi.
        // Kalau tidak, backend otomatis isi dgn waktu sekarang saat status berubah.
        status_changed_at:
          ["Pindah", "Meninggal"].includes(form.status_detail) && form.status_changed_at
            ? form.status_changed_at
            : null,
      };

      const res = await fetch(url, {
        method,
        headers: {
          "Content-Type": "application/json",
          Authorization: `Bearer ${token}`, // 🔐 JWT
        },
        body: JSON.stringify(payload),
      });

      if (!res.ok) {
        toast.error("Gagal menyimpan warga");
        setLoading(false);
        return;
      }

      toast.success(warga ? "Warga berhasil diperbarui!" : "Warga baru ditambahkan!");
      onSaved();
      onOpenChange(false);

    } catch (err) {
      toast.error("Tidak dapat terhubung ke server");
    }

    setLoading(false);
  };

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="max-w-2xl dark:bg-gray-900 dark:text-gray-100 max-h-screen overflow-y-auto">
        <DialogHeader>
          <DialogTitle>{warga ? "Edit Warga" : "Tambah Warga"}</DialogTitle>
        </DialogHeader>

        <div className="space-y-3">

          {/* ROW 1: NAMA LENGKAP */}
          <Input
            placeholder="Nama Lengkap"
            value={form.nama_lengkap}
            onChange={(e) =>
              setForm({ ...form, nama_lengkap: e.target.value })
            }
            className="dark:bg-gray-800 dark:text-gray-100"
          />

          {/* ROW 2: KODE NEGARA & WHATSAPP */}
          <div className="grid grid-cols-3 gap-3">
            <Input
              placeholder="Kode Negara"
              value={form.country_code}
              disabled
              className="dark:bg-gray-800 dark:text-gray-100"
            />
            <Input
              placeholder="Nomor WhatsApp"
              value={form.whatsapp}
              onChange={(e) =>
                setForm({ ...form, whatsapp: e.target.value })
              }
              className="col-span-2 dark:bg-gray-800 dark:text-gray-100"
            />
          </div>

          {/* ROW 3: TANGGAL LAHIR & JENIS KELAMIN */}
          <div className="grid grid-cols-2 gap-3">
            <div>
              <label className="block text-xs font-medium text-gray-600 dark:text-gray-400 mb-1">
                Tanggal Lahir
              </label>
              <Input
                type="date"
                value={form.tanggal_lahir}
                onChange={(e) =>
                  setForm({ ...form, tanggal_lahir: e.target.value })
                }
                className="dark:bg-gray-800 dark:text-gray-100"
              />
            </div>
            <div>
              <label className="block text-xs font-medium text-gray-600 dark:text-gray-400 mb-1">
                Jenis Kelamin
              </label>
              <select
                value={form.jenis_kelamin}
                onChange={(e) =>
                  setForm({ ...form, jenis_kelamin: e.target.value })
                }
                className="
                  w-full p-2 rounded-md border
                  border-gray-300 dark:border-gray-700
                  bg-[#f7f1de] dark:bg-gray-800
                  text-gray-900 dark:text-gray-100
                  focus:outline-none focus:ring-2 focus:ring-cyan-500
                "
              >
                <option value="">-- Pilih Jenis Kelamin --</option>
                {jenisKelaminOpsi.length > 0 ? (
                  jenisKelaminOpsi.map((o) => (
                    <option key={o.id} value={o.nilai}>{o.label}</option>
                  ))
                ) : (
                  <>
                    <option value="Laki-laki">Laki-laki</option>
                    <option value="Perempuan">Perempuan</option>
                  </>
                )}
              </select>
            </div>
          </div>

          {/* ROW 4: TEMPAT LAHIR & AGAMA */}
          <div className="grid grid-cols-2 gap-3">
            <div>
              <label className="block text-xs font-medium text-gray-600 dark:text-gray-400 mb-1">
                Tempat Lahir
              </label>
              <Input
                placeholder="Contoh: Jakarta"
                value={form.tempat_lahir}
                onChange={(e) => setForm({ ...form, tempat_lahir: e.target.value })}
                className="dark:bg-gray-800 dark:text-gray-100"
              />
            </div>
            <div>
              <label className="block text-xs font-medium text-gray-600 dark:text-gray-400 mb-1">
                Agama
              </label>
              <select
                value={form.agama}
                onChange={(e) => setForm({ ...form, agama: e.target.value })}
                className="
                  w-full p-2 rounded-md border
                  border-gray-300 dark:border-gray-700
                  bg-[#f7f1de] dark:bg-gray-800
                  text-gray-900 dark:text-gray-100
                  focus:outline-none focus:ring-2 focus:ring-cyan-500
                "
              >
                <option value="">-- Pilih Agama --</option>
                {agamaOpsi.length > 0 ? (
                  agamaOpsi.map((o) => (
                    <option key={o.id} value={o.nilai}>{o.label}</option>
                  ))
                ) : (
                  <>
                    <option value="Islam">Islam</option>
                    <option value="Kristen">Kristen</option>
                    <option value="Katolik">Katolik</option>
                    <option value="Hindu">Hindu</option>
                    <option value="Buddha">Buddha</option>
                    <option value="Konghucu">Konghucu</option>
                  </>
                )}
              </select>
            </div>
          </div>

          {/* ROW 4b: KEWARGANEGARAAN */}
          <div>
            <label className="block text-xs font-medium text-gray-600 dark:text-gray-400 mb-1">
              Kewarganegaraan
            </label>
            <select
              value={form.kewarganegaraan}
              onChange={(e) => setForm({ ...form, kewarganegaraan: e.target.value })}
              className="
                w-full p-2 rounded-md border
                border-gray-300 dark:border-gray-700
                bg-[#f7f1de] dark:bg-gray-800
                text-gray-900 dark:text-gray-100
                focus:outline-none focus:ring-2 focus:ring-cyan-500
              "
            >
              <option value="">-- Pilih Kewarganegaraan --</option>
              {negaraOpsi.map((n) => (
                <option key={n.id} value={n.nilai}>
                  {countryCodeToFlag(n.nilai)} {n.label} ({n.nilai})
                </option>
              ))}
            </select>
          </div>

          {/* ROW 5: PEKERJAAN */}
          <div>
            <label className="block text-xs font-medium text-gray-600 dark:text-gray-400 mb-1">
              Pekerjaan
            </label>
            <select
              value={form.pekerjaan}
              onChange={(e) => setForm({ ...form, pekerjaan: e.target.value })}
              className="
                w-full p-2 rounded-md border
                border-gray-300 dark:border-gray-700
                bg-[#f7f1de] dark:bg-gray-800
                text-gray-900 dark:text-gray-100
                focus:outline-none focus:ring-2 focus:ring-cyan-500
              "
            >
              <option value="">-- Pilih Pekerjaan --</option>
              {pekerjaanOpsi.length > 0 ? (
                pekerjaanOpsi.map((o) => (
                  <option key={o.id} value={o.nilai}>{o.label}</option>
                ))
              ) : (
                <>
                  <option value="Pegawai Negeri Sipil (PNS)">Pegawai Negeri Sipil (PNS)</option>
                  <option value="TNI / Polri">TNI / Polri</option>
                  <option value="Karyawan Swasta">Karyawan Swasta</option>
                  <option value="Wiraswasta">Wiraswasta</option>
                  <option value="Pedagang">Pedagang</option>
                  <option value="Petani">Petani</option>
                  <option value="Nelayan">Nelayan</option>
                  <option value="Buruh">Buruh</option>
                  <option value="Guru / Dosen">Guru / Dosen</option>
                  <option value="Tenaga Kesehatan">Tenaga Kesehatan</option>
                  <option value="Mahasiswa">Mahasiswa</option>
                  <option value="Pelajar">Pelajar</option>
                  <option value="Ibu Rumah Tangga">Ibu Rumah Tangga</option>
                  <option value="Pensiunan">Pensiunan</option>
                  <option value="Tidak Bekerja">Tidak Bekerja</option>
                  <option value="Lainnya">Lainnya</option>
                </>
              )}
            </select>
          </div>

          {/* ROW 6: POSISI KELUARGA & BLOK / NO RUMAH */}
          <div className="grid grid-cols-2 gap-3">
            <div>
              <label className="block text-xs font-medium text-gray-600 dark:text-gray-400 mb-1">
                Posisi Keluarga
              </label>
              <select
                value={form.posisi_keluarga}
                onChange={(e) =>
                  setForm({ ...form, posisi_keluarga: e.target.value })
                }
                className="
                  w-full p-2 rounded-md border
                  border-gray-300 dark:border-gray-700
                  bg-[#f7f1de] dark:bg-gray-800
                  text-gray-900 dark:text-gray-100
                  focus:outline-none focus:ring-2 focus:ring-cyan-500
                "
              >
                {posisiKeluargaOpsi.length > 0 ? (
                  posisiKeluargaOpsi.map((o) => (
                    <option key={o.id} value={o.nilai}>{o.label}</option>
                  ))
                ) : (
                  <>
                    <option value="Kepala Keluarga">Kepala Keluarga</option>
                    <option value="Istri">Istri</option>
                    <option value="Anak">Anak</option>
                    <option value="Lainnya">Lainnya</option>
                  </>
                )}
              </select>
            </div>
            <div>
              <label className="block text-xs font-medium text-gray-600 dark:text-gray-400 mb-1">
                Blok / No Rumah
              </label>
              <Select value={form.block_house === "" ? "none" : form.block_house} onValueChange={(value) => {
                if (value === "none") {
                  setForm({ ...form, block_house: "none" });
                } else {
                  // Store the full display text, will extract blok_no when saving
                  setForm({ ...form, block_house: value });
                }
              }}>
                <SelectTrigger className="dark:bg-gray-800 dark:border-gray-700 dark:text-gray-100">
                  <SelectValue placeholder="Pilih rumah" />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="none">-- Tidak ada rumah --</SelectItem>
                  {rumahList.map((rumah) => {
                    const displayText = getDisplayText(rumah);
                    return (
                      <SelectItem key={rumah.id} value={displayText}>
                        {displayText}
                      </SelectItem>
                    );
                  })}
                </SelectContent>
              </Select>
            </div>
          </div>

          {/* ROW 6: STATUS */}
          <div>
            <label className="block text-xs font-medium text-gray-600 dark:text-gray-400 mb-1">
              Status
            </label>
            <select
              value={form.status_detail}
              onChange={(e) =>
                setForm({ ...form, status_detail: e.target.value })
              }
              className="
                w-full p-2 rounded-md border
                border-gray-300 dark:border-gray-700
                bg-[#f7f1de] dark:bg-gray-800
                text-gray-900 dark:text-gray-100
                focus:outline-none focus:ring-2 focus:ring-cyan-500
              "
            >
              {statusWargaOpsi.length > 0 ? (
                statusWargaOpsi.map((s) => (
                  <option key={s.id} value={s.nilai}>{s.label}</option>
                ))
              ) : (
                // Fallback kalau referensi belum sempat termuat
                <>
                  <option value="Aktif">Aktif</option>
                  <option value="Kontrak">Kontrak</option>
                  <option value="Kos">Kos</option>
                  <option value="Pendatang Warga Sementara">Pendatang Warga Sementara</option>
                  <option value="Pindah">Pindah</option>
                  <option value="Meninggal">Meninggal</option>
                  <option value="Tidak Aktif">Tidak Aktif</option>
                </>
              )}
            </select>
          </div>

          {/* TANGGAL PINDAH / MENINGGAL — muncul hanya kalau status relevan */}
          {["Pindah", "Meninggal"].includes(form.status_detail) && (
            <div>
              <label className="block text-xs font-medium text-gray-600 dark:text-gray-400 mb-1">
                Tanggal {form.status_detail === "Pindah" ? "Pindah" : "Meninggal"}
              </label>
              <Input
                type="date"
                value={form.status_changed_at}
                onChange={(e) =>
                  setForm({ ...form, status_changed_at: e.target.value })
                }
              />
              <p className="text-xs text-gray-500 mt-1">
                Kosongkan untuk memakai tanggal hari ini
              </p>
            </div>
          )}

          {/* STRATA EKONOMI */}
          <div>
            <label className="block text-xs font-medium text-gray-600 dark:text-gray-400 mb-2">
              Strata Ekonomi
            </label>
            <div className="flex flex-wrap gap-2">
              {(strataOpsi.length > 0 ? strataOpsi : [
                {nilai:'Desil 1'},{nilai:'Desil 2'},{nilai:'Desil 3'},{nilai:'Desil 4'},{nilai:'Desil 5'},
                {nilai:'Desil 6'},{nilai:'Desil 7'},{nilai:'Desil 8'},{nilai:'Desil 9'},{nilai:'Desil 10'},
              ]).map(({ nilai }) => (
                <button key={nilai} type="button"
                  onClick={() => setForm({ ...form, strata_ekonomi: form.strata_ekonomi === nilai ? '' : nilai })}
                  className={`px-3 py-1.5 rounded-full text-xs font-semibold border transition-colors ${
                    form.strata_ekonomi === nilai
                      ? 'bg-blue-100 border-blue-500 text-blue-700'
                      : 'border-gray-300 text-gray-500 hover:bg-gray-100 dark:border-gray-600 dark:text-gray-400'
                  }`}>
                  {nilai}
                </button>
              ))}
            </div>
          </div>

          {/* BANTUAN YANG DITERIMA */}
          <div>
            <label className="block text-xs font-medium text-gray-600 dark:text-gray-400 mb-2">
              Bantuan Yang Diterima
            </label>
            <div className="flex flex-wrap gap-2">
              {(bantuanOpsi.length > 0 ? bantuanOpsi : [
                {nilai:'PKH',label:'Program Keluarga Harapan'},
                {nilai:'PIP',label:'Program Indonesia Pintar'},
                {nilai:'KIP',label:'Kartu Indonesia Pintar'},
                {nilai:'PBI-JK',label:'PBI Jaminan Kesehatan'},
                {nilai:'BST',label:'Bantuan Sosial Tunai'},
                {nilai:'BLT',label:'Bantuan Langsung Tunai'},
                {nilai:'BB/CCP',label:'Beras Bulog/Cadangan Pangan'},
                {nilai:'Rutilahu',label:'Rumah Tidak Layak Huni'},
              ]).map(({ nilai, label }) => {
                const active = form.bantuan_diterima.includes(nilai);
                return (
                  <button key={nilai} type="button"
                    title={label}
                    onClick={() => setForm({
                      ...form,
                      bantuan_diterima: active
                        ? form.bantuan_diterima.filter(x => x !== nilai)
                        : [...form.bantuan_diterima, nilai],
                    })}
                    className={`px-3 py-1.5 rounded-full text-xs font-semibold border transition-colors ${
                      active
                        ? 'bg-green-100 border-green-500 text-green-700'
                        : 'border-gray-300 text-gray-500 hover:bg-gray-100 dark:border-gray-600 dark:text-gray-400'
                    }`}>
                    {active && '✓ '}{nilai}
                  </button>
                );
              })}
            </div>
          </div>

          {/* BUTTONS */}
          <div className="flex gap-3 justify-end pt-4">
            <Button
              variant="outline"
              onClick={() => onOpenChange(false)}
              className="dark:border-gray-700 dark:text-gray-200 dark:hover:bg-gray-800"
            >
              Batal
            </Button>
            <Button
              onClick={save}
              disabled={loading}
              className="bg-[#ed6f5c] hover:bg-[#e05544] text-white"
            >
              {loading ? "Menyimpan..." : "Simpan"}
            </Button>
          </div>
        </div>
      </DialogContent>
    </Dialog>
  );
}
