import { useEffect, useState } from "react";

import { API_BASE_URL } from "@/config/api";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogFooter,
} from "@/components/ui/dialog";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import {
  AlertDialog,
  AlertDialogContent,
  AlertDialogHeader,
  AlertDialogFooter,
  AlertDialogTitle,
  AlertDialogCancel,
  AlertDialogAction,
  AlertDialogDescription,
} from "@/components/ui/alert-dialog";
import { Label } from "@/components/ui/label";
import { useAuth } from "@/contexts/AuthContext";
import { toast } from "@/components/ui/sonner";
import { useRolePermissions } from "@/hooks/useRolePermissions";
import { Pencil, Trash2, Filter, X, Download } from "lucide-react";

export default function RWKategoriBiayaPage() {
  const [categories, setCategories] = useState([]);
  const [search, setSearch] = useState("");
  const { token, user, logout } = useAuth();
  const { canCreate, canEdit, canDelete } = useRolePermissions(user?.role, token);

  // FORM DIALOG
  const [openForm, setOpenForm] = useState(false);
  const [formData, setFormData] = useState({
    id: null,
    nama: "",
    tipe: "Pengeluaran",
    pasangan_id: null,
  });

  // DELETE DIALOG
  const [openDelete, setOpenDelete] = useState(false);
  const [deleteId, setDeleteId] = useState(null);

  // FILTER
  const [showFilter, setShowFilter] = useState(false);
  const [filterTipe, setFilterTipe] = useState("all");

  // PAGINATION
  const [page, setPage] = useState(1);
  const [perPage, setPerPage] = useState(25);
  const [importing, setImporting] = useState(false);

  // LOAD DATA
  const loadCategories = async () => {
    try {
      const res = await fetch(`${API_BASE_URL}/api/finance-category`, {
        headers: {
          Authorization: `Bearer ${token}`,
        },
      });

      if (res.status === 401) {
        logout();
        return;
      }

      const data = await res.json();
      setCategories(data);
    } catch (err) {
      console.error("Gagal load kategori", err);
      toast.error("Gagal memuat data kategori");
    }
  };

  useEffect(() => {
    loadCategories();
  }, []);

  // FILTER LOGIC
  const filtered = categories
    .filter((c) => c.nama.toLowerCase().includes(search.toLowerCase()))
    .filter((c) => {
      if (filterTipe === "Pemasukan") return c.tipe === "Pemasukan";
      if (filterTipe === "Pengeluaran") return c.tipe === "Pengeluaran";
      if (filterTipe === "FUND") return c.tipe === "FUND";
      if (filterTipe === "THR") return c.tipe === "THR";
      return true;
    });

  // PAGINATION
  const totalPages = Math.ceil(filtered.length / perPage);
  const paginatedData = filtered.slice((page - 1) * perPage, page * perPage);

  // HANDLE SAVE
  const handleSave = async () => {
    if (!formData.nama || !formData.tipe) {
      toast.error("Nama dan Tipe harus diisi");
      return;
    }

    try {
      const url = formData.id
        ? `${API_BASE_URL}/api/finance-category/${formData.id}`
        : `${API_BASE_URL}/api/finance-category`;

      const method = formData.id ? "PUT" : "POST";

      const res = await fetch(url, {
        method,
        headers: {
          "Content-Type": "application/json",
          Authorization: `Bearer ${token}`,
        },
        body: JSON.stringify({
          nama: formData.nama,
          tipe: formData.tipe,
          pasangan_id: formData.pasangan_id || null,
        }),
      });

      if (res.ok) {
        toast.success(`Kategori berhasil ${formData.id ? "diupdate" : "ditambahkan"}`);
        loadCategories();
        setOpenForm(false);
        resetForm();
      } else {
        const error = await res.json();
        toast.error(error.detail || "Gagal menyimpan kategori");
      }
    } catch (err) {
      console.error("Error:", err);
      toast.error("Terjadi kesalahan saat menyimpan");
    }
  };

  // HANDLE DELETE
  const handleDelete = async () => {
    try {
      const res = await fetch(`${API_BASE_URL}/api/finance-category/${deleteId}`, {
        method: "DELETE",
        headers: {
          Authorization: `Bearer ${token}`,
        },
      });

      if (res.ok) {
        toast.success("Kategori berhasil dihapus");
        loadCategories();
      } else {
        const error = await res.json();
        toast.error(error.detail || "Gagal menghapus kategori");
      }
    } catch (err) {
      console.error("Error:", err);
      toast.error("Terjadi kesalahan saat menghapus");
    } finally {
      setOpenDelete(false);
      setDeleteId(null);
    }
  };

  const handleImportTemplate = async () => {
    setImporting(true);
    try {
      const res = await fetch(`${API_BASE_URL}/api/finance-category/import-templates`, {
        method: "POST",
        headers: { Authorization: `Bearer ${token}` },
      });
      if (res.ok) {
        const d = await res.json();
        toast.success(`Template berhasil diimpor (${d.added} kategori ditambahkan, ${d.skipped} sudah ada)`);
        loadCategories();
      } else {
        const e = await res.json();
        toast.error(e.detail || "Gagal mengimpor template");
      }
    } catch {
      toast.error("Terjadi kesalahan saat mengimpor template");
    } finally {
      setImporting(false);
    }
  };

  const resetForm = () => {
    setFormData({
      id: null,
      nama: "",
      tipe: "Pengeluaran",
      pasangan_id: null,
    });
  };

  const openEditForm = (category) => {
    setFormData({
      id: category.id,
      nama: category.nama,
      tipe: category.tipe,
      pasangan_id: category.pasangan_id || null,
    });
    setOpenForm(true);
  };

  const openDeleteDialog = (id) => {
    setDeleteId(id);
    setOpenDelete(true);
  };

  return (
    <div className="p-6 space-y-6 bg-[#efe7d2] dark:bg-gray-900 min-h-full">
      {/* Breadcrumb */}
      <div className="flex items-center gap-2 text-sm text-gray-500 dark:text-gray-400">
        <span>RW</span><span>/</span>
        <span className="text-gray-700 dark:text-gray-300 font-medium">Kategori Biaya</span>
      </div>

      {/* HEADER */}
      <div className="flex justify-between items-center">
        <div>
          <h1 className="text-3xl font-bold dark:text-gray-100">Kategori Biaya RW</h1>
          <p className="text-sm text-gray-600 dark:text-gray-400">
            Kelola kategori pemasukan dan pengeluaran untuk Kas RW
          </p>
        </div>
        <div className="flex gap-2">
          {canCreate("rw-kategori-biaya") && (
            <Button
              variant="outline"
              onClick={handleImportTemplate}
              disabled={importing}
              className="gap-2"
            >
              <Download className="h-4 w-4" />
              {importing ? "Mengimpor..." : "Gunakan Template"}
            </Button>
          )}
          {canCreate("rw-kategori-biaya") && (
            <Button
              onClick={() => {
                resetForm();
                setOpenForm(true);
              }}
              className="bg-[#ed6f5c] hover:bg-[#e05544] text-white"
            >
              + Tambah Kategori
            </Button>
          )}
        </div>
      </div>

      {/* SEARCH & FILTER */}
      <div className="bg-[#f7f1de] dark:bg-gray-900 p-4 rounded-lg border dark:border-gray-700 space-y-3">
        <div className="flex gap-3 items-center">
          <Input
            placeholder="Cari nama kategori..."
            value={search}
            onChange={(e) => setSearch(e.target.value)}
            className="max-w-sm"
          />
          <Button
            variant="outline"
            onClick={() => setShowFilter(!showFilter)}
            className="gap-2"
          >
            <Filter className="h-4 w-4" />
            Filter
          </Button>
        </div>

        {showFilter && (
          <div className="flex gap-3 items-center pt-2 border-t dark:border-gray-700">
            <Label className="text-sm">Tipe:</Label>
            <Select value={filterTipe} onValueChange={setFilterTipe}>
              <SelectTrigger className="w-48">
                <SelectValue />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="all">Semua Tipe</SelectItem>
                <SelectItem value="Pemasukan">Pemasukan</SelectItem>
                <SelectItem value="Pengeluaran">Pengeluaran</SelectItem>
                <SelectItem value="FUND">FUND</SelectItem>
                <SelectItem value="THR">THR</SelectItem>
              </SelectContent>
            </Select>
            {filterTipe !== "all" && (
              <Button
                variant="ghost"
                size="sm"
                onClick={() => setFilterTipe("all")}
                className="gap-1"
              >
                <X className="h-4 w-4" />
                Reset
              </Button>
            )}
          </div>
        )}
      </div>

      {/* TABLE */}
      <div className="bg-[#f7f1de] dark:bg-gray-900 rounded-lg border dark:border-gray-700">
        <Table>
          <TableHeader>
            <TableRow>
              <TableHead>Nama Kategori</TableHead>
              <TableHead>Tipe</TableHead>
              <TableHead>Pasangan Pos</TableHead>
              <TableHead className="text-right">Aksi</TableHead>
            </TableRow>
          </TableHeader>
          <TableBody>
            {paginatedData.length === 0 ? (
              <TableRow>
                <TableCell colSpan={4} className="text-center text-gray-500">
                  Tidak ada data kategori
                </TableCell>
              </TableRow>
            ) : (
              paginatedData.map((category) => {
                const pasangan = category.pasangan_id
                  ? categories.find((c) => c.id === category.pasangan_id)
                  : null;
                return (
                  <TableRow key={category.id}>
                    <TableCell className="font-medium">{category.nama}</TableCell>
                    <TableCell>
                      <span
                        className={`px-2 py-1 rounded text-xs font-semibold ${
                          category.tipe === "Pemasukan"
                            ? "bg-green-100 text-green-700 dark:bg-green-900 dark:text-green-300"
                            : category.tipe === "Pengeluaran"
                            ? "bg-red-100 text-red-700 dark:bg-red-900 dark:text-red-300"
                            : "bg-blue-100 text-blue-700 dark:bg-blue-900 dark:text-blue-300"
                        }`}
                      >
                        {category.tipe}
                      </span>
                    </TableCell>
                    <TableCell className="text-sm text-gray-500 dark:text-gray-400">
                      {pasangan ? (
                        <span className="flex items-center gap-1">
                          <span className="text-gray-400">↔</span>
                          {pasangan.nama}
                        </span>
                      ) : (
                        <span className="text-gray-300 dark:text-gray-600">—</span>
                      )}
                    </TableCell>
                    <TableCell className="text-right space-x-2">
                      {canEdit("rw-kategori-biaya") && (
                        <Button
                          variant="ghost"
                          size="sm"
                          onClick={() => openEditForm(category)}
                        >
                          <Pencil className="h-4 w-4" />
                        </Button>
                      )}
                      {canDelete("rw-kategori-biaya") && (
                        <Button
                          variant="ghost"
                          size="sm"
                          onClick={() => openDeleteDialog(category.id)}
                        >
                          <Trash2 className="h-4 w-4 text-red-500" />
                        </Button>
                      )}
                    </TableCell>
                  </TableRow>
                );
              })
            )}
          </TableBody>
        </Table>

        {/* PAGINATION */}
        {totalPages > 1 && (
          <div className="p-4 border-t dark:border-gray-700 flex justify-between items-center">
            <p className="text-sm text-gray-600 dark:text-gray-400">
              Halaman {page} dari {totalPages} ({filtered.length} total)
            </p>
            <div className="flex gap-2">
              <Button
                variant="outline"
                size="sm"
                disabled={page === 1}
                onClick={() => setPage(page - 1)}
              >
                Previous
              </Button>
              <Button
                variant="outline"
                size="sm"
                disabled={page === totalPages}
                onClick={() => setPage(page + 1)}
              >
                Next
              </Button>
            </div>
          </div>
        )}
      </div>

      {/* FORM DIALOG */}
      <Dialog open={openForm} onOpenChange={setOpenForm}>
        <DialogContent>
          <DialogHeader>
            <DialogTitle>
              {formData.id ? "Edit Kategori" : "Tambah Kategori"}
            </DialogTitle>
          </DialogHeader>
          <div className="space-y-4">
            <div>
              <Label htmlFor="nama">Nama Kategori</Label>
              <Input
                id="nama"
                value={formData.nama}
                onChange={(e) => setFormData({ ...formData, nama: e.target.value })}
                placeholder="Contoh: Gaji Security"
              />
            </div>
            <div>
              <Label htmlFor="tipe">Tipe</Label>
              <Select
                value={formData.tipe}
                onValueChange={(value) => setFormData({ ...formData, tipe: value, pasangan_id: null })}
              >
                <SelectTrigger>
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="Pemasukan">Pemasukan</SelectItem>
                  <SelectItem value="Pengeluaran">Pengeluaran</SelectItem>
                  <SelectItem value="FUND">FUND</SelectItem>
                  <SelectItem value="THR">THR</SelectItem>
                </SelectContent>
              </Select>
            </div>
            {(formData.tipe === "Pemasukan" || formData.tipe === "Pengeluaran") && (
              <div>
                <Label htmlFor="pasangan">
                  Pasangan Pos{" "}
                  <span className="text-gray-400 font-normal text-xs">
                    ({formData.tipe === "Pemasukan" ? "pilih kategori pengeluaran terkait" : "pilih kategori pemasukan terkait"})
                  </span>
                </Label>
                <Select
                  value={formData.pasangan_id || "__none__"}
                  onValueChange={(value) =>
                    setFormData({ ...formData, pasangan_id: value === "__none__" ? null : value })
                  }
                >
                  <SelectTrigger>
                    <SelectValue placeholder="— Tidak dipasangkan —" />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value="__none__">— Tidak dipasangkan —</SelectItem>
                    {categories
                      .filter((c) =>
                        formData.tipe === "Pemasukan"
                          ? c.tipe === "Pengeluaran"
                          : c.tipe === "Pemasukan"
                      )
                      .map((c) => (
                        <SelectItem key={c.id} value={c.id}>
                          {c.nama}
                        </SelectItem>
                      ))}
                  </SelectContent>
                </Select>
              </div>
            )}
          </div>
          <DialogFooter>
            <Button variant="outline" onClick={() => setOpenForm(false)}>
              Batal
            </Button>
            <Button onClick={handleSave}>Simpan</Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>

      {/* DELETE CONFIRMATION */}
      <AlertDialog open={openDelete} onOpenChange={setOpenDelete}>
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>Hapus Kategori</AlertDialogTitle>
            <AlertDialogDescription>
              Apakah Anda yakin ingin menghapus kategori ini? Data yang sudah dihapus tidak
              dapat dikembalikan.
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel>Batal</AlertDialogCancel>
            <AlertDialogAction
              onClick={handleDelete}
              className="bg-red-500 hover:bg-red-600"
            >
              Hapus
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </div>
  );
}
