import React, { useState, useEffect } from 'react';
import axios from 'axios';
import { useAuth } from '../../contexts/AuthContext';
import { useRWFilter } from '../../contexts/RWFilterContext';
import { useNavigate } from 'react-router-dom';
import { API_BASE_URL } from '../../config/api';
import { Users, Search, Filter, RefreshCw, MapPin, ChevronLeft, ChevronRight } from 'lucide-react';

const PAGE_SIZE = 15;
import {
  Table, TableBody, TableCell, TableHead, TableHeader, TableRow
} from '@/components/ui/table';
import { Badge } from '@/components/ui/badge';
import { Input } from '@/components/ui/input';
import {
  Select, SelectContent, SelectItem, SelectTrigger, SelectValue
} from '@/components/ui/select';

// Badge warna cycling untuk bantuan sosial
const BANTUAN_COLORS = [
  'bg-blue-100 text-blue-700 dark:bg-blue-900/40 dark:text-blue-300',
  'bg-emerald-100 text-emerald-700 dark:bg-emerald-900/40 dark:text-emerald-300',
  'bg-orange-100 text-orange-700 dark:bg-orange-900/40 dark:text-orange-300',
  'bg-purple-100 text-purple-700 dark:bg-purple-900/40 dark:text-purple-300',
  'bg-amber-100 text-amber-700 dark:bg-amber-900/40 dark:text-amber-300',
  'bg-rose-100 text-rose-700 dark:bg-rose-900/40 dark:text-rose-300',
  'bg-cyan-100 text-cyan-700 dark:bg-cyan-900/40 dark:text-cyan-300',
  'bg-indigo-100 text-indigo-700 dark:bg-indigo-900/40 dark:text-indigo-300',
];

const DataWarga = () => {
  const { token } = useAuth();
  const { rtId } = useRWFilter();
  const navigate = useNavigate();
  const [data, setData] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [search, setSearch] = useState('');
  const [filterStatus, setFilterStatus] = useState('');
  const [filterBlok, setFilterBlok] = useState('');
  const [filterPosisi, setFilterPosisi] = useState('');
  const [currentPage, setCurrentPage] = useState(1);
  const [bantuanOpsi, setBantuanOpsi] = useState([]);

  useEffect(() => {
    fetchData();
    // Fetch bantuan opsi untuk color mapping
    fetch(`${API_BASE_URL}/api/referensi/bantuan-sosial`)
      .then(r => r.json())
      .then(d => setBantuanOpsi(Array.isArray(d) ? d : []))
      .catch(() => {});
  }, [token, rtId]);

  const fetchData = async () => {
    try {
      setLoading(true);
      const headers = { Authorization: `Bearer ${token}` };
      const params = new URLSearchParams();
      if (rtId) params.append('rt_id', rtId);
      if (search) params.append('search', search);
      if (filterStatus) params.append('status', filterStatus);
      if (filterBlok) params.append('rt_blok', filterBlok);
      if (filterPosisi) params.append('posisi_keluarga', filterPosisi);
      const res = await axios.get(`${API_BASE_URL}/api/rw/warga?${params}`, { headers });
      setData(res.data);
      setError(null);
    } catch (err) {
      setError(err.response?.data?.detail || err.message);
    } finally {
      setLoading(false);
    }
  };

  const handleSearch = (e) => {
    e.preventDefault();
    setCurrentPage(1);
    fetchData();
  };

  const handleReset = () => {
    setSearch(''); setFilterStatus(''); setFilterBlok(''); setFilterPosisi('');
    setCurrentPage(1);
    setTimeout(fetchData, 100);
  };

  const getBantuanColor = (nilai) => {
    const idx = bantuanOpsi.findIndex(o => o.nilai === nilai);
    return BANTUAN_COLORS[(idx >= 0 ? idx : 0) % BANTUAN_COLORS.length];
  };

  // Get unique RT list & blok list from data
  const rtList = data?.data
    ? [...new Map(data.data.map(w => [w.rt_name, w.rt_name])).values()].filter(Boolean).sort()
    : [];
  const blokList = data?.data
    ? [...new Set(data.data.map(w => w.rt_blok).filter(Boolean))].sort()
    : [];

  if (loading) {
    return (
      <div className="p-6 bg-[#efe7d2] dark:bg-gray-900 min-h-full flex items-center justify-center">
        <div className="text-center space-y-4">
          <div className="w-12 h-12 border-4 border-cyan-500 border-t-transparent rounded-full animate-spin mx-auto" />
          <p className="text-gray-500 dark:text-gray-400">Memuat data warga...</p>
        </div>
      </div>
    );
  }

  if (error) {
    return (
      <div className="p-6 bg-[#efe7d2] dark:bg-gray-900 min-h-full">
        <div className="bg-red-50 dark:bg-red-900/20 border border-red-200 dark:border-red-800 rounded-lg p-4">
          <p className="text-red-600 dark:text-red-400 text-sm">Error: {error}</p>
        </div>
      </div>
    );
  }

  const wargaList = data?.data || [];
  const totalPages = Math.ceil(wargaList.length / PAGE_SIZE);
  const pageStart = (currentPage - 1) * PAGE_SIZE;
  const pageEnd = pageStart + PAGE_SIZE;
  const pagedList = wargaList.slice(pageStart, pageEnd);

  const goToPage = (p) => setCurrentPage(Math.max(1, Math.min(p, totalPages)));

  const getPageNumbers = () => {
    const pages = [];
    const delta = 2;
    const left = Math.max(1, currentPage - delta);
    const right = Math.min(totalPages, currentPage + delta);
    for (let i = left; i <= right; i++) pages.push(i);
    return pages;
  };

  return (
    <div className="p-6 space-y-6 bg-[#efe7d2] dark:bg-gray-900 min-h-full">
      {/* Breadcrumb */}
      <div className="flex items-center gap-2 text-sm text-gray-500 dark:text-gray-400">
        <span>RW</span><span>/</span>
        <span className="text-gray-700 dark:text-gray-300 font-medium">Data Warga</span>
      </div>

      {/* Header */}
      <div className="flex items-center gap-3">
        <div className="w-10 h-10 bg-gradient-to-br from-blue-500 to-indigo-600 rounded-xl flex items-center justify-center shadow">
          <Users className="h-5 w-5 text-white" />
        </div>
        <div>
          <h1 className="text-2xl font-bold text-gray-900 dark:text-white">Data Warga RW</h1>
          <p className="text-sm text-gray-500 dark:text-gray-400">
            Agregasi seluruh warga dari semua RT — {data?.total || 0} warga
          </p>
        </div>
      </div>

      {/* Summary Cards */}
      <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
        {[
          { label: 'Total Warga', value: data?.total || 0, color: 'from-blue-500 to-indigo-600' },
          { label: 'Warga Aktif', value: wargaList.filter(w => w.status === 'active').length, color: 'from-green-500 to-emerald-600' },
          { label: 'Laki-laki', value: wargaList.filter(w => w.jenis_kelamin === 'Laki-laki').length, color: 'from-cyan-500 to-blue-600' },
          { label: 'Perempuan', value: wargaList.filter(w => w.jenis_kelamin === 'Perempuan').length, color: 'from-pink-500 to-rose-600' },
        ].map((card, i) => (
          <div key={i} className="bg-[#f7f1de] dark:bg-gray-800 rounded-lg shadow p-4 flex items-center gap-3">
            <div className={`w-10 h-10 bg-gradient-to-br ${card.color} rounded-lg flex items-center justify-center`}>
              <Users className="h-5 w-5 text-white" />
            </div>
            <div>
              <p className="text-xs text-gray-500 dark:text-gray-400">{card.label}</p>
              <p className="text-xl font-bold text-gray-900 dark:text-white">{card.value}</p>
            </div>
          </div>
        ))}
      </div>

      {/* Filters */}
      <div className="bg-[#f7f1de] dark:bg-gray-800 rounded-lg shadow p-4">
        <form onSubmit={handleSearch} className="flex flex-wrap gap-3 items-end">
          <div className="flex-1 min-w-[200px]">
            <label className="text-xs text-gray-500 dark:text-gray-400 mb-1 block">Cari Warga</label>
            <div className="relative">
              <Search className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-gray-400" />
              <Input
                placeholder="Nama, blok, atau WhatsApp..."
                value={search}
                onChange={e => setSearch(e.target.value)}
                className="pl-9"
              />
            </div>
          </div>
          <div className="w-36">
            <label className="text-xs text-gray-500 dark:text-gray-400 mb-1 block">Filter Blok RT</label>
            <Select value={filterBlok || "all"} onValueChange={(val) => setFilterBlok(val === "all" ? "" : val)}>
              <SelectTrigger><SelectValue placeholder="Semua Blok" /></SelectTrigger>
              <SelectContent>
                <SelectItem value="all">Semua Blok</SelectItem>
                {blokList.map(b => (
                  <SelectItem key={b} value={b}>Blok {b}</SelectItem>
                ))}
              </SelectContent>
            </Select>
          </div>
          <div className="w-36">
            <label className="text-xs text-gray-500 dark:text-gray-400 mb-1 block">Status</label>
            <Select value={filterStatus || "all"} onValueChange={(val) => setFilterStatus(val === "all" ? "" : val)}>
              <SelectTrigger><SelectValue placeholder="Semua Status" /></SelectTrigger>
              <SelectContent>
                <SelectItem value="all">Semua Status</SelectItem>
                <SelectItem value="active">Aktif</SelectItem>
                <SelectItem value="inactive">Tidak Aktif</SelectItem>
              </SelectContent>
            </Select>
          </div>
          <div className="w-44">
            <label className="text-xs text-gray-500 dark:text-gray-400 mb-1 block">Posisi Keluarga</label>
            <Select value={filterPosisi || "all"} onValueChange={(val) => setFilterPosisi(val === "all" ? "" : val)}>
              <SelectTrigger><SelectValue placeholder="Semua Posisi" /></SelectTrigger>
              <SelectContent>
                <SelectItem value="all">Semua Posisi</SelectItem>
                <SelectItem value="Kepala Keluarga">Kepala Keluarga</SelectItem>
                <SelectItem value="Istri">Istri</SelectItem>
                <SelectItem value="Anak">Anak</SelectItem>
              </SelectContent>
            </Select>
          </div>
          <div className="flex gap-2">
            <button type="submit"
              className="px-4 py-2 bg-[#ed6f5c] hover:bg-[#e05544] text-white text-sm rounded-lg transition-colors flex items-center gap-2">
              <Filter className="h-4 w-4" />Filter
            </button>
            <button type="button" onClick={handleReset}
              className="px-4 py-2 bg-gray-100 dark:bg-gray-700 hover:bg-gray-200 dark:hover:bg-gray-600 text-gray-700 dark:text-gray-300 text-sm rounded-lg transition-colors flex items-center gap-2">
              <RefreshCw className="h-4 w-4" />Reset
            </button>
          </div>
        </form>
      </div>

      {/* Table */}
      <div className="bg-[#f7f1de] dark:bg-gray-800 rounded-lg shadow overflow-hidden">
        <div className="p-4 border-b border-[#d5cebc] dark:border-gray-700 flex items-center justify-between">
          <h3 className="text-base font-semibold text-gray-900 dark:text-gray-100">Daftar Warga</h3>
          <span className="text-sm text-gray-500 dark:text-gray-400">
            {wargaList.length > 0
              ? `${pageStart + 1}–${Math.min(pageEnd, wargaList.length)} dari ${wargaList.length} warga`
              : '0 warga'}
          </span>
        </div>

        {wargaList.length > 0 ? (
          <div className="overflow-x-auto">
            <Table>
              <TableHeader>
                <TableRow>
                  <TableHead>Nama Lengkap</TableHead>
                  <TableHead>Blok Rumah</TableHead>
                  <TableHead>RT</TableHead>
                  <TableHead>Jenis Kelamin</TableHead>
                  <TableHead>Posisi Keluarga</TableHead>
                  <TableHead>WhatsApp</TableHead>
                  <TableHead>Strata Ekonomi</TableHead>
                  <TableHead>Bantuan Sosial</TableHead>
                  <TableHead className="text-center">Status</TableHead>
                </TableRow>
              </TableHeader>
              <TableBody>
                {pagedList.map((w) => (
                  <TableRow key={w.id}>
                    <TableCell className="font-medium text-gray-900 dark:text-white">
                      {w.nama_lengkap}
                    </TableCell>
                    <TableCell>
                      {w.blok_rumah ? (
                        <button
                          onClick={() => navigate(`/rw/citizens/${w.id}`)}
                          className="font-medium text-[#ed6f5c] hover:text-[#e05544] hover:underline transition-colors"
                        >
                          {w.blok_rumah}
                        </button>
                      ) : '-'}
                    </TableCell>
                    <TableCell>
                      {w.rt_name && w.rt_name !== '-' ? (
                        <div className="flex items-center gap-1">
                          <MapPin className="h-3 w-3 text-blue-500 flex-shrink-0" />
                          <span className="text-sm font-medium text-blue-700 dark:text-blue-400">
                            {w.rt_name}
                          </span>
                        </div>
                      ) : '-'}
                    </TableCell>
                    <TableCell>{w.jenis_kelamin || '-'}</TableCell>
                    <TableCell>{w.posisi_keluarga || '-'}</TableCell>
                    <TableCell className="text-sm text-gray-500 dark:text-gray-400">
                      {w.whatsapp ? `${w.country_code || '+62'}${w.whatsapp}` : '-'}
                    </TableCell>
                    <TableCell>
                      {w.strata_ekonomi ? (
                        <span className="px-2 py-0.5 rounded-full text-xs font-semibold bg-blue-50 text-blue-700 border border-blue-200 dark:bg-blue-900/20 dark:text-blue-300 dark:border-blue-800">
                          {w.strata_ekonomi}
                        </span>
                      ) : (
                        <span className="text-gray-300 dark:text-gray-600 text-xs">—</span>
                      )}
                    </TableCell>
                    <TableCell>
                      {w.bantuan_diterima && w.bantuan_diterima.length > 0 ? (
                        <div className="flex flex-wrap gap-1">
                          {w.bantuan_diterima.map((b, bi) => (
                            <span key={b} className={`px-1.5 py-0.5 rounded text-[10px] font-semibold ${getBantuanColor(b)}`}>
                              {b}
                            </span>
                          ))}
                        </div>
                      ) : (
                        <span className="text-gray-300 dark:text-gray-600 text-xs">—</span>
                      )}
                    </TableCell>
                    <TableCell className="text-center">
                      <Badge
                        variant="outline"
                        className={w.status === 'active'
                          ? 'border-green-500 text-green-600 bg-green-50 dark:bg-green-900/20'
                          : 'border-gray-400 text-gray-500 bg-[#ece4cf] dark:bg-gray-700'
                        }
                      >
                        {w.status === 'active' ? 'Aktif' : 'Tidak Aktif'}
                      </Badge>
                    </TableCell>
                  </TableRow>
                ))}
              </TableBody>
            </Table>
          </div>
        ) : (
          <div className="text-center py-12">
            <Users className="h-12 w-12 text-gray-300 dark:text-gray-600 mx-auto mb-3" />
            <p className="text-gray-500 dark:text-gray-400">Tidak ada warga ditemukan</p>
          </div>
        )}

        {/* Pagination */}
        {totalPages > 1 && (
          <div className="px-4 py-3 border-t border-[#d5cebc] dark:border-gray-700 flex items-center justify-between">
            <span className="text-sm text-gray-500 dark:text-gray-400">
              Halaman {currentPage} dari {totalPages}
            </span>
            <div className="flex items-center gap-1">
              <button onClick={() => goToPage(currentPage - 1)} disabled={currentPage === 1}
                className="p-1.5 rounded-md hover:bg-[#e4dcc8] dark:hover:bg-gray-700 disabled:opacity-40 disabled:cursor-not-allowed transition-colors">
                <ChevronLeft className="h-4 w-4 text-gray-600 dark:text-gray-400" />
              </button>
              {currentPage > 3 && (
                <>
                  <button onClick={() => goToPage(1)} className="w-8 h-8 text-sm rounded-md hover:bg-[#e4dcc8] dark:hover:bg-gray-700 text-gray-600 dark:text-gray-400 transition-colors">1</button>
                  {currentPage > 4 && <span className="px-1 text-gray-400">…</span>}
                </>
              )}
              {getPageNumbers().map(p => (
                <button key={p} onClick={() => goToPage(p)}
                  className={`w-8 h-8 text-sm rounded-md transition-colors font-medium ${
                    p === currentPage
                      ? 'bg-[#ed6f5c] text-white'
                      : 'hover:bg-[#e4dcc8] dark:hover:bg-gray-700 text-gray-600 dark:text-gray-400'
                  }`}>
                  {p}
                </button>
              ))}
              {currentPage < totalPages - 2 && (
                <>
                  {currentPage < totalPages - 3 && <span className="px-1 text-gray-400">…</span>}
                  <button onClick={() => goToPage(totalPages)} className="w-8 h-8 text-sm rounded-md hover:bg-[#e4dcc8] dark:hover:bg-gray-700 text-gray-600 dark:text-gray-400 transition-colors">{totalPages}</button>
                </>
              )}
              <button onClick={() => goToPage(currentPage + 1)} disabled={currentPage === totalPages}
                className="p-1.5 rounded-md hover:bg-[#e4dcc8] dark:hover:bg-gray-700 disabled:opacity-40 disabled:cursor-not-allowed transition-colors">
                <ChevronRight className="h-4 w-4 text-gray-600 dark:text-gray-400" />
              </button>
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

export default DataWarga;
