import { useEffect, useState } from "react";

import { API_BASE_URL, API_ENDPOINTS } from "@/config/api";
import { useLocation } from "react-router-dom";
import ImportExcelModal from "@/components/ImportExcelModal";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import WargaTable from "./WargaTable";
import WargaForm from "./WargaForm";
import {
  AlertDialog,
  AlertDialogContent,
  AlertDialogHeader,
  AlertDialogFooter,
  AlertDialogTitle,
  AlertDialogCancel,
  AlertDialogAction
} from "@/components/ui/alert-dialog";
import { useAuth } from "@/contexts/AuthContext";
import { toast } from "@/components/ui/sonner";
import { useRolePermissions } from "@/hooks/useRolePermissions";

export default function WargaPage() {
  const location = useLocation();
  const [data, setData] = useState([]);
  const [search, setSearch] = useState("");
  const { token, logout, user } = useAuth();
  const { canCreate, canDelete } = useRolePermissions(user?.role, token);

  // FORM
  const [openForm, setOpenForm] = useState(false);
  const [selectedWarga, setSelectedWarga] = useState(null);

  // MULTI SELECT
  const [selectedRows, setSelectedRows] = useState([]);

  // FILTER
  const [showFilter, setShowFilter] = useState(false);
  const [filterStatus, setFilterStatus] = useState("all");
  const [filterGender, setFilterGender] = useState("all");

  // PAGINATION
  const [page, setPage] = useState(1);
  const [perPage, setPerPage] = useState(5);

  // BULK DELETE DIALOG
  const [openBulkDelete, setOpenBulkDelete] = useState(false);

  // IMPORT EXCEL
  const [showImportModal, setShowImportModal] = useState(false);

  const loadWarga = async () => {
    try {
      const res = await fetch(`${API_BASE_URL}/api/warga`, {
        headers: {
          Authorization: `Bearer ${token}`,
        },
      });

      if (res.status === 401) {
        logout();
        return;
      }

      const json = await res.json();
      setData(json);
    } catch (err) {
      console.error("Gagal load warga", err);
      toast.error("Gagal memuat data warga");
    }
  };

  useEffect(() => {
    loadWarga();
  }, []);

  // Auto-search dari state (misal dari IPL page)
  useEffect(() => {
    if (location.state?.searchName) {
      setSearch(location.state.searchName);
    }
  }, [location.state?.searchName]);

  // FILTER LOGIC
  const filtered = data
    .filter((w) =>
      w.nama_lengkap.toLowerCase().includes(search.toLowerCase())
    )
    .filter((w) => {
      if (filterStatus === "active") return w.status === "active";
      if (filterStatus === "inactive") return w.status === "inactive";
      return true;
    })
    .filter((w) => {
      if (filterGender === "L") return w.jenis_kelamin === "Laki-laki";
      if (filterGender === "P") return w.jenis_kelamin === "Perempuan";
      return true;
    });

  // PAGINATION
  const totalPages = Math.ceil(filtered.length / perPage);
  const paginatedData = filtered.slice((page - 1) * perPage, page * perPage);

  // EXPORT EXCEL
  const [exporting, setExporting] = useState(false);
  const exportExcel = async () => {
    setExporting(true);
    try {
      const res = await fetch(API_ENDPOINTS.EXPORT_EXCEL_WARGA, {
        headers: { Authorization: `Bearer ${token}` },
      });
      if (res.status === 401) { logout(); return; }
      if (!res.ok) throw new Error(`HTTP ${res.status}`);
      const blob = await res.blob();
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = `daftar-warga-${new Date().toISOString().slice(0, 10)}.xlsx`;
      a.click();
      URL.revokeObjectURL(url);
    } catch (err) {
      console.error('Gagal export warga', err);
      toast.error('Gagal mengekspor data warga');
    } finally {
      setExporting(false);
    }
  };

  // BULK DELETE
  const doBulkDelete = async () => {
    for (const id of selectedRows) {
      await fetch(`${API_BASE_URL}/api/warga/${id}`, {
        method: "DELETE",
        headers: {
          Authorization: `Bearer ${token}`,
        },
      });
    }
    toast.success(`${selectedRows.length} warga berhasil dihapus`);
    loadWarga();
    setSelectedRows([]);
    setOpenBulkDelete(false);
  };

  return (
    <div className="p-6 space-y-4">
      {/* HEADER */}
      <div className="flex justify-between items-center">
        <div>
          <h1 className="text-3xl font-bold dark:text-gray-100">
            {user?.role === "warga" ? "Data Keluarga Saya" : "Daftar Warga"}
          </h1>
          <p className="text-sm text-gray-600 dark:text-gray-400">
            {user?.role === "warga" ? "Anggota keluarga di rumah Anda" : "Kelola data warga"}
          </p>
        </div>
        <div className="flex gap-2">
          {user?.role !== "warga" && (
          <Button
            variant="outline"
            onClick={exportExcel}
            disabled={exporting}
            className="border-blue-600 text-blue-700 hover:bg-blue-50 dark:border-blue-500 dark:text-blue-400"
          >
            {exporting ? "Mengekspor..." : "⬇ Export Excel"}
          </Button>
          )}
          {canCreate('warga') && (
            <>
              <Button
                variant="outline"
                onClick={() => setShowImportModal(true)}
                className="border-green-600 text-green-700 hover:bg-green-50 dark:border-green-500 dark:text-green-400"
              >
                ⬆ Import Excel
              </Button>
              <Button
                onClick={() => {
                  setSelectedWarga(null);
                  setOpenForm(true);
                }}
                className="bg-[#ed6f5c] hover:bg-[#e05544] text-white"
              >
                + Tambah Warga
              </Button>
            </>
          )}
        </div>
      </div>

      {/* SEARCH & FILTER */}
      <div className="flex gap-3">
        <Input
          placeholder="Cari nama warga..."
          value={search}
          onChange={(e) => {
            setSearch(e.target.value);
            setPage(1);
          }}
          className="flex-1 dark:bg-gray-800 dark:text-gray-100 dark:border-gray-700"
        />
        <Button
          variant="outline"
          onClick={() => setShowFilter(!showFilter)}
          className="dark:border-gray-700 dark:text-gray-200"
        >
          Filter
        </Button>
      </div>

      {/* FILTER PANEL */}
      {showFilter && (
        <div className="bg-[#f7f1de] dark:bg-gray-900 p-6 rounded-lg border dark:border-gray-700 space-y-4">
          <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
            {/* STATUS */}
            <div>
              <label className="text-xs font-semibold text-gray-500 dark:text-gray-400 uppercase">Status</label>
              <select
                value={filterStatus}
                onChange={(e) => {
                  setFilterStatus(e.target.value);
                  setPage(1);
                }}
                className="w-full p-2 mt-2 border rounded-md dark:bg-gray-800 dark:border-gray-700 dark:text-gray-100 bg-[#ece4cf]"
              >
                <option value="all">Semua</option>
                <option value="active">Aktif</option>
                <option value="inactive">Tidak Aktif</option>
              </select>
            </div>

            {/* JENIS KELAMIN */}
            <div>
              <label className="text-xs font-semibold text-gray-500 dark:text-gray-400 uppercase">Jenis Kelamin</label>
              <select
                value={filterGender}
                onChange={(e) => {
                  setFilterGender(e.target.value);
                  setPage(1);
                }}
                className="w-full p-2 mt-2 border rounded-md dark:bg-gray-800 dark:border-gray-700 dark:text-gray-100 bg-[#ece4cf]"
              >
                <option value="all">Semua</option>
                <option value="L">Laki-laki</option>
                <option value="P">Perempuan</option>
              </select>
            </div>

            {/* PER HALAMAN */}
            <div>
              <label className="text-xs font-semibold text-gray-500 dark:text-gray-400 uppercase">Per Halaman</label>
              <select
                value={perPage}
                onChange={(e) => {
                  setPerPage(Number(e.target.value));
                  setPage(1);
                }}
                className="w-full p-2 mt-2 border rounded-md dark:bg-gray-800 dark:border-gray-700 dark:text-gray-100 bg-[#ece4cf]"
              >
                <option value="5">5</option>
                <option value="10">10</option>
                <option value="25">25</option>
              </select>
            </div>
          </div>
        </div>
      )}

      {/* ACTIONS */}
      {selectedRows.length > 0 && canDelete('warga') && (
        <div className="flex gap-3 bg-blue-50 dark:bg-blue-900/20 p-4 rounded-lg border border-blue-200 dark:border-blue-800">
          <span className="text-sm dark:text-gray-300">
            {selectedRows.length} item dipilih
          </span>
          <Button
            size="sm"
            variant="destructive"
            onClick={() => setOpenBulkDelete(true)}
          >
            Hapus
          </Button>
          {user?.role !== "warga" && (
          <Button
            size="sm"
            onClick={exportExcel}
            className="bg-green-500 hover:bg-green-600 text-white"
          >
            Export Excel
          </Button>
          )}
        </div>
      )}

      {/* TABLE */}
      <div className="bg-[#f7f1de] dark:bg-gray-900 rounded-lg border dark:border-gray-700">
        <WargaTable
          data={paginatedData}
          onEdit={(w) => {
            setSelectedWarga(w);
            setOpenForm(true);
          }}
          onDelete={loadWarga}
          selectedRows={selectedRows}
          setSelectedRows={setSelectedRows}
        />
      </div>

      {/* PAGINATION INFO */}
      <div className="flex justify-between items-center text-sm text-gray-600 dark:text-gray-400 px-2">
        <span>
          {filtered.length === 0 ? "Tidak ada data" : `${(page - 1) * perPage + 1}-${Math.min(page * perPage, filtered.length)} dari ${filtered.length}`}
        </span>
        <div className="flex gap-2">
          <Button
            size="sm"
            variant="outline"
            onClick={() => setPage(Math.max(1, page - 1))}
            disabled={page === 1}
            className="dark:border-gray-700 dark:text-gray-200"
          >
            Sebelumnya
          </Button>
          <Button
            size="sm"
            variant="outline"
            onClick={() => setPage(Math.min(totalPages, page + 1))}
            disabled={page === totalPages}
            className="dark:border-gray-700 dark:text-gray-200"
          >
            Selanjutnya
          </Button>
        </div>
      </div>

      {/* FORM DIALOG */}
      <WargaForm
        open={openForm}
        onOpenChange={setOpenForm}
        warga={selectedWarga}
        onSaved={() => {
          loadWarga();
          setSelectedWarga(null);
        }}
      />

      {/* BULK DELETE DIALOG */}
      <AlertDialog open={openBulkDelete} onOpenChange={setOpenBulkDelete}>
        <AlertDialogContent className="bg-[#f7f1de] dark:bg-gray-900 dark:text-gray-100">
          <AlertDialogHeader>
            <AlertDialogTitle>Hapus {selectedRows.length} Warga?</AlertDialogTitle>
          </AlertDialogHeader>
          <p className="text-sm text-gray-600 dark:text-gray-400">
            Tindakan ini tidak dapat dibatalkan.
          </p>
          <AlertDialogFooter>
            <AlertDialogCancel className="dark:bg-gray-800 dark:text-gray-200">
              Batal
            </AlertDialogCancel>
            <AlertDialogAction
              onClick={doBulkDelete}
              className="bg-red-600 hover:bg-red-700"
            >
              Hapus Semua
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>

      {/* IMPORT EXCEL MODAL */}
      <ImportExcelModal
        show={showImportModal}
        onClose={() => setShowImportModal(false)}
        onImported={loadWarga}
        title="Import Data Warga dari Excel"
        templateUrl={API_ENDPOINTS.IMPORT_EXCEL_TEMPLATE_WARGA}
        importUrl={API_ENDPOINTS.IMPORT_EXCEL_WARGA}
        templateName="template_warga.xlsx"
        columns={[
          'Nama Lengkap *', 'No WhatsApp', 'Tanggal Lahir', 'Tempat Lahir',
          'Jenis Kelamin', 'Agama', 'Pekerjaan', 'Posisi Keluarga',
          'Blok/No Rumah', 'Status', 'Strata Ekonomi', 'Bantuan Diterima',
        ]}
      />
    </div>
  );
}
