import React, { useState, useEffect, useRef, useCallback } from 'react';
import { useNavigate } from 'react-router-dom';
import { useAuth } from '@/contexts/AuthContext';
import { API_BASE_URL } from '@/config/api';
import { toast } from '@/components/ui/sonner';
import { Siren, CheckCircle, CircleCheck, Clock, MapPin, MessageSquare, RefreshCw, ArrowLeft } from 'lucide-react';
import { Badge } from '@/components/ui/badge';

const STATUS_META = {
  active:       { label: 'Aktif',       cls: 'bg-red-100 text-red-700 border-red-200',           dot: 'bg-red-500' },
  acknowledged: { label: 'Ditangani',   cls: 'bg-yellow-100 text-yellow-700 border-yellow-200',  dot: 'bg-yellow-500' },
  resolved:     { label: 'Selesai',     cls: 'bg-green-100 text-green-700 border-green-200',      dot: 'bg-green-500' },
};

function timeSince(isoStr) {
  if (!isoStr) return '-';
  const diff = Date.now() - new Date(isoStr).getTime();
  const s = Math.floor(diff / 1000);
  if (s < 60)   return `${s} detik lalu`;
  const m = Math.floor(s / 60);
  if (m < 60)   return `${m} menit lalu`;
  const h = Math.floor(m / 60);
  if (h < 24)   return `${h} jam lalu`;
  return new Date(isoStr).toLocaleDateString('id-ID', { day: '2-digit', month: 'short', year: 'numeric', hour: '2-digit', minute: '2-digit' });
}

const IS_ADMIN_ROLE = (role) => ['admin', 'pengurus_rw', 'pengurus_kelurahan'].includes(role);

export default function PanicAlertsPage() {
  const { token, user } = useAuth();
  const navigate        = useNavigate();
  const isAdmin         = IS_ADMIN_ROLE(user?.role);

  const [alerts, setAlerts]     = useState([]);
  const [filter, setFilter]     = useState('all');
  const [loading, setLoading]   = useState(true);
  const [actLoading, setActLoading] = useState({});
  const pollRef = useRef(null);

  const loadAlerts = useCallback(async () => {
    if (!token) return;
    try {
      const res = await fetch(
        `${API_BASE_URL}/api/panic-button/alerts?status=${filter}`,
        { headers: { Authorization: `Bearer ${token}` }, cache: 'no-store' }
      );
      if (res.ok) {
        const data = await res.json();
        setAlerts(data);
      }
    } catch { /* silent */ } finally {
      setLoading(false);
    }
  }, [token, filter]);

  useEffect(() => {
    setLoading(true);
    loadAlerts();
  }, [loadAlerts]);

  // Auto-refresh setiap 5 detik jika ada alert active
  useEffect(() => {
    if (pollRef.current) clearInterval(pollRef.current);
    const hasActive = alerts.some(a => a.status === 'active');
    if (hasActive) {
      pollRef.current = setInterval(loadAlerts, 5000);
    }
    return () => { if (pollRef.current) clearInterval(pollRef.current); };
  }, [alerts, loadAlerts]);

  const doAction = async (alertId, action) => {
    setActLoading(p => ({ ...p, [alertId]: action }));
    try {
      const res = await fetch(`${API_BASE_URL}/api/panic-button/${alertId}/${action}`, {
        method:  'PUT',
        headers: { Authorization: `Bearer ${token}` },
      });
      const data = await res.json();
      if (!res.ok) { toast.error(data.detail || 'Gagal'); return; }
      toast.success(action === 'acknowledge' ? 'Alert ditandai ditangani' : 'Alert diselesaikan');
      loadAlerts();
    } catch {
      toast.error('Gagal menghubungi server');
    } finally {
      setActLoading(p => ({ ...p, [alertId]: null }));
    }
  };

  const activeCount = alerts.filter(a => a.status === 'active').length;

  return (
    <div className="p-6 space-y-5 bg-[#f7f1de] dark:bg-gray-900 min-h-full">
      {/* Header */}
      <div className="flex items-center gap-3">
        <button onClick={() => navigate(-1)}
          className="p-2 rounded-lg bg-white dark:bg-gray-800 shadow-sm hover:bg-gray-100 dark:hover:bg-gray-700">
          <ArrowLeft size={18} className="text-gray-600 dark:text-gray-400" />
        </button>
        <div className="flex items-center gap-3 flex-1">
          <div className="w-10 h-10 rounded-xl bg-red-600 flex items-center justify-center shadow">
            <Siren size={20} className="text-white" />
          </div>
          <div>
            <h1 className="text-2xl font-bold text-gray-900 dark:text-white flex items-center gap-2">
              Alert Darurat
              {activeCount > 0 && (
                <span className="inline-flex items-center justify-center w-6 h-6 rounded-full bg-red-600 text-white text-xs font-bold animate-bounce">
                  {activeCount}
                </span>
              )}
            </h1>
            <p className="text-sm text-gray-500 dark:text-gray-400">
              {isAdmin ? 'Kelola laporan darurat warga' : 'Riwayat alert darurat yang Anda kirim'}
            </p>
          </div>
        </div>
        <button onClick={loadAlerts}
          className="p-2 rounded-lg bg-white dark:bg-gray-800 shadow-sm hover:bg-gray-100 dark:hover:bg-gray-700"
          title="Refresh">
          <RefreshCw size={16} className="text-gray-500" />
        </button>
      </div>

      {/* Filter tabs */}
      <div className="flex gap-2 flex-wrap">
        {[
          { key: 'all',          label: 'Semua' },
          { key: 'active',       label: 'Aktif' },
          { key: 'acknowledged', label: 'Ditangani' },
          { key: 'resolved',     label: 'Selesai' },
        ].map(f => (
          <button key={f.key} onClick={() => setFilter(f.key)}
            className={`px-4 py-1.5 rounded-full text-sm font-medium transition-colors
              ${filter === f.key
                ? 'bg-red-600 text-white shadow'
                : 'bg-white dark:bg-gray-800 text-gray-600 dark:text-gray-300 hover:bg-red-50 dark:hover:bg-gray-700'
              }`}>
            {f.label}
          </button>
        ))}
      </div>

      {/* Alert list */}
      {loading ? (
        <div className="flex items-center justify-center py-12">
          <div className="w-8 h-8 border-4 border-red-500 border-t-transparent rounded-full animate-spin" />
        </div>
      ) : alerts.length === 0 ? (
        <div className="bg-white dark:bg-gray-800 rounded-2xl shadow p-10 text-center">
          <Siren size={40} className="mx-auto text-gray-300 dark:text-gray-600 mb-3" />
          <p className="text-gray-500 dark:text-gray-400 text-sm">Tidak ada alert darurat</p>
        </div>
      ) : (
        <div className="space-y-3">
          {alerts.map(alert => {
            const meta = STATUS_META[alert.status] || STATUS_META.resolved;
            const isActive = alert.status === 'active';
            const isAcked  = alert.status === 'acknowledged';
            return (
              <div key={alert.id}
                className={`bg-white dark:bg-gray-800 rounded-2xl shadow p-5 border-l-4 transition-all
                  ${isActive ? 'border-red-500' : isAcked ? 'border-yellow-400' : 'border-green-400'}`}>
                <div className="flex items-start justify-between gap-3">
                  <div className="flex-1 min-w-0">
                    {/* Status + timestamp */}
                    <div className="flex items-center gap-2 mb-2 flex-wrap">
                      <span className={`inline-flex items-center gap-1.5 text-xs px-2.5 py-1 rounded-full font-semibold border ${meta.cls}`}>
                        <span className={`w-1.5 h-1.5 rounded-full ${meta.dot} ${isActive ? 'animate-pulse' : ''}`} />
                        {meta.label}
                      </span>
                      <span className="text-xs text-gray-400">
                        <Clock size={10} className="inline mr-1" />
                        {timeSince(alert.created_at)}
                      </span>
                    </div>

                    {/* Nama + lokasi detail */}
                    <p className="font-bold text-gray-900 dark:text-white text-base">
                      {alert.triggered_by_name}
                    </p>
                    <div className="flex flex-wrap items-center gap-x-3 gap-y-0.5 mt-0.5">
                      {alert.blok_rumah && (
                        <span className="text-sm text-gray-500 dark:text-gray-400 flex items-center gap-1">
                          <MapPin size={12} /> No. {alert.blok_rumah}
                        </span>
                      )}
                      {alert.rt_name && (
                        <span className="text-xs bg-blue-50 dark:bg-blue-900/30 text-blue-700 dark:text-blue-300 px-2 py-0.5 rounded-full font-medium">
                          {alert.rt_name}
                        </span>
                      )}
                      {alert.rw_name && (
                        <span className="text-xs bg-emerald-50 dark:bg-emerald-900/30 text-emerald-700 dark:text-emerald-300 px-2 py-0.5 rounded-full font-medium">
                          {alert.rw_name}
                        </span>
                      )}
                    </div>
                    {alert.pesan && (
                      <div className="mt-2 bg-gray-50 dark:bg-gray-700/50 rounded-lg px-3 py-2 flex items-start gap-2">
                        <MessageSquare size={13} className="text-gray-400 flex-shrink-0 mt-0.5" />
                        <p className="text-sm text-gray-700 dark:text-gray-300">{alert.pesan}</p>
                      </div>
                    )}

                    {/* Handler info */}
                    {alert.handled_by_name && (
                      <p className="text-xs text-gray-400 mt-2">
                        Ditangani oleh: <span className="font-medium text-gray-600 dark:text-gray-300">{alert.handled_by_name}</span>
                        {alert.acknowledged_at && ` · ${timeSince(alert.acknowledged_at)}`}
                      </p>
                    )}
                    {alert.resolved_at && (
                      <p className="text-xs text-gray-400 mt-0.5">
                        Selesai: <span className="font-medium">{timeSince(alert.resolved_at)}</span>
                      </p>
                    )}
                  </div>

                  {/* Action buttons — hanya untuk admin */}
                  {isAdmin && (
                    <div className="flex flex-col gap-2 flex-shrink-0">
                      {isActive && (
                        <button
                          onClick={() => doAction(alert.id, 'acknowledge')}
                          disabled={!!actLoading[alert.id]}
                          className="flex items-center gap-1.5 px-3 py-1.5 rounded-xl bg-yellow-500 hover:bg-yellow-600 text-white text-xs font-semibold disabled:opacity-50 transition-colors"
                        >
                          <CheckCircle size={13} />
                          {actLoading[alert.id] === 'acknowledge' ? '...' : 'Tangani'}
                        </button>
                      )}
                      {(isActive || isAcked) && (
                        <button
                          onClick={() => doAction(alert.id, 'resolve')}
                          disabled={!!actLoading[alert.id]}
                          className="flex items-center gap-1.5 px-3 py-1.5 rounded-xl bg-green-600 hover:bg-green-700 text-white text-xs font-semibold disabled:opacity-50 transition-colors"
                        >
                          <CircleCheck size={13} />
                          {actLoading[alert.id] === 'resolve' ? '...' : 'Selesai'}
                        </button>
                      )}
                    </div>
                  )}
                </div>
              </div>
            );
          })}
        </div>
      )}
    </div>
  );
}
