import React, { useState, useEffect } from 'react';
import axios from 'axios';
import { useAuth } from '../contexts/AuthContext';
import { useLocation } from 'react-router-dom';
import { API_BASE_URL } from '../config/api';
import { Bell, Plus, Pencil, Trash2, RefreshCw, Eye, Send, Building2, Megaphone } from 'lucide-react';
import {
  Table, TableBody, TableCell, TableHead, TableHeader, TableRow
} from '@/components/ui/table';
import { Badge } from '@/components/ui/badge';
import {
  Dialog, DialogContent, DialogHeader, DialogTitle, DialogFooter
} from '@/components/ui/dialog';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Textarea } from '@/components/ui/textarea';
import {
  Select, SelectContent, SelectItem, SelectTrigger, SelectValue
} from '@/components/ui/select';

const STATUS_COLORS = {
  draft: 'border-gray-400 text-gray-500 bg-[#ece4cf] dark:bg-gray-700',
  published: 'border-green-500 text-green-600 bg-green-50 dark:bg-green-900/20',
  archived: 'border-amber-400 text-amber-600 bg-amber-50 dark:bg-amber-900/20',
};

const TIPE_COLORS = {
  info: 'border-blue-400 text-blue-600 bg-blue-50 dark:bg-blue-900/20',
  penting: 'border-amber-500 text-amber-600 bg-amber-50 dark:bg-amber-900/20',
  darurat: 'border-red-500 text-red-600 bg-red-50 dark:bg-red-900/20',
  kegiatan: 'border-purple-400 text-purple-600 bg-purple-50 dark:bg-purple-900/20',
};

const PengumumanRT = () => {
  const { token, user } = useAuth();
  const location = useLocation();
  const isWarga = user?.role === 'warga';
  const isRTAdmin = user?.role === 'admin';
  const [data, setData] = useState([]);
  const [activeTab, setActiveTab] = useState('rt');
  const [rwData, setRwData] = useState([]);
  const [rwLoading, setRwLoading] = useState(false);
  const [kelData, setKelData] = useState([]);
  const [kelLoading, setKelLoading] = useState(false);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [filterStatus, setFilterStatus] = useState('');
  const [showForm, setShowForm] = useState(false);
  const [editItem, setEditItem] = useState(null);
  const [viewItem, setViewItem] = useState(null);
  const [saving, setSaving] = useState(false);
  const [form, setForm] = useState({
    judul: '', isi: '', tipe: 'info', target: 'all', level: 'RT', status: 'draft'
  });

  useEffect(() => { fetchData(); }, [token]);

  useEffect(() => {
    if (location.state?.viewItem) setViewItem(location.state.viewItem);
    if (location.state?.tab) setActiveTab(location.state.tab);
    if (location.state?.viewItem || location.state?.tab) {
      window.history.replaceState({}, '', location.pathname);
    }
  }, []);

  const fetchData = async () => {
    try {
      setLoading(true);
      const headers = { Authorization: `Bearer ${token}` };
      const params = isWarga
        ? '?status=published&level=RT'
        : (filterStatus ? `?status=${filterStatus}&level=RT` : '?level=RT');
      const res = await axios.get(`${API_BASE_URL}/api/pengumuman${params}`, { headers });
      setData(Array.isArray(res.data) ? res.data : []);
      setError(null);
    } catch (err) {
      setError(err.response?.data?.detail || err.message);
    } finally {
      setLoading(false);
    }
  };

  const fetchRWInbox = async () => {
    try {
      setRwLoading(true);
      const headers = { Authorization: `Bearer ${token}` };
      const res = await axios.get(`${API_BASE_URL}/api/pengumuman/inbox-rt`, { headers });
      setRwData(res.data?.data || []);
    } catch (_) {
    } finally {
      setRwLoading(false);
    }
  };

  const fetchKelInbox = async () => {
    try {
      setKelLoading(true);
      const headers = { Authorization: `Bearer ${token}` };
      const res = await axios.get(`${API_BASE_URL}/api/pengumuman/inbox-rt-kelurahan`, { headers });
      setKelData(res.data?.data || []);
    } catch (_) {
    } finally {
      setKelLoading(false);
    }
  };

  useEffect(() => {
    if (isRTAdmin && activeTab === 'rw') fetchRWInbox();
    if (isRTAdmin && activeTab === 'kel') fetchKelInbox();
  }, [isRTAdmin, activeTab]);

  const openAdd = () => {
    setEditItem(null);
    setForm({ judul: '', isi: '', tipe: 'info', target: 'all', level: 'RT', status: 'draft' });
    setShowForm(true);
  };

  const openEdit = (item) => {
    setEditItem(item);
    setForm({ judul: item.judul, isi: item.isi, tipe: item.tipe, target: item.target, level: 'RT', status: item.status });
    setShowForm(true);
  };

  const handleSave = async () => {
    if (!form.judul || !form.isi) return;
    try {
      setSaving(true);
      const headers = { Authorization: `Bearer ${token}` };
      const payload = { ...form, level: 'RT' };
      if (editItem) {
        await axios.put(`${API_BASE_URL}/api/pengumuman/${editItem.id}`, payload, { headers });
      } else {
        await axios.post(`${API_BASE_URL}/api/pengumuman`, payload, { headers });
      }
      setShowForm(false);
      fetchData();
    } catch (err) {
      alert(err.response?.data?.detail || 'Gagal menyimpan');
    } finally {
      setSaving(false);
    }
  };

  const handlePublish = async (id) => {
    try {
      const headers = { Authorization: `Bearer ${token}` };
      await axios.post(`${API_BASE_URL}/api/pengumuman/${id}/publish`, {}, { headers });
      fetchData();
    } catch (err) {
      alert(err.response?.data?.detail || 'Gagal mempublish');
    }
  };

  const handleDelete = async (id) => {
    if (!window.confirm('Hapus pengumuman ini?')) return;
    try {
      const headers = { Authorization: `Bearer ${token}` };
      await axios.delete(`${API_BASE_URL}/api/pengumuman/${id}`, { headers });
      fetchData();
    } catch (err) {
      alert(err.response?.data?.detail || 'Gagal menghapus');
    }
  };

  const formatDate = (d) => d
    ? new Date(d).toLocaleDateString('id-ID', { day: '2-digit', month: 'short', year: 'numeric' })
    : '-';

  if (loading) {
    return (
      <div className="p-6 bg-[#efe7d2] dark:bg-gray-900 min-h-full flex items-center justify-center">
        <div className="text-center space-y-4">
          <div className="w-12 h-12 border-4 border-cyan-500 border-t-transparent rounded-full animate-spin mx-auto" />
          <p className="text-gray-500 dark:text-gray-400">Memuat pengumuman...</p>
        </div>
      </div>
    );
  }

  if (error) {
    return (
      <div className="p-6 bg-[#efe7d2] dark:bg-gray-900 min-h-full">
        <div className="bg-red-50 dark:bg-red-900/20 border border-red-200 dark:border-red-800 rounded-lg p-4">
          <p className="text-red-600 dark:text-red-400 text-sm">Error: {error}</p>
        </div>
      </div>
    );
  }

  return (
    <div className="p-6 space-y-6 bg-[#efe7d2] dark:bg-gray-900 min-h-full">
      {/* Breadcrumb */}
      <div className="flex items-center gap-2 text-sm text-gray-500 dark:text-gray-400">
        <span>RT</span><span>/</span>
        <span className="text-gray-700 dark:text-gray-300 font-medium">Pengumuman</span>
      </div>

      {/* Tab switcher — RT admin only */}
      {isRTAdmin && (
        <div className="flex gap-1 bg-[#f7f1de] dark:bg-gray-800 rounded-lg p-1 shadow w-fit">
          <button
            onClick={() => setActiveTab('rt')}
            className={`px-4 py-2 text-sm font-medium rounded-md transition-colors ${
              activeTab === 'rt'
                ? 'bg-[#ed6f5c] text-white shadow-sm'
                : 'text-gray-600 dark:text-gray-400 hover:bg-[#e4dcc8] dark:hover:bg-gray-700'
            }`}
          >
            Pengumuman RT
          </button>
          <button
            onClick={() => setActiveTab('rw')}
            className={`px-4 py-2 text-sm font-medium rounded-md transition-colors ${
              activeTab === 'rw'
                ? 'bg-[#ed6f5c] text-white shadow-sm'
                : 'text-gray-600 dark:text-gray-400 hover:bg-[#e4dcc8] dark:hover:bg-gray-700'
            }`}
          >
            Dari RW
          </button>
          <button
            onClick={() => setActiveTab('kel')}
            className={`px-4 py-2 text-sm font-medium rounded-md transition-colors ${
              activeTab === 'kel'
                ? 'bg-emerald-500 text-white shadow-sm'
                : 'text-gray-600 dark:text-gray-400 hover:bg-[#e4dcc8] dark:hover:bg-gray-700'
            }`}
          >
            Dari Kelurahan
          </button>
        </div>
      )}

      {/* Header */}
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-3">
          <div className={`w-10 h-10 bg-gradient-to-br ${activeTab === 'kel' ? 'from-emerald-500 to-teal-600' : 'from-purple-500 to-violet-600'} rounded-xl flex items-center justify-center shadow`}>
            {activeTab === 'kel' ? <Megaphone className="h-5 w-5 text-white" /> : <Bell className="h-5 w-5 text-white" />}
          </div>
          <div>
            <h1 className="text-2xl font-bold text-gray-900 dark:text-white">
              {isRTAdmin && activeTab === 'kel' ? 'Broadcast dari Kelurahan'
                : isRTAdmin && activeTab === 'rw' ? 'Inbox dari RW'
                : 'Pengumuman RT'}
            </h1>
            <p className="text-sm text-gray-500 dark:text-gray-400">
              {isRTAdmin && activeTab === 'kel'
                ? `Broadcast dari Kelurahan untuk wilayah Anda — ${kelData.length} pengumuman`
                : isRTAdmin && activeTab === 'rw'
                ? `Pengumuman dari RW untuk RT Anda — ${rwData.length} pengumuman`
                : `${isWarga ? 'Pengumuman dari RT Anda' : 'Kirim pengumuman ke warga'} — ${data.length} pengumuman`}
            </p>
          </div>
        </div>
        <div className="flex gap-2">
          <button onClick={activeTab === 'kel' ? fetchKelInbox : activeTab === 'rw' ? fetchRWInbox : fetchData} className="flex items-center gap-2 px-3 py-2 text-sm bg-[#f7f1de] dark:bg-gray-800 border border-[#d5cebc] dark:border-gray-700 rounded-lg hover:bg-[#e4dcc8] dark:hover:bg-gray-700 transition-colors">
            <RefreshCw className="h-4 w-4" />
          </button>
          {!isWarga && activeTab !== 'rw' && activeTab !== 'kel' && (
            <button onClick={openAdd} className="flex items-center gap-2 px-4 py-2 bg-[#ed6f5c] hover:bg-[#e05544] text-white text-sm rounded-lg transition-colors">
              <Plus className="h-4 w-4" />Buat Pengumuman
            </button>
          )}
        </div>
      </div>

      {/* Filter — disembunyikan untuk warga dan tab RW/Kelurahan */}
      {!isWarga && activeTab !== 'rw' && activeTab !== 'kel' && <div className="bg-[#f7f1de] dark:bg-gray-800 rounded-lg shadow p-4 flex gap-3 items-end">
        <div className="w-40">
          <label className="text-xs text-gray-500 dark:text-gray-400 mb-1 block">Filter Status</label>
          <Select value={filterStatus || "all"} onValueChange={v => { setFilterStatus(v === "all" ? "" : v); setTimeout(fetchData, 100); }}>
            <SelectTrigger><SelectValue placeholder="Semua Status" /></SelectTrigger>
            <SelectContent>
              <SelectItem value="all">Semua Status</SelectItem>
              <SelectItem value="draft">Draft</SelectItem>
              <SelectItem value="published">Published</SelectItem>
              <SelectItem value="archived">Archived</SelectItem>
            </SelectContent>
          </Select>
        </div>
      </div>}

      {/* Table */}
      {isRTAdmin && activeTab === 'kel' ? (
        <div className="bg-[#f7f1de] dark:bg-gray-800 rounded-lg shadow overflow-hidden">
          <div className="bg-gradient-to-r from-emerald-500 to-teal-600 p-4 flex items-center gap-3">
            <div className="w-8 h-8 bg-white/20 rounded-lg flex items-center justify-center">
              <Megaphone className="h-4 w-4 text-white" />
            </div>
            <div>
              <h3 className="text-base font-semibold text-white">Broadcast dari Kelurahan ({kelData.length})</h3>
              <p className="text-emerald-100 text-xs">Pengumuman langsung dari Kelurahan</p>
            </div>
          </div>
          {kelLoading ? (
            <div className="flex items-center justify-center py-12">
              <div className="w-8 h-8 border-4 border-emerald-500 border-t-transparent rounded-full animate-spin" />
            </div>
          ) : kelData.length > 0 ? (
            <Table>
              <TableHeader>
                <TableRow>
                  <TableHead>Judul</TableHead>
                  <TableHead>Tipe</TableHead>
                  <TableHead>Tanggal Publish</TableHead>
                  <TableHead>Dari</TableHead>
                  <TableHead className="text-center">Detail</TableHead>
                </TableRow>
              </TableHeader>
              <TableBody>
                {kelData.map((p) => (
                  <TableRow key={p.id}>
                    <TableCell className="font-medium text-gray-900 dark:text-white max-w-[240px]">
                      <span className="truncate block">{p.judul}</span>
                    </TableCell>
                    <TableCell>
                      <Badge variant="outline" className={TIPE_COLORS[p.tipe] || ''}>{p.tipe}</Badge>
                    </TableCell>
                    <TableCell className="text-sm text-gray-500 dark:text-gray-400">{formatDate(p.published_at)}</TableCell>
                    <TableCell>
                      <span className="flex items-center gap-1 text-sm text-gray-500 dark:text-gray-400">
                        <Building2 className="h-3.5 w-3.5 text-emerald-500" />
                        {p.creator_name || 'Kelurahan'}
                      </span>
                    </TableCell>
                    <TableCell className="text-center">
                      <button onClick={() => setViewItem(p)} className="p-1.5 text-emerald-600 hover:bg-emerald-50 dark:hover:bg-emerald-900/20 rounded">
                        <Eye className="h-3.5 w-3.5" />
                      </button>
                    </TableCell>
                  </TableRow>
                ))}
              </TableBody>
            </Table>
          ) : (
            <div className="text-center py-12">
              <Megaphone className="h-12 w-12 text-gray-300 dark:text-gray-600 mx-auto mb-3" />
              <p className="text-gray-500 dark:text-gray-400">Belum ada broadcast dari Kelurahan</p>
            </div>
          )}
        </div>
      ) : isRTAdmin && activeTab === 'rw' ? (
        <div className="bg-[#f7f1de] dark:bg-gray-800 rounded-lg shadow overflow-hidden">
          <div className="p-4 border-b border-[#d5cebc] dark:border-gray-700">
            <h3 className="text-base font-semibold text-gray-900 dark:text-gray-100">Pengumuman dari RW ({rwData.length})</h3>
          </div>
          {rwLoading ? (
            <div className="flex items-center justify-center py-12">
              <div className="w-8 h-8 border-4 border-[#ed6f5c] border-t-transparent rounded-full animate-spin" />
            </div>
          ) : rwData.length > 0 ? (
            <Table>
              <TableHeader>
                <TableRow>
                  <TableHead>Judul</TableHead>
                  <TableHead>Tipe</TableHead>
                  <TableHead>Tanggal Publish</TableHead>
                  <TableHead>Dari</TableHead>
                  <TableHead className="text-center">Detail</TableHead>
                </TableRow>
              </TableHeader>
              <TableBody>
                {rwData.map((p) => (
                  <TableRow key={p.id}>
                    <TableCell className="font-medium text-gray-900 dark:text-white max-w-[240px]">
                      <span className="truncate block">{p.judul}</span>
                    </TableCell>
                    <TableCell>
                      <Badge variant="outline" className={TIPE_COLORS[p.tipe] || ''}>{p.tipe}</Badge>
                    </TableCell>
                    <TableCell className="text-sm text-gray-500 dark:text-gray-400">{formatDate(p.published_at)}</TableCell>
                    <TableCell className="text-sm text-gray-500 dark:text-gray-400">{p.creator_name || '-'}</TableCell>
                    <TableCell className="text-center">
                      <button onClick={() => setViewItem(p)} className="p-1.5 text-blue-500 hover:bg-blue-50 dark:hover:bg-blue-900/20 rounded">
                        <Eye className="h-3.5 w-3.5" />
                      </button>
                    </TableCell>
                  </TableRow>
                ))}
              </TableBody>
            </Table>
          ) : (
            <div className="text-center py-12">
              <Bell className="h-12 w-12 text-gray-300 dark:text-gray-600 mx-auto mb-3" />
              <p className="text-gray-500 dark:text-gray-400">Belum ada pengumuman dari RW</p>
            </div>
          )}
        </div>
      ) : (
        <div className="bg-[#f7f1de] dark:bg-gray-800 rounded-lg shadow overflow-hidden">
          <div className="p-4 border-b border-[#d5cebc] dark:border-gray-700">
            <h3 className="text-base font-semibold text-gray-900 dark:text-gray-100">Daftar Pengumuman ({data.length})</h3>
          </div>
          {data.length > 0 ? (
            <Table>
              <TableHeader>
                <TableRow>
                  <TableHead>Judul</TableHead>
                  <TableHead>Tipe</TableHead>
                  <TableHead>Status</TableHead>
                  <TableHead>Dibuat Oleh</TableHead>
                  <TableHead>Tanggal</TableHead>
                  <TableHead className="text-center">Aksi</TableHead>
                </TableRow>
              </TableHeader>
              <TableBody>
                {data.map((p) => (
                  <TableRow key={p.id}>
                    <TableCell className="font-medium text-gray-900 dark:text-white max-w-[200px]">
                      <span className="truncate block">{p.judul}</span>
                    </TableCell>
                    <TableCell>
                      <Badge variant="outline" className={TIPE_COLORS[p.tipe] || ''}>{p.tipe}</Badge>
                    </TableCell>
                    <TableCell>
                      <Badge variant="outline" className={STATUS_COLORS[p.status] || ''}>{p.status}</Badge>
                    </TableCell>
                    <TableCell className="text-sm text-gray-500 dark:text-gray-400">{p.creator_name || '-'}</TableCell>
                    <TableCell className="text-sm text-gray-500 dark:text-gray-400">{formatDate(p.created_at)}</TableCell>
                    <TableCell className="text-center">
                      <div className="flex items-center justify-center gap-1">
                        <button onClick={() => setViewItem(p)} className="p-1.5 text-blue-500 hover:bg-blue-50 dark:hover:bg-blue-900/20 rounded">
                          <Eye className="h-3.5 w-3.5" />
                        </button>
                        {!isWarga && p.status === 'draft' && (
                          <button onClick={() => handlePublish(p.id)} className="p-1.5 text-green-500 hover:bg-green-50 dark:hover:bg-green-900/20 rounded" title="Publish">
                            <Send className="h-3.5 w-3.5" />
                          </button>
                        )}
                        {!isWarga && (
                          <button onClick={() => openEdit(p)} className="p-1.5 text-amber-500 hover:bg-amber-50 dark:hover:bg-amber-900/20 rounded">
                            <Pencil className="h-3.5 w-3.5" />
                          </button>
                        )}
                        {!isWarga && (
                          <button onClick={() => handleDelete(p.id)} className="p-1.5 text-red-500 hover:bg-red-50 dark:hover:bg-red-900/20 rounded">
                            <Trash2 className="h-3.5 w-3.5" />
                          </button>
                        )}
                      </div>
                    </TableCell>
                  </TableRow>
                ))}
              </TableBody>
            </Table>
          ) : (
            <div className="text-center py-12">
              <Bell className="h-12 w-12 text-gray-300 dark:text-gray-600 mx-auto mb-3" />
              <p className="text-gray-500 dark:text-gray-400">Belum ada pengumuman</p>
            </div>
          )}
        </div>
      )}

      {/* Form Dialog */}
      <Dialog open={showForm} onOpenChange={setShowForm}>
        <DialogContent className="bg-[#f7f1de] dark:bg-gray-900 max-w-lg">
          <DialogHeader>
            <DialogTitle>{editItem ? 'Edit Pengumuman' : 'Buat Pengumuman Baru'}</DialogTitle>
          </DialogHeader>
          <div className="space-y-3 py-2">
            <div>
              <Label>Judul <span className="text-red-500">*</span></Label>
              <Input className="mt-1" value={form.judul} onChange={e => setForm(f => ({ ...f, judul: e.target.value }))} placeholder="Judul pengumuman..." />
            </div>
            <div>
              <Label>Isi Pengumuman <span className="text-red-500">*</span></Label>
              <Textarea className="mt-1" rows={4} value={form.isi} onChange={e => setForm(f => ({ ...f, isi: e.target.value }))} placeholder="Isi pengumuman..." />
            </div>
            <div className="grid grid-cols-2 gap-3">
              <div>
                <Label>Tipe</Label>
                <Select value={form.tipe} onValueChange={v => setForm(f => ({ ...f, tipe: v }))}>
                  <SelectTrigger className="mt-1"><SelectValue /></SelectTrigger>
                  <SelectContent>
                    <SelectItem value="info">Info</SelectItem>
                    <SelectItem value="penting">Penting</SelectItem>
                    <SelectItem value="darurat">Darurat</SelectItem>
                    <SelectItem value="kegiatan">Kegiatan</SelectItem>
                  </SelectContent>
                </Select>
              </div>
              <div>
                <Label>Status</Label>
                <Select value={form.status} onValueChange={v => setForm(f => ({ ...f, status: v }))}>
                  <SelectTrigger className="mt-1"><SelectValue /></SelectTrigger>
                  <SelectContent>
                    <SelectItem value="draft">Draft</SelectItem>
                    <SelectItem value="published">Publish Sekarang</SelectItem>
                  </SelectContent>
                </Select>
              </div>
            </div>
          </div>
          <DialogFooter>
            <button onClick={() => setShowForm(false)} className="px-4 py-2 text-sm border border-[#d5cebc] dark:border-gray-700 rounded-lg hover:bg-[#e4dcc8] dark:hover:bg-gray-800">Batal</button>
            <button onClick={handleSave} disabled={saving} className="px-4 py-2 bg-[#ed6f5c] hover:bg-[#e05544] text-white text-sm rounded-lg disabled:opacity-50">
              {saving ? 'Menyimpan...' : 'Simpan'}
            </button>
          </DialogFooter>
        </DialogContent>
      </Dialog>

      {/* View Dialog */}
      <Dialog open={!!viewItem} onOpenChange={() => setViewItem(null)}>
        <DialogContent className="bg-[#f7f1de] dark:bg-gray-900 max-w-lg">
          <DialogHeader>
            <DialogTitle className="flex items-center gap-2">
              <Bell className="h-5 w-5 text-purple-500" />
              {viewItem?.judul}
            </DialogTitle>
          </DialogHeader>
          {viewItem && (
            <div className="space-y-3 text-sm">
              <div className="flex gap-2 flex-wrap">
                <Badge variant="outline" className={STATUS_COLORS[viewItem.status] || ''}>{viewItem.status}</Badge>
                <Badge variant="outline" className={TIPE_COLORS[viewItem.tipe] || ''}>{viewItem.tipe}</Badge>
              </div>
              <div className="text-gray-500 dark:text-gray-400 text-xs">
                Dibuat: {formatDate(viewItem.created_at)} · Oleh: {viewItem.creator_name || '-'}
                {viewItem.published_at && ` · Dipublish: ${formatDate(viewItem.published_at)}`}
              </div>
              <div className="bg-[#ece4cf] dark:bg-gray-800 rounded-lg p-4 text-gray-700 dark:text-gray-300 whitespace-pre-wrap">
                {viewItem.isi}
              </div>
            </div>
          )}
        </DialogContent>
      </Dialog>
    </div>
  );
};

export default PengumumanRT;
