import { useEffect, useLayoutEffect, useRef, useState } from "react";
import { API_BASE_URL, API_ENDPOINTS } from "@/config/api";
import { useAuth } from "@/contexts/AuthContext";
import { Building2, Lock, MapPin, User, FileText, RefreshCw, Calendar, PenTool, ShieldCheck } from "lucide-react";

const Field = ({ label, value, mono = false }) => (
  <div>
    <p className="text-xs font-medium text-gray-500 dark:text-gray-400 mb-1 uppercase tracking-wide">{label}</p>
    <p className={`text-sm font-semibold text-gray-800 dark:text-gray-100 bg-[#f7f1de] dark:bg-gray-700 rounded-lg px-3 py-2.5 border border-[#d5cebc] dark:border-gray-600 ${mono ? 'font-mono' : ''}`}>
      {value || <span className="text-gray-400 dark:text-gray-500 font-normal italic">Belum diisi</span>}
    </p>
  </div>
);

const formatTanggal = (iso) => {
  if (!iso) return '';
  const [y, m, d] = iso.split('-');
  return `${d}/${m}/${y}`;
};

const formatPeriode = (val) => {
  if (!val) return '';
  const [mulai, selesai] = val.split('|');
  if (!mulai && !selesai) return '';
  if (mulai && selesai) return `Mulai ${formatTanggal(mulai)} s/d ${formatTanggal(selesai)}`;
  if (mulai) return `Mulai ${formatTanggal(mulai)}`;
  return `s/d ${formatTanggal(selesai)}`;
};

// Canvas wrapper: attaches touch events with passive:false to prevent page scroll while drawing
function CanvasSignature({ canvasRef, onStart, onMove, onEnd }) {
  useEffect(() => {
    const c = canvasRef.current; if (!c) return;
    const opts = { passive: false };
    c.addEventListener('touchstart',  onStart, opts);
    c.addEventListener('touchmove',   onMove,  opts);
    c.addEventListener('touchend',    onEnd,   opts);
    c.addEventListener('touchcancel', onEnd,   opts);
    return () => {
      c.removeEventListener('touchstart',  onStart, opts);
      c.removeEventListener('touchmove',   onMove,  opts);
      c.removeEventListener('touchend',    onEnd,   opts);
      c.removeEventListener('touchcancel', onEnd,   opts);
    };
  }, [canvasRef, onStart, onMove, onEnd]);

  return (
    <div className="border-2 border-[#d5cebc] dark:border-gray-600 rounded-lg overflow-hidden bg-white dark:bg-gray-700 select-none"
      style={{ cursor: 'crosshair', touchAction: 'none', userSelect: 'none' }}>
      <canvas
        ref={canvasRef}
        className="block w-full"
        style={{ display: 'block' }}
        onMouseDown={onStart}
        onMouseMove={onMove}
        onMouseUp={onEnd}
        onMouseLeave={onEnd}
      />
    </div>
  );
}

export default function ProfilRT() {
  const { token, user } = useAuth();
  const isAdmin = user?.role === 'admin' || user?.role === 'pengurus_rt';
  const [form, setForm]       = useState({});
  const [loading, setLoading] = useState(true);

  // TTD state
  const [mainTab,     setMainTab]     = useState('gambar');   // 'gambar' | 'pin'
  const [drawMode,    setDrawMode]    = useState('canvas');   // 'canvas' | 'upload'
  const [ttdUrl,      setTtdUrl]      = useState(null);
  const [hasPin,      setHasPin]      = useState(false);
  const [ttdSaving,   setTtdSaving]   = useState(false);
  const [ttdMsg,      setTtdMsg]      = useState('');
  const [pinVal,      setPinVal]      = useState('');
  const [pinConfirm,  setPinConfirm]  = useState('');
  const [pinMsg,      setPinMsg]      = useState('');
  const [pinSaving,   setPinSaving]   = useState(false);
  const [uploadFile,  setUploadFile]  = useState(null);
  const [uploadPreview, setUploadPreview] = useState(null);
  const canvasRef  = useRef(null);
  const isDrawing  = useRef(false);
  const lastPos    = useRef({ x: 0, y: 0 });
  const uploadRef  = useRef(null);
  const dprRef     = useRef(1);

  const authHeader = { Authorization: `Bearer ${token}` };

  const load = async () => {
    setLoading(true);
    try {
      const res = await fetch(`${API_BASE_URL}/api/surat-resmi/profil`, {
        headers: authHeader,
      });
      if (res.ok) setForm(await res.json());
    } catch { /* ignore */ }
    setLoading(false);
  };

  const loadTtd = async () => {
    try {
      const res = await fetch(API_ENDPOINTS.SURAT_TTD_IMAGE, { headers: authHeader });
      if (res.ok) {
        const d = await res.json();
        setTtdUrl(d.ttd_url ? `${API_BASE_URL}${d.ttd_url}?t=${Date.now()}` : null);
        setHasPin(d.has_pin);
      }
    } catch { /* ignore */ }
  };

  useEffect(() => { load(); loadTtd(); }, [token]);

  // stop drawing if mouse released anywhere outside canvas
  useEffect(() => {
    const up = () => { isDrawing.current = false; };
    window.addEventListener('mouseup', up);
    return () => window.removeEventListener('mouseup', up);
  }, []);

  // ── Canvas: init with proper DPR dimensions ──────────────
  const initCanvas = (c) => {
    if (!c) return;
    const dpr  = window.devicePixelRatio || 1;
    dprRef.current = dpr;
    const cssW = c.parentElement ? c.parentElement.clientWidth : c.offsetWidth;
    const cssH = 160;
    if (cssW === 0) return;
    c.width  = cssW * dpr;
    c.height = cssH * dpr;
    c.style.width  = `${cssW}px`;
    c.style.height = `${cssH}px`;
    const ctx = c.getContext('2d');
    ctx.strokeStyle = '#e2d9c5';
    ctx.lineWidth   = 1 * dpr;
    const gy = 120 * dpr;
    ctx.beginPath(); ctx.moveTo(20 * dpr, gy); ctx.lineTo((cssW - 20) * dpr, gy); ctx.stroke();
  };

  useLayoutEffect(() => {
    if (drawMode !== 'canvas') return;
    // use rAF so the DOM has laid out and offsetWidth is correct
    const id = requestAnimationFrame(() => initCanvas(canvasRef.current));
    return () => cancelAnimationFrame(id);
  }, [drawMode]);

  // ── Canvas helpers ──────────────────────────────────────
  // Returns canvas pixel coords (already scaled by DPR)
  const getPos = (e, canvas) => {
    const rect = canvas.getBoundingClientRect();
    const src  = e.touches ? e.touches[0] : e;
    const dpr  = dprRef.current;
    return {
      x: (src.clientX - rect.left) * dpr,
      y: (src.clientY - rect.top)  * dpr,
    };
  };
  const startDraw = (e) => {
    const c = canvasRef.current; if (!c) return;
    e.preventDefault();
    isDrawing.current = true;
    lastPos.current   = getPos(e, c);
  };
  const draw = (e) => {
    if (!isDrawing.current) return;
    const c = canvasRef.current; if (!c) return;
    e.preventDefault();
    const ctx = c.getContext('2d');
    const pos = getPos(e, c);
    ctx.beginPath();
    ctx.moveTo(lastPos.current.x, lastPos.current.y);
    ctx.lineTo(pos.x, pos.y);
    ctx.strokeStyle = '#1e293b';
    ctx.lineWidth   = 2.5 * dprRef.current;
    ctx.lineCap     = 'round';
    ctx.lineJoin    = 'round';
    ctx.stroke();
    lastPos.current = pos;
  };
  const stopDraw = () => { isDrawing.current = false; };
  const clearCanvas = () => {
    const c = canvasRef.current; if (!c) return;
    c.getContext('2d').clearRect(0, 0, c.width, c.height);
    initCanvas(c);
  };

  const saveCanvas = async () => {
    const c = canvasRef.current; if (!c) return;
    const b64 = c.toDataURL('image/png');
    setTtdSaving(true); setTtdMsg('');
    try {
      const res = await fetch(API_ENDPOINTS.SURAT_TTD_CANVAS, {
        method: 'POST',
        headers: { ...authHeader, 'Content-Type': 'application/json' },
        body: JSON.stringify({ image_base64: b64 }),
      });
      const d = await res.json();
      if (!res.ok) throw new Error(d.detail || 'Gagal');
      setTtdMsg('TTD berhasil disimpan');
      clearCanvas();
      loadTtd();
    } catch (e) { setTtdMsg('Error: ' + e.message); }
    setTtdSaving(false);
  };

  const saveUpload = async () => {
    if (!uploadFile) return;
    setTtdSaving(true); setTtdMsg('');
    try {
      const form = new FormData();
      form.append('file', uploadFile);
      const res = await fetch(API_ENDPOINTS.SURAT_TTD_UPLOAD, {
        method: 'POST',
        headers: authHeader,
        body: form,
      });
      const d = await res.json();
      if (!res.ok) throw new Error(d.detail || 'Gagal');
      setTtdMsg('TTD berhasil diunggah');
      setUploadFile(null); setUploadPreview(null);
      loadTtd();
    } catch (e) { setTtdMsg('Error: ' + e.message); }
    setTtdSaving(false);
  };

  const deleteTtd = async () => {
    if (!window.confirm('Hapus gambar TTD?')) return;
    try {
      await fetch(API_ENDPOINTS.SURAT_TTD_DELETE, { method: 'DELETE', headers: authHeader });
      setTtdUrl(null);
      setTtdMsg('TTD dihapus');
    } catch { /* ignore */ }
  };

  const savePin = async () => {
    if (!pinVal || !pinConfirm) { setPinMsg('Isi PIN dan konfirmasi PIN'); return; }
    if (pinVal !== pinConfirm)  { setPinMsg('PIN tidak cocok'); return; }
    if (pinVal.length < 4 || pinVal.length > 8) { setPinMsg('PIN harus 4-8 digit'); return; }
    setPinSaving(true); setPinMsg('');
    try {
      const res = await fetch(API_ENDPOINTS.SURAT_TTD_SET_PIN, {
        method: 'POST',
        headers: { ...authHeader, 'Content-Type': 'application/json' },
        body: JSON.stringify({ pin: pinVal, pin_confirm: pinConfirm }),
      });
      const d = await res.json();
      if (!res.ok) throw new Error(d.detail || 'Gagal');
      setPinMsg('PIN berhasil disimpan');
      setPinVal(''); setPinConfirm('');
      setHasPin(true);
    } catch (e) { setPinMsg('Error: ' + e.message); }
    setPinSaving(false);
  };

  if (loading) {
    return (
      <div className="p-6 bg-[#efe7d2] dark:bg-gray-900 min-h-full flex items-center justify-center">
        <div className="text-center space-y-3">
          <div className="w-10 h-10 border-4 border-[#ed6f5c] border-t-transparent rounded-full animate-spin mx-auto" />
          <p className="text-sm text-gray-500">Memuat profil RT...</p>
        </div>
      </div>
    );
  }

  return (
    <div className="p-6 space-y-6 bg-[#efe7d2] dark:bg-gray-900 min-h-full">
      {/* Breadcrumb */}
      <div className="flex items-center gap-2 text-sm text-gray-500 dark:text-gray-400">
        <span>RT</span><span>/</span>
        <span className="text-gray-700 dark:text-gray-300 font-medium">Profil RT</span>
      </div>

      {/* Header */}
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-3">
          <div className="w-12 h-12 bg-gradient-to-br from-[#ed6f5c] to-orange-500 rounded-xl flex items-center justify-center shadow-lg">
            <Building2 className="h-6 w-6 text-white" />
          </div>
          <div>
            <h1 className="text-2xl font-bold text-gray-900 dark:text-white">Profil RT</h1>
            <p className="text-sm text-gray-500 dark:text-gray-400">Informasi penandatangan surat resmi RT</p>
          </div>
        </div>
        <button onClick={load} className="flex items-center gap-2 px-3 py-2 text-sm bg-[#f7f1de] dark:bg-gray-800 border border-[#d5cebc] dark:border-gray-700 rounded-lg hover:bg-[#e4dcc8] transition-colors">
          <RefreshCw className="h-4 w-4" />Refresh
        </button>
      </div>

      {/* Lock info */}
      <div className="flex items-center gap-3 bg-amber-50 dark:bg-amber-900/20 border border-amber-200 dark:border-amber-700 rounded-xl px-4 py-3">
        <Lock size={16} className="text-amber-600 dark:text-amber-400 flex-shrink-0" />
        <div>
          <p className="text-sm font-semibold text-amber-700 dark:text-amber-400">Profil dikelola oleh Admin RW</p>
          <p className="text-xs text-amber-600/70 dark:text-amber-500 mt-0.5">Hubungi Admin RW untuk mengubah informasi profil ini</p>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        {/* Identitas Pengurus */}
        <div className="lg:col-span-2 space-y-4">
          <div className="bg-[#f7f1de] dark:bg-gray-800 rounded-xl shadow p-5 space-y-4">
            <div className="flex items-center gap-2 pb-2 border-b border-[#d5cebc] dark:border-gray-700">
              <User className="h-4 w-4 text-[#ed6f5c]" />
              <h3 className="text-sm font-semibold text-gray-700 dark:text-gray-200">Identitas Pengurus</h3>
            </div>
            <Field label="Nama Ketua RT"  value={form.nama_pejabat} />
            <Field label="Jabatan"        value={form.jabatan} />
            <div className="grid grid-cols-2 gap-4">
              <Field label="No. RT" value={form.no_rt} mono />
              <Field label="No. RW" value={form.no_rw} mono />
            </div>
            <div className="flex items-center gap-2 pt-1">
              <Calendar className="h-3.5 w-3.5 text-[#ed6f5c] flex-shrink-0" />
              <span className="text-xs font-medium text-gray-500 dark:text-gray-400 uppercase tracking-wide">Periode Menjabat</span>
            </div>
            <Field label="Periode" value={formatPeriode(form.periode_menjabat)} />
          </div>

          {/* Wilayah */}
          <div className="bg-[#f7f1de] dark:bg-gray-800 rounded-xl shadow p-5 space-y-4">
            <div className="flex items-center gap-2 pb-2 border-b border-[#d5cebc] dark:border-gray-700">
              <MapPin className="h-4 w-4 text-[#ed6f5c]" />
              <h3 className="text-sm font-semibold text-gray-700 dark:text-gray-200">Wilayah</h3>
            </div>
            <Field label="Nama Kelurahan"  value={form.nama_kelurahan} />
            <Field label="Kecamatan"       value={form.kecamatan} />
            <Field label="Kabupaten / Kota" value={form.kabupaten} />
            <div className="grid grid-cols-2 gap-4">
              <Field label="Provinsi"            value={form.provinsi} />
              <Field label="Kota (tanggal surat)" value={form.kota} />
            </div>
          </div>
        </div>

        {/* Preview Kop Surat */}
        <div className="space-y-4">
          <div className="bg-[#f7f1de] dark:bg-gray-800 rounded-xl shadow p-5">
            <div className="flex items-center gap-2 pb-2 border-b border-[#d5cebc] dark:border-gray-700 mb-4">
              <FileText className="h-4 w-4 text-[#ed6f5c]" />
              <h3 className="text-sm font-semibold text-gray-700 dark:text-gray-200">Preview Kop Surat</h3>
            </div>
            <div className="bg-white dark:bg-gray-700 rounded-lg border border-[#d5cebc] dark:border-gray-600 p-4 text-center space-y-1">
              <div className="text-[10px] font-bold text-gray-500 dark:text-gray-300 uppercase tracking-wider leading-tight">
                Pemerintah Kelurahan
              </div>
              <div className="text-sm font-extrabold text-gray-800 dark:text-gray-100 uppercase tracking-wide">
                {form.nama_kelurahan || '...'}
              </div>
              <div className="text-xs font-bold text-[#ed6f5c]">
                Ketua RT. {form.no_rt || '-'} RW. {form.no_rw || '-'}
              </div>
              <div className="border-t border-gray-200 dark:border-gray-500 mt-2 pt-2 text-[10px] text-gray-500 dark:text-gray-400 leading-relaxed">
                {[form.kecamatan, form.kabupaten].filter(Boolean).join(', ') || '...'}
              </div>
              {(form.nama_pejabat || form.jabatan) && (
                <div className="border-t border-dashed border-gray-200 dark:border-gray-500 mt-3 pt-3 text-[10px] text-gray-600 dark:text-gray-300">
                  <div className="font-bold">{form.nama_pejabat || '-'}</div>
                  <div className="text-gray-500 dark:text-gray-400">{form.jabatan || '-'}</div>
                </div>
              )}
            </div>
          </div>

          {/* Status card */}
          <div className="bg-[#f7f1de] dark:bg-gray-800 rounded-xl shadow p-5">
            <p className="text-xs font-medium text-gray-500 dark:text-gray-400 uppercase tracking-wide mb-3">Status Kelengkapan</p>
            {[
              { label: 'Nama Ketua',       ok: !!form.nama_pejabat },
              { label: 'Jabatan',          ok: !!form.jabatan },
              { label: 'No. RT / RW',      ok: !!(form.no_rt && form.no_rw) },
              { label: 'Periode Menjabat', ok: !!form.periode_menjabat },
              { label: 'Kelurahan',        ok: !!form.nama_kelurahan },
              { label: 'Kecamatan',        ok: !!form.kecamatan },
              { label: 'Kabupaten',        ok: !!form.kabupaten },
            ].map(item => (
              <div key={item.label} className="flex items-center justify-between py-1.5 border-b border-gray-100 dark:border-gray-700 last:border-0">
                <span className="text-xs text-gray-600 dark:text-gray-400">{item.label}</span>
                {item.ok
                  ? <span className="text-xs font-semibold text-green-600">✓ Terisi</span>
                  : <span className="text-xs font-semibold text-amber-500">⚠ Kosong</span>}
              </div>
            ))}
          </div>
        </div>
      </div>

      {/* ── Tanda Tangan Digital — hanya admin/pengurus ─────────────────── */}
      {isAdmin && <div className="bg-[#f7f1de] dark:bg-gray-800 rounded-xl shadow p-5 space-y-4">
        <div className="flex items-center gap-2 pb-2 border-b border-[#d5cebc] dark:border-gray-700">
          <PenTool className="h-4 w-4 text-[#ed6f5c]" />
          <h3 className="text-sm font-semibold text-gray-700 dark:text-gray-200">Tanda Tangan Digital</h3>
          <span className="ml-auto text-xs text-gray-400 dark:text-gray-500">Dikelola oleh RT</span>
        </div>

        {/* Main tabs */}
        <div className="flex gap-2 border-b border-[#d5cebc] dark:border-gray-700 pb-0">
          {[['gambar', 'Gambar TTD'], ['pin', 'PIN Keamanan']].map(([key, label]) => (
            <button key={key} onClick={() => setMainTab(key)}
              className={`px-4 py-2 text-sm font-medium rounded-t-lg border-b-2 transition-colors ${
                mainTab === key
                  ? 'border-[#ed6f5c] text-[#ed6f5c] bg-white dark:bg-gray-700'
                  : 'border-transparent text-gray-500 dark:text-gray-400 hover:text-gray-700'
              }`}
            >{label}</button>
          ))}
        </div>

        {/* Tab: Gambar TTD */}
        {mainTab === 'gambar' && (
          <div className="space-y-4">
            {/* Sub-toggle */}
            <div className="flex gap-2">
              {[['canvas', 'Gambar (Canvas)'], ['upload', 'Upload Foto']].map(([key, label]) => (
                <button key={key} onClick={() => setDrawMode(key)}
                  className={`px-3 py-1.5 text-xs font-medium rounded-full border transition-colors ${
                    drawMode === key
                      ? 'bg-[#ed6f5c] text-white border-[#ed6f5c]'
                      : 'bg-white dark:bg-gray-700 text-gray-600 dark:text-gray-300 border-gray-300 dark:border-gray-600 hover:bg-gray-50'
                  }`}
                >{label}</button>
              ))}
            </div>

            {/* Canvas mode */}
            {drawMode === 'canvas' && (
              <div className="space-y-2">
                <p className="text-xs text-gray-500 dark:text-gray-400">
                  Gambar tanda tangan Anda di area berikut. Tanda garis abu-abu adalah panduan baseline.
                </p>
                <CanvasSignature
                  canvasRef={canvasRef}
                  onStart={startDraw}
                  onMove={draw}
                  onEnd={stopDraw}
                />
                <div className="flex gap-2">
                  <button onClick={clearCanvas}
                    className="px-3 py-1.5 text-xs border border-gray-300 dark:border-gray-600 rounded-lg hover:bg-gray-50 dark:hover:bg-gray-700 transition-colors">
                    Hapus
                  </button>
                  <button onClick={saveCanvas} disabled={ttdSaving}
                    className="px-4 py-1.5 text-xs bg-[#ed6f5c] hover:bg-[#e05544] text-white rounded-lg font-medium disabled:opacity-60 transition-colors">
                    {ttdSaving ? 'Menyimpan...' : 'Simpan TTD'}
                  </button>
                </div>
              </div>
            )}

            {/* Upload mode */}
            {drawMode === 'upload' && (
              <div className="space-y-2">
                <p className="text-xs text-gray-500 dark:text-gray-400">Upload gambar TTD (PNG/JPG, transparan lebih baik):</p>
                <div className="flex items-center gap-3">
                  <input ref={uploadRef} type="file" accept="image/png,image/jpeg" className="hidden"
                    onChange={(e) => {
                      const f = e.target.files?.[0];
                      if (!f) return;
                      setUploadFile(f);
                      setUploadPreview(URL.createObjectURL(f));
                    }}
                  />
                  <button onClick={() => uploadRef.current?.click()}
                    className="px-3 py-1.5 text-xs border border-gray-300 dark:border-gray-600 rounded-lg hover:bg-gray-50 dark:hover:bg-gray-700 transition-colors">
                    Pilih File
                  </button>
                  {uploadFile && <span className="text-xs text-gray-600 dark:text-gray-300">{uploadFile.name}</span>}
                </div>
                {uploadPreview && (
                  <div className="border border-[#d5cebc] dark:border-gray-600 rounded-lg p-2 bg-white dark:bg-gray-700 inline-block">
                    <img src={uploadPreview} alt="preview" className="h-16 object-contain" />
                  </div>
                )}
                {uploadFile && (
                  <button onClick={saveUpload} disabled={ttdSaving}
                    className="px-4 py-1.5 text-xs bg-[#ed6f5c] hover:bg-[#e05544] text-white rounded-lg font-medium disabled:opacity-60 transition-colors">
                    {ttdSaving ? 'Mengunggah...' : 'Simpan TTD'}
                  </button>
                )}
              </div>
            )}

            {ttdMsg && (
              <div className={`text-xs px-3 py-2 rounded-lg ${
                ttdMsg.startsWith('Error') ? 'bg-red-50 text-red-600 border border-red-200' : 'bg-green-50 text-green-700 border border-green-200'
              }`}>{ttdMsg}</div>
            )}

            {/* Current TTD preview */}
            <div className="pt-2 border-t border-[#d5cebc] dark:border-gray-700">
              <p className="text-xs font-medium text-gray-500 dark:text-gray-400 uppercase tracking-wide mb-2">TTD Saat Ini</p>
              {ttdUrl ? (
                <div className="flex items-end gap-4">
                  <div className="border border-[#d5cebc] dark:border-gray-600 rounded-lg p-3 bg-white dark:bg-gray-700">
                    <img src={ttdUrl} alt="TTD" className="h-16 object-contain max-w-[200px]" />
                  </div>
                  <button onClick={deleteTtd}
                    className="px-3 py-1.5 text-xs border border-red-300 text-red-600 rounded-lg hover:bg-red-50 transition-colors">
                    Hapus TTD
                  </button>
                </div>
              ) : (
                <div className="text-xs text-gray-400 dark:text-gray-500 italic px-2 py-3 border border-dashed border-gray-200 dark:border-gray-600 rounded-lg">
                  Belum ada gambar TTD tersimpan
                </div>
              )}
            </div>
          </div>
        )}

        {/* Tab: PIN Keamanan */}
        {mainTab === 'pin' && (
          <div className="space-y-4 max-w-sm">
            <div className={`flex items-center gap-2 px-3 py-2 rounded-lg text-sm ${
              hasPin
                ? 'bg-green-50 dark:bg-green-900/20 border border-green-200 dark:border-green-700 text-green-700 dark:text-green-400'
                : 'bg-amber-50 dark:bg-amber-900/20 border border-amber-200 dark:border-amber-700 text-amber-700 dark:text-amber-400'
            }`}>
              <ShieldCheck className="h-4 w-4 flex-shrink-0" />
              <span className="font-medium">{hasPin ? 'PIN sudah diset' : 'PIN belum diset'}</span>
            </div>

            <p className="text-xs text-gray-500 dark:text-gray-400">
              PIN digunakan untuk mengamankan proses penerbitan surat. Setiap kali menyetujui surat, PIN harus dimasukkan.
            </p>

            <div className="space-y-3">
              <div>
                <label className="text-xs font-medium text-gray-600 dark:text-gray-400 block mb-1">
                  {hasPin ? 'PIN Baru' : 'PIN'} <span className="text-gray-400">(4-8 digit)</span>
                </label>
                <input
                  type="password" inputMode="numeric" maxLength={8}
                  value={pinVal} onChange={(e) => setPinVal(e.target.value.replace(/\D/g, ''))}
                  placeholder="Masukkan PIN angka"
                  className="w-full px-3 py-2 text-sm border border-[#d5cebc] dark:border-gray-600 rounded-lg bg-white dark:bg-gray-700 dark:text-gray-100 focus:outline-none focus:ring-2 focus:ring-[#ed6f5c]/30"
                />
              </div>
              <div>
                <label className="text-xs font-medium text-gray-600 dark:text-gray-400 block mb-1">Konfirmasi PIN</label>
                <input
                  type="password" inputMode="numeric" maxLength={8}
                  value={pinConfirm} onChange={(e) => setPinConfirm(e.target.value.replace(/\D/g, ''))}
                  placeholder="Ulangi PIN"
                  className="w-full px-3 py-2 text-sm border border-[#d5cebc] dark:border-gray-600 rounded-lg bg-white dark:bg-gray-700 dark:text-gray-100 focus:outline-none focus:ring-2 focus:ring-[#ed6f5c]/30"
                />
              </div>
              <button onClick={savePin} disabled={pinSaving}
                className="w-full px-4 py-2 text-sm bg-[#ed6f5c] hover:bg-[#e05544] text-white rounded-lg font-medium disabled:opacity-60 transition-colors">
                {pinSaving ? 'Menyimpan...' : hasPin ? 'Perbarui PIN' : 'Simpan PIN'}
              </button>
            </div>

            {pinMsg && (
              <div className={`text-xs px-3 py-2 rounded-lg ${
                pinMsg.startsWith('Error') ? 'bg-red-50 text-red-600 border border-red-200' : 'bg-green-50 text-green-700 border border-green-200'
              }`}>{pinMsg}</div>
            )}
          </div>
        )}
      </div>}
    </div>
  );
}
