/**
 * API Configuration
 * Central configuration for all API endpoints
 * Uses environment variables for dynamic base URLs
 */

// Get base URLs from environment variables with fallback defaults
export const API_BASE_URL = process.env.REACT_APP_API_BASE_URL || 'http://localhost:8025';
export const WHATSAPP_BASE_URL = process.env.REACT_APP_WHATSAPP_BASE_URL || 'http://localhost:4123';


async function req(path, options) {
  const token = localStorage.getItem('token');
  const res = await fetch(`${API_BASE_URL}${path}`, {
    headers: {
      'Content-Type': 'application/json',
      ...(token && { Authorization: `Bearer ${token}` }),
    },
    ...options,
  });
  if (!res.ok) {
    const err = await res.json().catch(() => ({}));
    throw new Error(err.detail || `HTTP ${res.status}`);
  }
  return res.json();
}


