import React, { useState, useEffect } from 'react';
import axios from 'axios';
import jsPDF from 'jspdf';
import autoTable from 'jspdf-autotable';
import * as XLSX from 'xlsx';
import { useAuth } from '../../contexts/AuthContext';
import { useKelurahanFilter } from '../../contexts/KelurahanFilterContext';
import { API_BASE_URL } from '../../config/api';
import { BarChart3, Download, RefreshCw, Users, Home, DollarSign, FileText, AlertCircle, Building2, MapPin } from 'lucide-react';

const LaporanKelurahan = () => {
  const { token } = useAuth();
  const { rwId } = useKelurahanFilter();
  const [data, setData] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  useEffect(() => { fetchData(); }, [token, rwId]);

  const fetchData = async () => {
    try {
      setLoading(true);
      const headers = { Authorization: `Bearer ${token}` };
      const params = new URLSearchParams();
      if (rwId) params.append('rw_id', rwId);
      const res = await axios.get(`${API_BASE_URL}/api/kelurahan/reports/summary?${params}`, { headers });
      setData(res.data);
      setError(null);
    } catch (err) {
      setError(err.response?.data?.detail || err.message);
    } finally {
      setLoading(false);
    }
  };

  const formatCurrency = (val) =>
    new Intl.NumberFormat('id-ID', { style: 'currency', currency: 'IDR', minimumFractionDigits: 0 }).format(val || 0);

  const handleExportPDF = () => {
    if (!data) return;
    const doc = new jsPDF('p', 'mm', 'a4');
    doc.setFont('helvetica', 'bold');
    doc.setFontSize(14);
    doc.text('Laporan Kelurahan', 105, 16, { align: 'center' });
    doc.setFont('helvetica', 'normal');
    doc.setFontSize(9);
    doc.text(`Kelurahan: ${data?.kelurahan?.nama_kelurahan || '-'}`, 15, 24);
    doc.text(`Periode: ${data?.periode || '-'}`, 15, 30);
    doc.text(`Generated: ${data?.generated_at ? new Date(data.generated_at).toLocaleString('id-ID') : '-'}`, 15, 36);
    doc.setDrawColor(200, 200, 200);
    doc.line(15, 40, 195, 40);

    autoTable(doc, {
      startY: 46,
      head: [['Wilayah', '']],
      body: [
        ['Total RW', data?.wilayah?.total_rw ?? 0],
        ['Total RT/Blok', data?.wilayah?.total_rt ?? 0],
        ['RW Aktif', data?.wilayah?.rw_aktif ?? 0],
      ],
      styles: { fontSize: 9 },
      headStyles: { fillColor: [5, 150, 105] },
    });

    autoTable(doc, {
      head: [['Warga', '']],
      body: [
        ['Total Warga', data?.warga?.total ?? 0],
        ['Warga Aktif', data?.warga?.aktif ?? 0],
        ['Tidak Aktif', data?.warga?.tidak_aktif ?? 0],
        ['Laki-laki', data?.warga?.laki_laki ?? 0],
        ['Perempuan', data?.warga?.perempuan ?? 0],
        ['Kepala Keluarga', data?.warga?.kepala_keluarga ?? 0],
      ],
      styles: { fontSize: 9 },
      headStyles: { fillColor: [79, 70, 229] },
    });

    autoTable(doc, {
      head: [['Rumah', '']],
      body: [
        ['Total Rumah', data?.rumah?.total ?? 0],
        ['Rumah Aktif', data?.rumah?.aktif ?? 0],
        ['Rumah Kosong', data?.rumah?.kosong ?? 0],
        ['Berpenghuni', data?.rumah?.berpenghuni ?? 0],
        ['Jumlah Blok', data?.rumah?.jumlah_blok ?? 0],
      ],
      styles: { fontSize: 9 },
      headStyles: { fillColor: [22, 163, 74] },
    });

    autoTable(doc, {
      head: [['Keuangan', '']],
      body: [
        ['Total Kas RT', formatCurrency(data?.keuangan?.total_kas_rt)],
        ['Total Kas RW', formatCurrency(data?.keuangan?.total_kas_rw)],
        ['Total Kas Wilayah', formatCurrency(data?.keuangan?.total_kas_wilayah)],
        ['IPL Terkumpul', formatCurrency(data?.keuangan?.ipl_terkumpul)],
        ['IPL Tunggakan', formatCurrency(data?.keuangan?.ipl_tunggakan)],
      ],
      styles: { fontSize: 9 },
      headStyles: { fillColor: [217, 119, 6] },
    });

    autoTable(doc, {
      head: [['Surat', '']],
      body: [
        ['Total Surat', data?.surat?.total ?? 0],
        ['Surat Bulan Ini', data?.surat?.bulan_ini ?? 0],
        ['Surat Minggu Ini', data?.surat?.minggu_ini ?? 0],
      ],
      styles: { fontSize: 9 },
      headStyles: { fillColor: [8, 145, 178] },
    });

    autoTable(doc, {
      head: [['Pengaduan', '']],
      body: [
        ['Total Pengaduan', data?.pengaduan?.total ?? 0],
        ['Pengaduan Aktif', data?.pengaduan?.aktif ?? 0],
        ['Selesai', data?.pengaduan?.resolved ?? 0],
        ['Tingkat Penyelesaian', `${data?.pengaduan?.resolution_rate || 0}%`],
      ],
      styles: { fontSize: 9 },
      headStyles: { fillColor: [225, 29, 72] },
    });

    doc.save(`laporan-kelurahan-${data.periode?.replace(/\s+/g, '-') || 'export'}.pdf`);
  };

  const handleExportXLSX = () => {
    if (!data) return;
    const workbook = XLSX.utils.book_new();
    const summarySheet = XLSX.utils.aoa_to_sheet([
      ['Laporan Kelurahan', data.kelurahan?.nama_kelurahan || ''],
      ['Periode', data.periode || ''],
      ['Generated', data.generated_at || ''],
      [''],
      ['=== WILAYAH ==='],
      ['Total RW', data.wilayah?.total_rw || 0],
      ['Total RT/Blok', data.wilayah?.total_rt || 0],
      ['RW Aktif', data.wilayah?.rw_aktif || 0],
      [''],
      ['=== WARGA ==='],
      ['Total Warga', data.warga?.total || 0],
      ['Warga Aktif', data.warga?.aktif || 0],
      ['Tidak Aktif', data.warga?.tidak_aktif || 0],
      ['Laki-laki', data.warga?.laki_laki || 0],
      ['Perempuan', data.warga?.perempuan || 0],
      ['Kepala Keluarga', data.warga?.kepala_keluarga || 0],
      [''],
      ['=== RUMAH ==='],
      ['Total Rumah', data.rumah?.total || 0],
      ['Rumah Aktif', data.rumah?.aktif || 0],
      ['Rumah Kosong', data.rumah?.kosong || 0],
      ['Berpenghuni', data.rumah?.berpenghuni || 0],
      ['Jumlah Blok', data.rumah?.jumlah_blok || 0],
      [''],
      ['=== KEUANGAN ==='],
      ['Total Kas RT', data.keuangan?.total_kas_rt || 0],
      ['Total Kas RW', data.keuangan?.total_kas_rw || 0],
      ['Total Kas Wilayah', data.keuangan?.total_kas_wilayah || 0],
      ['IPL Terkumpul', data.keuangan?.ipl_terkumpul || 0],
      ['IPL Tunggakan', data.keuangan?.ipl_tunggakan || 0],
      [''],
      ['=== SURAT ==='],
      ['Total Surat', data.surat?.total || 0],
      ['Surat Bulan Ini', data.surat?.bulan_ini || 0],
      ['Surat Minggu Ini', data.surat?.minggu_ini || 0],
      [''],
      ['=== PENGADUAN ==='],
      ['Total Pengaduan', data.pengaduan?.total || 0],
      ['Pengaduan Aktif', data.pengaduan?.aktif || 0],
      ['Pengaduan Selesai', data.pengaduan?.resolved || 0],
      ['Tingkat Penyelesaian', `${data.pengaduan?.resolution_rate || 0}%`],
    ]);
    XLSX.utils.book_append_sheet(workbook, summarySheet, 'Ringkasan');
    XLSX.writeFile(workbook, `laporan-kelurahan-${data.periode?.replace(/\s+/g, '-') || 'export'}.xlsx`);
  };

  if (loading) {
    return (
      <div className="p-6 bg-[#efe7d2] dark:bg-gray-900 min-h-full flex items-center justify-center">
        <div className="text-center space-y-4">
          <div className="w-12 h-12 border-4 border-cyan-500 border-t-transparent rounded-full animate-spin mx-auto" />
          <p className="text-gray-500 dark:text-gray-400">Memuat laporan kelurahan...</p>
        </div>
      </div>
    );
  }

  if (error) {
    return (
      <div className="p-6 bg-[#efe7d2] dark:bg-gray-900 min-h-full">
        <div className="bg-red-50 dark:bg-red-900/20 border border-red-200 dark:border-red-800 rounded-lg p-4">
          <p className="text-red-600 dark:text-red-400 text-sm">Error: {error}</p>
        </div>
      </div>
    );
  }

  const sections = [
    {
      title: 'Wilayah', icon: Building2, color: 'from-emerald-500 to-teal-600',
      items: [
        { label: 'Total RW', value: data?.wilayah?.total_rw || 0 },
        { label: 'Total RT/Blok', value: data?.wilayah?.total_rt || 0 },
        { label: 'RW Aktif', value: data?.wilayah?.rw_aktif || 0 },
      ]
    },
    {
      title: 'Warga', icon: Users, color: 'from-blue-500 to-indigo-600',
      items: [
        { label: 'Total Warga', value: data?.warga?.total || 0 },
        { label: 'Warga Aktif', value: data?.warga?.aktif || 0 },
        { label: 'Tidak Aktif', value: data?.warga?.tidak_aktif || 0 },
        { label: 'Laki-laki', value: data?.warga?.laki_laki || 0 },
        { label: 'Perempuan', value: data?.warga?.perempuan || 0 },
        { label: 'Kepala Keluarga', value: data?.warga?.kepala_keluarga || 0 },
      ]
    },
    {
      title: 'Rumah', icon: Home, color: 'from-green-500 to-emerald-600',
      items: [
        { label: 'Total Rumah', value: data?.rumah?.total || 0 },
        { label: 'Rumah Aktif', value: data?.rumah?.aktif || 0 },
        { label: 'Rumah Kosong', value: data?.rumah?.kosong || 0 },
        { label: 'Berpenghuni', value: data?.rumah?.berpenghuni || 0 },
        { label: 'Jumlah Blok', value: data?.rumah?.jumlah_blok || 0 },
      ]
    },
    {
      title: 'Keuangan', icon: DollarSign, color: 'from-amber-500 to-orange-600',
      items: [
        { label: 'Total Kas RT', value: formatCurrency(data?.keuangan?.total_kas_rt) },
        { label: 'Total Kas RW', value: formatCurrency(data?.keuangan?.total_kas_rw) },
        { label: 'Total Kas Wilayah', value: formatCurrency(data?.keuangan?.total_kas_wilayah) },
        { label: 'IPL Terkumpul', value: formatCurrency(data?.keuangan?.ipl_terkumpul) },
        { label: 'IPL Tunggakan', value: formatCurrency(data?.keuangan?.ipl_tunggakan) },
      ]
    },
    {
      title: 'Surat', icon: FileText, color: 'from-cyan-500 to-blue-600',
      items: [
        { label: 'Total Surat', value: data?.surat?.total || 0 },
        { label: 'Surat Bulan Ini', value: data?.surat?.bulan_ini || 0 },
        { label: 'Surat Minggu Ini', value: data?.surat?.minggu_ini || 0 },
      ]
    },
    {
      title: 'Pengaduan', icon: AlertCircle, color: 'from-red-500 to-rose-600',
      items: [
        { label: 'Total Pengaduan', value: data?.pengaduan?.total || 0 },
        { label: 'Pengaduan Aktif', value: data?.pengaduan?.aktif || 0 },
        { label: 'Selesai', value: data?.pengaduan?.resolved || 0 },
        { label: 'Tingkat Penyelesaian', value: `${data?.pengaduan?.resolution_rate || 0}%` },
      ]
    },
  ];

  return (
    <div className="p-6 space-y-6 bg-[#efe7d2] dark:bg-gray-900 min-h-full">
      {/* Breadcrumb */}
      <div className="flex items-center gap-2 text-sm text-gray-500 dark:text-gray-400">
        <span>Kelurahan</span><span>/</span>
        <span className="text-gray-700 dark:text-gray-300 font-medium">Laporan</span>
      </div>

      {/* Header */}
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-3">
          <div className="w-10 h-10 bg-gradient-to-br from-indigo-500 to-purple-600 rounded-xl flex items-center justify-center shadow">
            <BarChart3 className="h-5 w-5 text-white" />
          </div>
          <div>
            <h1 className="text-2xl font-bold text-gray-900 dark:text-white">Laporan Kelurahan</h1>
            <p className="text-sm text-gray-500 dark:text-gray-400">
              {data?.kelurahan?.nama_kelurahan} · Periode: {data?.periode}
            </p>
          </div>
        </div>
        <div className="flex gap-2">
          <button onClick={fetchData} className="flex items-center gap-2 px-3 py-2 text-sm bg-[#f7f1de] dark:bg-gray-800 border border-[#d5cebc] dark:border-gray-700 rounded-lg hover:bg-[#e4dcc8] dark:hover:bg-gray-700 transition-colors">
            <RefreshCw className="h-4 w-4" />
          </button>
          <button onClick={handleExportXLSX} className="flex items-center gap-2 px-4 py-2 bg-green-500 hover:bg-green-600 text-white text-sm rounded-lg transition-colors">
            <Download className="h-4 w-4" />Export Ke Excel
          </button>
          <button onClick={handleExportPDF} className="flex items-center gap-2 px-4 py-2 bg-[#ed6f5c] hover:bg-[#e05544] text-white text-sm rounded-lg transition-colors">
            <Download className="h-4 w-4" />Print PDF
          </button>
        </div>
      </div>

      {/* Kelurahan Info */}
      {data?.kelurahan && (
        <div className="bg-gradient-to-r from-emerald-500 to-teal-600 rounded-xl p-4 text-white">
          <div className="flex items-center gap-3">
            <Building2 className="h-6 w-6" />
            <div>
              <h2 className="font-bold">{data.kelurahan.nama_kelurahan}</h2>
              <p className="text-emerald-100 text-sm">
                Kec. {data.kelurahan.kecamatan} · {data.kelurahan.kota}
                {data.kelurahan.lurah && ` · Lurah: ${data.kelurahan.lurah}`}
              </p>
            </div>
          </div>
        </div>
      )}

      {/* Report Sections */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
        {sections.map((section, idx) => (
          <div key={idx} className="bg-[#f7f1de] dark:bg-gray-800 rounded-lg shadow overflow-hidden">
            <div className={`bg-gradient-to-r ${section.color} p-4 flex items-center gap-3`}>
              <section.icon className="h-5 w-5 text-white" />
              <h3 className="text-base font-semibold text-white">{section.title}</h3>
            </div>
            <div className="p-4 space-y-2">
              {section.items.map((item, i) => (
                <div key={i} className="flex justify-between items-center py-1.5 border-b border-gray-100 dark:border-gray-700 last:border-0">
                  <span className="text-sm text-gray-600 dark:text-gray-400">{item.label}</span>
                  <span className="text-sm font-semibold text-gray-900 dark:text-white">{item.value}</span>
                </div>
              ))}
            </div>
          </div>
        ))}
      </div>

      {/* Generated timestamp */}
      <div className="text-center text-xs text-gray-400 dark:text-gray-500">
        Laporan dibuat pada: {data?.generated_at ? new Date(data.generated_at).toLocaleString('id-ID') : '-'}
      </div>
    </div>
  );
};

export default LaporanKelurahan;
