import React, { useState, useEffect } from 'react';
import axios from 'axios';
import jsPDF from 'jspdf';
import autoTable from 'jspdf-autotable';
import * as XLSX from 'xlsx';
import { useAuth } from '../../contexts/AuthContext';
import { useRWFilter } from '../../contexts/RWFilterContext';
import { API_BASE_URL } from '../../config/api';
import {
  BarChart3, Download, RefreshCw, Users, Home, DollarSign, FileText, AlertCircle,
  TrendingUp, TrendingDown,
} from 'lucide-react';
import {
  Select, SelectContent, SelectItem, SelectTrigger, SelectValue,
} from '@/components/ui/select';
import { Button } from '@/components/ui/button';

const FULL_MONTHS = ["", "Januari", "Februari", "Maret", "April", "Mei", "Juni", "Juli", "Agustus", "September", "Oktober", "November", "Desember"];

const LaporanRW = () => {
  const { token } = useAuth();
  const { rtId } = useRWFilter();
  const [data, setData] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  // Pos Anggaran
  const now = new Date();
  const [tahun, setTahun] = useState(String(now.getFullYear()));
  const [bulanDari, setBulanDari] = useState("1");
  const [bulanSampai, setBulanSampai] = useState(String(now.getMonth() + 1));
  const [posData, setPosData] = useState([]);
  const [posLoading, setPosLoading] = useState(false);
  const years = Array.from({ length: 5 }, (_, i) => String(now.getFullYear() - i));

  useEffect(() => { fetchData(); }, [token, rtId]);
  useEffect(() => { fetchPosAnggaran(); }, [token, rtId]);

  const fetchData = async () => {
    try {
      setLoading(true);
      const headers = { Authorization: `Bearer ${token}` };
      const params = rtId ? { rt_id: rtId } : {};
      const res = await axios.get(`${API_BASE_URL}/api/rw/reports/summary`, { headers, params });
      setData(res.data);
      setError(null);
    } catch (err) {
      setError(err.response?.data?.detail || err.message);
    } finally {
      setLoading(false);
    }
  };

  const fetchPosAnggaran = async () => {
    setPosLoading(true);
    try {
      const headers = { Authorization: `Bearer ${token}` };
      const params = {
        tahun_dari: tahun, bulan_dari: bulanDari,
        tahun_sampai: tahun, bulan_sampai: bulanSampai,
      };
      const res = await axios.get(`${API_BASE_URL}/api/rw/reports/pos-anggaran`, { headers, params });
      setPosData(res.data || []);
    } catch (err) {
      setPosData([]);
    } finally {
      setPosLoading(false);
    }
  };

  const formatCurrency = (val) =>
    new Intl.NumberFormat('id-ID', { style: 'currency', currency: 'IDR', minimumFractionDigits: 0 }).format(val || 0);

  const posTotalPemasukan = posData.reduce((s, d) => s + d.total_pemasukan, 0);
  const posTotalPengeluaran = posData.reduce((s, d) => s + d.total_pengeluaran, 0);
  const posTotalSaldo = posTotalPemasukan - posTotalPengeluaran;

  const handleExportPDF = () => {
    if (!data) return;
    const doc = new jsPDF('p', 'mm', 'a4');
    doc.setFont('helvetica', 'bold');
    doc.setFontSize(14);
    doc.text('Laporan RW', 105, 16, { align: 'center' });
    doc.setFont('helvetica', 'normal');
    doc.setFontSize(9);
    doc.text(`Periode: ${data?.periode || '-'}`, 15, 24);
    doc.text(`Generated: ${data?.generated_at ? new Date(data.generated_at).toLocaleString('id-ID') : '-'}`, 15, 30);
    doc.setDrawColor(200, 200, 200);
    doc.line(15, 34, 195, 34);

    autoTable(doc, {
      startY: 40,
      head: [['Warga', '']],
      body: [
        ['Total Warga', data?.warga?.total ?? 0],
        ['Warga Aktif', data?.warga?.aktif ?? 0],
        ['Tidak Aktif', data?.warga?.tidak_aktif ?? 0],
        ['Laki-laki', data?.warga?.laki_laki ?? 0],
        ['Perempuan', data?.warga?.perempuan ?? 0],
        ['Kepala Keluarga', data?.warga?.kepala_keluarga ?? 0],
      ],
      styles: { fontSize: 9 },
      headStyles: { fillColor: [79, 70, 229] },
    });

    autoTable(doc, {
      head: [['Rumah', '']],
      body: [
        ['Total Rumah', data?.rumah?.total ?? 0],
        ['Rumah Aktif', data?.rumah?.aktif ?? 0],
        ['Rumah Kosong', data?.rumah?.kosong ?? 0],
        ['Berpenghuni', data?.rumah?.berpenghuni ?? 0],
        ['Jumlah Blok/RT', data?.rumah?.jumlah_blok ?? 0],
      ],
      styles: { fontSize: 9 },
      headStyles: { fillColor: [5, 150, 105] },
    });

    autoTable(doc, {
      head: [['Keuangan', '']],
      body: [
        ['Saldo RT', formatCurrency(data?.keuangan?.saldo_rt)],
        ['Saldo RW', formatCurrency(data?.keuangan?.saldo_rw)],
        ['Total Kas', formatCurrency(data?.keuangan?.total_kas)],
        ['Pemasukan RT', formatCurrency(data?.keuangan?.total_pemasukan_rt)],
        ['Pengeluaran RT', formatCurrency(data?.keuangan?.total_pengeluaran_rt)],
      ],
      styles: { fontSize: 9 },
      headStyles: { fillColor: [217, 119, 6] },
    });

    autoTable(doc, {
      head: [['Surat', '']],
      body: [
        ['Total Surat', data?.surat?.total ?? 0],
        ['Surat Bulan Ini', data?.surat?.bulan_ini ?? 0],
      ],
      styles: { fontSize: 9 },
      headStyles: { fillColor: [8, 145, 178] },
    });

    autoTable(doc, {
      head: [['Pengaduan', '']],
      body: [
        ['Total Pengaduan', data?.pengaduan?.total ?? 0],
        ['Pengaduan Aktif', data?.pengaduan?.aktif ?? 0],
        ['Selesai', data?.pengaduan?.resolved ?? 0],
      ],
      styles: { fontSize: 9 },
      headStyles: { fillColor: [225, 29, 72] },
    });

    if (posData.length) {
      const posRows = posData.map(p => [
        p.nama_pos,
        formatCurrency(p.total_pemasukan),
        formatCurrency(p.total_pengeluaran),
        formatCurrency(p.saldo),
      ]);
      posRows.push([
        'TOTAL',
        formatCurrency(posTotalPemasukan),
        formatCurrency(posTotalPengeluaran),
        formatCurrency(posTotalSaldo),
      ]);
      autoTable(doc, {
        head: [[`Pos Anggaran (${FULL_MONTHS[Number(bulanDari)]}-${FULL_MONTHS[Number(bulanSampai)]} ${tahun})`, 'Pemasukan', 'Pengeluaran', 'Saldo']],
        body: posRows,
        styles: { fontSize: 8 },
        headStyles: { fillColor: [67, 56, 202] },
      });
    }

    doc.save(`laporan-rw-${data.periode?.replace(/\s+/g, '-') || 'export'}.pdf`);
  };

  const handleExportXLSX = () => {
    if (!data) return;
    const workbook = XLSX.utils.book_new();

    const summarySheet = XLSX.utils.aoa_to_sheet([
      ['Laporan RW', data.periode || ''],
      ['Generated', data.generated_at || ''],
      [''],
      ['=== WARGA ==='],
      ['Total Warga', data.warga?.total || 0],
      ['Warga Aktif', data.warga?.aktif || 0],
      ['Tidak Aktif', data.warga?.tidak_aktif || 0],
      ['Laki-laki', data.warga?.laki_laki || 0],
      ['Perempuan', data.warga?.perempuan || 0],
      ['Kepala Keluarga', data.warga?.kepala_keluarga || 0],
      [''],
      ['=== RUMAH ==='],
      ['Total Rumah', data.rumah?.total || 0],
      ['Rumah Aktif', data.rumah?.aktif || 0],
      ['Rumah Kosong', data.rumah?.kosong || 0],
      ['Berpenghuni', data.rumah?.berpenghuni || 0],
      ['Jumlah Blok/RT', data.rumah?.jumlah_blok || 0],
      [''],
      ['=== KEUANGAN ==='],
      ['Saldo RT', data.keuangan?.saldo_rt || 0],
      ['Saldo RW', data.keuangan?.saldo_rw || 0],
      ['Total Kas', data.keuangan?.total_kas || 0],
      ['Pemasukan RT', data.keuangan?.total_pemasukan_rt || 0],
      ['Pengeluaran RT', data.keuangan?.total_pengeluaran_rt || 0],
      [''],
      ['=== SURAT ==='],
      ['Total Surat', data.surat?.total || 0],
      ['Surat Bulan Ini', data.surat?.bulan_ini || 0],
      [''],
      ['=== PENGADUAN ==='],
      ['Total Pengaduan', data.pengaduan?.total || 0],
      ['Pengaduan Aktif', data.pengaduan?.aktif || 0],
      ['Pengaduan Selesai', data.pengaduan?.resolved || 0],
    ]);
    XLSX.utils.book_append_sheet(workbook, summarySheet, 'Ringkasan');

    if (posData.length) {
      const posSheet = XLSX.utils.json_to_sheet(
        posData.map(p => ({
          'Pos': p.nama_pos,
          'Kategori Pengeluaran': p.kategori_pengeluaran_nama || '-',
          'Pemasukan': p.total_pemasukan,
          'Pengeluaran': p.total_pengeluaran,
          'Saldo': p.saldo,
        }))
      );
      XLSX.utils.book_append_sheet(workbook, posSheet, 'Pos Anggaran');
    }

    XLSX.writeFile(workbook, `laporan-rw-${data.periode?.replace(/\s+/g, '-') || 'export'}.xlsx`);
  };

  if (loading) {
    return (
      <div className="p-6 bg-[#efe7d2] dark:bg-gray-900 min-h-full flex items-center justify-center">
        <div className="text-center space-y-4">
          <div className="w-12 h-12 border-4 border-cyan-500 border-t-transparent rounded-full animate-spin mx-auto" />
          <p className="text-gray-500 dark:text-gray-400">Memuat laporan...</p>
        </div>
      </div>
    );
  }

  if (error) {
    return (
      <div className="p-6 bg-[#efe7d2] dark:bg-gray-900 min-h-full">
        <div className="bg-red-50 dark:bg-red-900/20 border border-red-200 dark:border-red-800 rounded-lg p-4">
          <p className="text-red-600 dark:text-red-400 text-sm">Error: {error}</p>
        </div>
      </div>
    );
  }

  const sections = [
    {
      title: 'Warga', icon: Users, color: 'from-blue-500 to-indigo-600',
      items: [
        { label: 'Total Warga', value: data?.warga?.total || 0 },
        { label: 'Warga Aktif', value: data?.warga?.aktif || 0 },
        { label: 'Tidak Aktif', value: data?.warga?.tidak_aktif || 0 },
        { label: 'Laki-laki', value: data?.warga?.laki_laki || 0 },
        { label: 'Perempuan', value: data?.warga?.perempuan || 0 },
        { label: 'Kepala Keluarga', value: data?.warga?.kepala_keluarga || 0 },
      ]
    },
    {
      title: 'Rumah', icon: Home, color: 'from-green-500 to-emerald-600',
      items: [
        { label: 'Total Rumah', value: data?.rumah?.total || 0 },
        { label: 'Rumah Aktif', value: data?.rumah?.aktif || 0 },
        { label: 'Rumah Kosong', value: data?.rumah?.kosong || 0 },
        { label: 'Berpenghuni', value: data?.rumah?.berpenghuni || 0 },
        { label: 'Jumlah Blok/RT', value: data?.rumah?.jumlah_blok || 0 },
      ]
    },
    {
      title: 'Keuangan', icon: DollarSign, color: 'from-amber-500 to-orange-600',
      items: [
        { label: 'Saldo RT', value: formatCurrency(data?.keuangan?.saldo_rt) },
        { label: 'Saldo RW', value: formatCurrency(data?.keuangan?.saldo_rw) },
        { label: 'Total Kas', value: formatCurrency(data?.keuangan?.total_kas) },
        { label: 'Pemasukan RT', value: formatCurrency(data?.keuangan?.total_pemasukan_rt) },
        { label: 'Pengeluaran RT', value: formatCurrency(data?.keuangan?.total_pengeluaran_rt) },
      ]
    },
    {
      title: 'Surat', icon: FileText, color: 'from-cyan-500 to-blue-600',
      items: [
        { label: 'Total Surat', value: data?.surat?.total || 0 },
        { label: 'Surat Bulan Ini', value: data?.surat?.bulan_ini || 0 },
      ]
    },
    {
      title: 'Pengaduan', icon: AlertCircle, color: 'from-red-500 to-rose-600',
      items: [
        { label: 'Total Pengaduan', value: data?.pengaduan?.total || 0 },
        { label: 'Pengaduan Aktif', value: data?.pengaduan?.aktif || 0 },
        { label: 'Selesai', value: data?.pengaduan?.resolved || 0 },
      ]
    },
  ];

  return (
    <div className="p-6 space-y-6 bg-[#efe7d2] dark:bg-gray-900 min-h-full">
      {/* Breadcrumb */}
      <div className="flex items-center gap-2 text-sm text-gray-500 dark:text-gray-400">
        <span>RW</span><span>/</span>
        <span className="text-gray-700 dark:text-gray-300 font-medium">Laporan</span>
      </div>

      {/* Header */}
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-3">
          <div className="w-10 h-10 bg-gradient-to-br from-indigo-500 to-purple-600 rounded-xl flex items-center justify-center shadow">
            <BarChart3 className="h-5 w-5 text-white" />
          </div>
          <div>
            <h1 className="text-2xl font-bold text-gray-900 dark:text-white">Laporan RW</h1>
            <p className="text-sm text-gray-500 dark:text-gray-400">
              Periode: {data?.periode} · Generated: {data?.generated_at ? new Date(data.generated_at).toLocaleString('id-ID') : '-'}
            </p>
          </div>
        </div>
        <div className="flex gap-2">
          <button onClick={() => { fetchData(); fetchPosAnggaran(); }} className="flex items-center gap-2 px-3 py-2 text-sm bg-[#f7f1de] dark:bg-gray-800 border border-[#d5cebc] dark:border-gray-700 rounded-lg hover:bg-[#e4dcc8] dark:hover:bg-gray-700 transition-colors">
            <RefreshCw className="h-4 w-4" />
          </button>
          <button onClick={handleExportXLSX} className="flex items-center gap-2 px-4 py-2 bg-green-500 hover:bg-green-600 text-white text-sm rounded-lg transition-colors">
            <Download className="h-4 w-4" />Export XLSX
          </button>
          <button onClick={handleExportPDF} className="flex items-center gap-2 px-4 py-2 bg-[#ed6f5c] hover:bg-[#e05544] text-white text-sm rounded-lg transition-colors">
            <Download className="h-4 w-4" />Export PDF
          </button>
        </div>
      </div>

      {/* Report Sections */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
        {sections.map((section, idx) => (
          <div key={idx} className="bg-[#f7f1de] dark:bg-gray-800 rounded-lg shadow overflow-hidden">
            <div className={`bg-gradient-to-r ${section.color} p-4 flex items-center gap-3`}>
              <section.icon className="h-5 w-5 text-white" />
              <h3 className="text-base font-semibold text-white">{section.title}</h3>
            </div>
            <div className="p-4 space-y-2">
              {section.items.map((item, i) => (
                <div key={i} className="flex justify-between items-center py-1.5 border-b border-gray-100 dark:border-gray-700 last:border-0">
                  <span className="text-sm text-gray-600 dark:text-gray-400">{item.label}</span>
                  <span className="text-sm font-semibold text-gray-900 dark:text-white">{item.value}</span>
                </div>
              ))}
            </div>
          </div>
        ))}
      </div>

      {/* Pos Anggaran */}
      <div className="bg-[#f7f1de] dark:bg-gray-800 rounded-lg border border-[#d5cebc] dark:border-gray-700 p-5 space-y-5">
        <div className="flex flex-wrap items-end gap-3 justify-between">
          <div>
            <h2 className="text-xl font-bold text-gray-900 dark:text-white">Laporan Pos Anggaran</h2>
            <p className="text-sm text-gray-500 dark:text-gray-400 mt-0.5">
              Saldo per pos iuran Kas RW — pemasukan terkumpul vs pengeluaran
            </p>
          </div>
          <div className="flex flex-wrap items-end gap-2">
            <div>
              <label className="text-xs text-gray-500 block mb-1">Tahun</label>
              <Select value={tahun} onValueChange={setTahun}>
                <SelectTrigger className="w-28"><SelectValue /></SelectTrigger>
                <SelectContent>
                  {years.map(y => <SelectItem key={y} value={y}>{y}</SelectItem>)}
                </SelectContent>
              </Select>
            </div>
            <div>
              <label className="text-xs text-gray-500 block mb-1">Dari Bulan</label>
              <Select value={bulanDari} onValueChange={setBulanDari}>
                <SelectTrigger className="w-32"><SelectValue /></SelectTrigger>
                <SelectContent>
                  {FULL_MONTHS.slice(1).map((m, i) => (
                    <SelectItem key={i + 1} value={String(i + 1)}>{m}</SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>
            <div>
              <label className="text-xs text-gray-500 block mb-1">Sampai Bulan</label>
              <Select value={bulanSampai} onValueChange={setBulanSampai}>
                <SelectTrigger className="w-32"><SelectValue /></SelectTrigger>
                <SelectContent>
                  {FULL_MONTHS.slice(1).map((m, i) => (
                    <SelectItem key={i + 1} value={String(i + 1)}>{m}</SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>
            <Button onClick={fetchPosAnggaran} disabled={posLoading} className="bg-[#ed6f5c] hover:bg-[#e05544] text-white gap-2">
              <RefreshCw size={14} className={posLoading ? "animate-spin" : ""} />
              {posLoading ? "Memuat..." : "Tampilkan"}
            </Button>
          </div>
        </div>

        {posData.length > 0 && (
          <div className="grid grid-cols-1 sm:grid-cols-3 gap-3">
            <div className="bg-[#efe7d2] dark:bg-gray-900 rounded-lg border border-[#d5cebc] dark:border-gray-700 p-4">
              <p className="text-xs font-semibold text-gray-500 uppercase">Total Pemasukan</p>
              <p className="text-xl sm:text-2xl font-bold text-green-600 dark:text-green-400 mt-1 break-all">{formatCurrency(posTotalPemasukan)}</p>
            </div>
            <div className="bg-[#efe7d2] dark:bg-gray-900 rounded-lg border border-[#d5cebc] dark:border-gray-700 p-4">
              <p className="text-xs font-semibold text-gray-500 uppercase">Total Pengeluaran</p>
              <p className="text-xl sm:text-2xl font-bold text-red-600 dark:text-red-400 mt-1 break-all">{formatCurrency(posTotalPengeluaran)}</p>
            </div>
            <div className="bg-[#efe7d2] dark:bg-gray-900 rounded-lg border border-[#d5cebc] dark:border-gray-700 p-4">
              <p className="text-xs font-semibold text-gray-500 uppercase">Saldo Total</p>
              <p className={`text-xl sm:text-2xl font-bold mt-1 break-all ${posTotalSaldo >= 0 ? "text-green-600 dark:text-green-400" : "text-red-600 dark:text-red-400"}`}>
                {formatCurrency(posTotalSaldo)}
              </p>
            </div>
          </div>
        )}

        {posLoading ? (
          <div className="text-center py-16 text-gray-400">Memuat data...</div>
        ) : posData.length === 0 ? (
          <div className="text-center py-16 text-gray-400">
            <p className="font-medium">Belum ada data Pos Anggaran</p>
            <p className="text-sm mt-1">
              Pastikan Kategori Biaya sudah dipasangkan (Pemasukan ↔ Pengeluaran) di menu Kategori Biaya RW.
            </p>
          </div>
        ) : (
          <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-4">
            {posData.map((pos) => {
              const surplus = pos.saldo >= 0;
              const pct = pos.total_pemasukan > 0
                ? Math.min(100, Math.round((pos.total_pengeluaran / pos.total_pemasukan) * 100))
                : 0;
              return (
                <div key={pos.kategori_pemasukan_id} className="bg-[#efe7d2] dark:bg-gray-900 rounded-lg border border-[#d5cebc] dark:border-gray-700 shadow-sm overflow-hidden">
                  <div className={`h-1.5 w-full ${surplus ? "bg-green-400" : "bg-red-400"}`} />
                  <div className="p-5">
                    <div className="flex items-start justify-between mb-3">
                      <div>
                        <h3 className="font-semibold text-gray-800 dark:text-gray-100">{pos.nama_pos}</h3>
                        {pos.kategori_pengeluaran_nama && (
                          <p className="text-xs text-gray-400 mt-0.5">↔ {pos.kategori_pengeluaran_nama}</p>
                        )}
                      </div>
                      <div className={`p-1.5 rounded-full ${surplus ? "bg-green-100 text-green-600" : "bg-red-100 text-red-600"}`}>
                        {surplus ? <TrendingUp size={16} /> : <TrendingDown size={16} />}
                      </div>
                    </div>

                    <div className="space-y-1.5 text-sm">
                      <div className="flex justify-between">
                        <span className="text-gray-500">Pemasukan</span>
                        <span className="font-medium text-green-600">{formatCurrency(pos.total_pemasukan)}</span>
                      </div>
                      <div className="flex justify-between">
                        <span className="text-gray-500">Pengeluaran</span>
                        <span className="font-medium text-red-600">{formatCurrency(pos.total_pengeluaran)}</span>
                      </div>
                      {pos.total_pemasukan > 0 && (
                        <div className="pt-1">
                          <div className="w-full bg-gray-200 dark:bg-gray-700 rounded-full h-1.5">
                            <div
                              className={`h-1.5 rounded-full transition-all ${surplus ? "bg-green-400" : "bg-red-400"}`}
                              style={{ width: `${pct}%` }}
                            />
                          </div>
                          <p className="text-xs text-gray-400 mt-0.5">{pct}% terpakai</p>
                        </div>
                      )}
                    </div>

                    <div className="mt-3 pt-3 border-t border-[#d5cebc] dark:border-gray-700 flex justify-between items-center">
                      <span className="text-xs font-semibold text-gray-500 uppercase">Saldo</span>
                      <span className={`text-lg font-bold ${surplus ? "text-green-600 dark:text-green-400" : "text-red-600 dark:text-red-400"}`}>
                        {formatCurrency(pos.saldo)}
                      </span>
                    </div>
                    {!surplus && (
                      <p className="text-xs text-red-500 mt-1">⚠ Defisit — disubsidi sementara dari pos lain</p>
                    )}
                  </div>
                </div>
              );
            })}
          </div>
        )}
      </div>
    </div>
  );
};

export default LaporanRW;
