import React, { useState, useEffect, useCallback } from 'react';
import { createPortal } from 'react-dom';
import { API_BASE_URL } from '@/config/api';
import { toast } from '@/components/ui/sonner';
import {
  Smartphone, Plus, Trash2, RefreshCw, Wifi, WifiOff,
  QrCode, X, Loader2, CheckCircle2
} from 'lucide-react';

function DeviceStatusBadge({ ready, qr }) {
  if (qr) return (
    <span className="inline-flex items-center gap-1 px-2 py-0.5 rounded-full text-xs font-medium bg-yellow-100 text-yellow-700 border border-yellow-200">
      <QrCode size={11} /> Menunggu Scan QR
    </span>
  );
  if (ready) return (
    <span className="inline-flex items-center gap-1 px-2 py-0.5 rounded-full text-xs font-medium bg-green-100 text-green-700 border border-green-200">
      <Wifi size={11} /> Online
    </span>
  );
  return (
    <span className="inline-flex items-center gap-1 px-2 py-0.5 rounded-full text-xs font-medium bg-gray-100 text-gray-500 border border-gray-200">
      <WifiOff size={11} /> Offline
    </span>
  );
}

const token  = () => localStorage.getItem('vendor_token');
const hdrs   = () => ({ Authorization: `Bearer ${token()}`, 'Content-Type': 'application/json' });

export default function WhatsAppDevices() {
  const [devices, setDevices]       = useState([]);
  const [loading, setLoading]       = useState(true);
  const [showModal, setShowModal]   = useState(false);
  const [newName, setNewName]       = useState('');
  const [newNotes, setNewNotes]     = useState('');
  const [adding, setAdding]         = useState(false);
  const [deletingId, setDeletingId] = useState(null);
  const [qrModal, setQrModal]       = useState(null); // { id, deviceKey, name, qr }

  const loadDevices = useCallback(async () => {
    if (!token()) return;
    try {
      const res = await fetch(`${API_BASE_URL}/api/whatsapp-devices`, { headers: hdrs() });
      if (res.ok) setDevices(await res.json());
    } catch { /* silent */ } finally {
      setLoading(false);
    }
  }, [token]);

  useEffect(() => { loadDevices(); }, [loadDevices]);

  // Auto-refresh status setiap 10 detik
  useEffect(() => {
    const id = setInterval(loadDevices, 10_000);
    return () => clearInterval(id);
  }, [loadDevices]);

  // Polling QR modal: jika QR muncul, update qrModal.qr
  useEffect(() => {
    if (!qrModal) return;
    const id = setInterval(async () => {
      try {
        const res = await fetch(`${API_BASE_URL}/api/whatsapp-devices/${qrModal.id}/status`, { headers: hdrs() });
        if (res.ok) {
          const data = await res.json();
          if (data.ready) {
            toast.success(`Device "${qrModal.name}" berhasil terhubung!`);
            setQrModal(null);
            loadDevices();
          } else if (data.qr) {
            setQrModal(prev => prev ? { ...prev, qr: data.qr } : null);
          }
        }
      } catch { /* silent */ }
    }, 3000);
    return () => clearInterval(id);
  }, [qrModal]);

  const handleAdd = async (e) => {
    e.preventDefault();
    if (!newName.trim()) return;
    setAdding(true);
    try {
      const res = await fetch(`${API_BASE_URL}/api/whatsapp-devices`, {
        method: 'POST', headers: hdrs(),
        body: JSON.stringify({ name: newName.trim(), notes: newNotes.trim() || null })
      });
      const data = await res.json();
      if (!res.ok) { toast.error(data.detail || 'Gagal menambah device'); return; }
      toast.success('Device ditambahkan! Scan QR untuk menghubungkan.');
      setShowModal(false);
      setNewName(''); setNewNotes('');
      await loadDevices();
      // Buka QR modal jika QR sudah tersedia
      setQrModal({ id: data.id, deviceKey: data.device_key, name: data.name, qr: data.qr });
    } catch { toast.error('Gagal menghubungi server'); }
    finally { setAdding(false); }
  };

  const handleDelete = async (device) => {
    if (!window.confirm(`Hapus device "${device.name}"? Device akan logout dari WhatsApp.`)) return;
    setDeletingId(device.id);
    try {
      const res = await fetch(`${API_BASE_URL}/api/whatsapp-devices/${device.id}`, {
        method: 'DELETE', headers: hdrs()
      });
      if (res.ok) { toast.success('Device dihapus'); loadDevices(); }
      else { const d = await res.json(); toast.error(d.detail || 'Gagal menghapus device'); }
    } catch { toast.error('Gagal menghubungi server'); }
    finally { setDeletingId(null); }
  };

  const openQr = (device) => {
    if (device.qr) setQrModal({ id: device.id, deviceKey: device.device_key, name: device.name, qr: device.qr });
    else toast.info('QR tidak tersedia. Device mungkin sedang inisialisasi, coba beberapa saat lagi.');
  };

  return (
    <div className="p-6 space-y-5 bg-[#f7f1de] dark:bg-gray-900 min-h-full">
      {/* Header */}
      <div className="flex items-center justify-between gap-3">
        <div className="flex items-center gap-3">
          <div className="w-10 h-10 rounded-xl bg-green-600 flex items-center justify-center shadow">
            <Smartphone size={20} className="text-white" />
          </div>
          <div>
            <h1 className="text-2xl font-bold text-gray-900 dark:text-white">WhatsApp Devices</h1>
            <p className="text-sm text-gray-500 dark:text-gray-400">Kelola perangkat WhatsApp terpusat untuk semua tenant</p>
          </div>
        </div>
        <div className="flex gap-2">
          <button onClick={loadDevices}
            className="p-2 rounded-lg bg-white dark:bg-gray-800 shadow-sm hover:bg-gray-100 dark:hover:bg-gray-700"
            title="Refresh">
            <RefreshCw size={16} className="text-gray-500" />
          </button>
          <button onClick={() => setShowModal(true)}
            className="flex items-center gap-2 px-4 py-2 rounded-xl bg-green-600 hover:bg-green-700 text-white text-sm font-medium shadow">
            <Plus size={16} /> Tambah Device
          </button>
        </div>
      </div>

      {/* Info banner */}
      <div className="bg-green-50 dark:bg-green-900/20 border border-green-200 dark:border-green-800 rounded-xl px-4 py-3 text-sm text-green-800 dark:text-green-300">
        <strong>Cara kerja:</strong> Tambah device WhatsApp di sini → QR muncul → Scan dengan aplikasi WhatsApp (Linked Device) → Device terhubung. Setiap tenant dapat dipilih menggunakan device tertentu di menu Subscription.
      </div>

      {/* Device list */}
      {loading ? (
        <div className="flex items-center justify-center py-16">
          <Loader2 size={28} className="animate-spin text-green-600" />
        </div>
      ) : devices.length === 0 ? (
        <div className="bg-white dark:bg-gray-800 rounded-2xl shadow p-12 text-center">
          <Smartphone size={48} className="mx-auto text-gray-300 dark:text-gray-600 mb-3" />
          <p className="text-gray-500 dark:text-gray-400 text-sm mb-4">Belum ada device WhatsApp terdaftar</p>
          <button onClick={() => setShowModal(true)}
            className="flex items-center gap-2 px-4 py-2 rounded-xl bg-green-600 hover:bg-green-700 text-white text-sm font-medium mx-auto">
            <Plus size={15} /> Tambah Device Pertama
          </button>
        </div>
      ) : (
        <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-3">
          {devices.map(dev => (
            <div key={dev.id} className="bg-white dark:bg-gray-800 rounded-2xl shadow p-5 flex flex-col gap-3">
              <div className="flex items-start justify-between gap-2">
                <div className="flex items-center gap-2 min-w-0">
                  <div className={`w-9 h-9 rounded-xl flex items-center justify-center flex-shrink-0 ${dev.ready ? 'bg-green-100' : 'bg-gray-100 dark:bg-gray-700'}`}>
                    <Smartphone size={18} className={dev.ready ? 'text-green-600' : 'text-gray-400'} />
                  </div>
                  <div className="min-w-0">
                    <p className="font-semibold text-gray-900 dark:text-white text-sm truncate">{dev.name}</p>
                    {dev.phone_number && (
                      <p className="text-xs text-gray-400">+{dev.phone_number}</p>
                    )}
                  </div>
                </div>
                <DeviceStatusBadge ready={dev.ready} qr={dev.qr} />
              </div>

              {dev.notes && (
                <p className="text-xs text-gray-500 dark:text-gray-400 bg-gray-50 dark:bg-gray-700/50 rounded-lg px-3 py-2">
                  {dev.notes}
                </p>
              )}

              {dev.last_sync && (
                <p className="text-xs text-gray-400">
                  Sinkron: {new Date(dev.last_sync).toLocaleString('id-ID')}
                </p>
              )}

              <div className="flex gap-2 mt-auto pt-2 border-t border-gray-100 dark:border-gray-700">
                {dev.qr && !dev.ready && (
                  <button onClick={() => openQr(dev)}
                    className="flex-1 flex items-center justify-center gap-1.5 px-3 py-1.5 rounded-lg bg-yellow-50 text-yellow-700 border border-yellow-200 text-xs font-medium hover:bg-yellow-100 transition-colors">
                    <QrCode size={13} /> Lihat QR
                  </button>
                )}
                {dev.ready && (
                  <div className="flex-1 flex items-center justify-center gap-1.5 px-3 py-1.5 rounded-lg bg-green-50 text-green-700 text-xs font-medium">
                    <CheckCircle2 size={13} /> Terhubung
                  </div>
                )}
                <button onClick={() => handleDelete(dev)}
                  disabled={!!deletingId}
                  className="flex items-center justify-center gap-1 px-3 py-1.5 rounded-lg bg-red-50 text-red-600 border border-red-200 text-xs font-medium hover:bg-red-100 transition-colors disabled:opacity-50">
                  {deletingId === dev.id ? <Loader2 size={13} className="animate-spin" /> : <Trash2 size={13} />}
                </button>
              </div>
            </div>
          ))}
        </div>
      )}

      {/* Modal tambah device */}
      {showModal && createPortal(
        <div className="fixed inset-0 bg-black/60 backdrop-blur-sm flex items-center justify-center z-[9999] p-4">
          <div className="bg-white dark:bg-gray-800 rounded-2xl shadow-xl w-full max-w-md p-6">
            <div className="flex items-center justify-between mb-4">
              <h2 className="text-lg font-bold text-gray-900 dark:text-white">Tambah Device WhatsApp</h2>
              <button onClick={() => setShowModal(false)} className="p-1.5 rounded-lg hover:bg-gray-100 dark:hover:bg-gray-700">
                <X size={18} className="text-gray-500" />
              </button>
            </div>
            <form onSubmit={handleAdd} className="space-y-4">
              <div>
                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                  Nama Device <span className="text-red-500">*</span>
                </label>
                <input
                  type="text" value={newName} onChange={e => setNewName(e.target.value)}
                  placeholder="e.g. WA Pengurus RT 01, WA Kelurahan Sriwedari"
                  className="w-full border border-gray-300 dark:border-gray-600 rounded-xl px-3 py-2 text-sm bg-white dark:bg-gray-700 text-gray-900 dark:text-white focus:ring-2 focus:ring-green-500 focus:border-transparent"
                  required autoFocus
                />
              </div>
              <div>
                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">Catatan (opsional)</label>
                <input
                  type="text" value={newNotes} onChange={e => setNewNotes(e.target.value)}
                  placeholder="Nomor HP, PIC, dll"
                  className="w-full border border-gray-300 dark:border-gray-600 rounded-xl px-3 py-2 text-sm bg-white dark:bg-gray-700 text-gray-900 dark:text-white focus:ring-2 focus:ring-green-500 focus:border-transparent"
                />
              </div>
              <div className="flex gap-3 pt-2">
                <button type="button" onClick={() => setShowModal(false)}
                  className="flex-1 px-4 py-2 rounded-xl border border-gray-300 dark:border-gray-600 text-sm text-gray-600 dark:text-gray-300 hover:bg-gray-50 dark:hover:bg-gray-700">
                  Batal
                </button>
                <button type="submit" disabled={adding || !newName.trim()}
                  className="flex-1 flex items-center justify-center gap-2 px-4 py-2 rounded-xl bg-green-600 hover:bg-green-700 text-white text-sm font-medium disabled:opacity-50">
                  {adding ? <Loader2 size={15} className="animate-spin" /> : <Plus size={15} />}
                  {adding ? 'Membuat...' : 'Buat Device'}
                </button>
              </div>
            </form>
          </div>
        </div>,
        document.body
      )}

      {/* Modal QR Code */}
      {qrModal && createPortal(
        <div className="fixed inset-0 bg-black/60 backdrop-blur-sm flex items-center justify-center z-[9999] p-4">
          <div className="bg-white dark:bg-gray-800 rounded-2xl shadow-xl w-full max-w-sm p-6 text-center">
            <div className="flex items-center justify-between mb-4">
              <h2 className="text-lg font-bold text-gray-900 dark:text-white">Scan QR Code</h2>
              <button onClick={() => setQrModal(null)} className="p-1.5 rounded-lg hover:bg-gray-100 dark:hover:bg-gray-700">
                <X size={18} className="text-gray-500" />
              </button>
            </div>
            <p className="text-sm text-gray-500 dark:text-gray-400 mb-4">
              Buka WhatsApp → <strong>Perangkat Tertaut</strong> → <strong>Tautkan Perangkat</strong> → scan QR di bawah ini
            </p>
            {qrModal.qr ? (
              <div className="flex justify-center mb-4">
                <img src={qrModal.qr} alt="QR Code" className="w-56 h-56 rounded-xl border-4 border-gray-100" />
              </div>
            ) : (
              <div className="flex flex-col items-center gap-3 py-8">
                <Loader2 size={32} className="animate-spin text-green-500" />
                <p className="text-sm text-gray-500">Menunggu QR code dari server...</p>
              </div>
            )}
            <p className="text-xs text-gray-400">
              Device: <strong>{qrModal.name}</strong> · QR refresh otomatis setiap 3 detik
            </p>
          </div>
        </div>,
        document.body
      )}
    </div>
  );
}
