import React, { useState, useEffect, useCallback } from 'react';
import { createPortal } from 'react-dom';
import { API_BASE_URL } from '../../config/api';
import { vendorConfirm } from './VendorConfirm';
import {
  Building2, MapPin, Plus, ChevronRight, ChevronDown,
  CheckCircle, AlertTriangle, Trash2, RefreshCw,
  Globe, Users, Home, Edit2, X, Search
} from 'lucide-react';

// ─── Helpers ──────────────────────────────────────────────────────────────────
const token = () => localStorage.getItem('vendor_token');
const hdrs   = () => ({ Authorization: `Bearer ${token()}`, 'Content-Type': 'application/json' });

const TYPE_META = {
  Kelurahan: { label: 'Kelurahan', color: 'bg-orange-100 text-orange-700 ', icon: Globe,    dot: 'bg-orange-500' },
  RW:        { label: 'RW',        color: 'bg-[#fdf1ef] text-[#ed6f5c]', icon: Building2, dot: 'bg-[#ed6f5c]' },
  RT:        { label: 'RT',        color: 'bg-blue-100 text-blue-700 ',         icon: Home,      dot: 'bg-[#ed6f5c]'   },
};

const Badge = ({ type }) => {
  const m = TYPE_META[type] || TYPE_META.RT;
  return <span className={`text-xs px-2 py-0.5 rounded-full font-semibold ${m.color}`}>{m.label}</span>;
};

const StatusBadge = ({ status }) => (
  <span className={`text-xs px-2 py-0.5 rounded-full font-medium ${
    status === 'active' ? 'bg-green-100 text-green-700' :
    status === 'suspended' ? 'bg-red-100 text-red-700' : 'bg-gray-100 text-gray-500'
  }`}>{status === 'active' ? 'Aktif' : status === 'suspended' ? 'Suspend' : status}</span>
);

// ─── Form Modal ───────────────────────────────────────────────────────────────
const INIT_FORM = { name: '', tenant_type: 'RT', parent_id: '', address: '', city: '', province: '' };

function TenantFormModal({ open, onClose, onSave, tenants, editData }) {
  const [form, setForm]       = useState(INIT_FORM);
  const [saving, setSaving]   = useState(false);
  const [error, setError]     = useState('');
  const [provinsiList, setProvinsiList] = useState([]);
  const [kotaList, setKotaList]         = useState([]);

  useEffect(() => {
    if (editData) setForm({ ...INIT_FORM, ...editData });
    else setForm(INIT_FORM);
    setError('');
  }, [open, editData]);

  // fetch provinsi list once on mount
  useEffect(() => {
    fetch(`${API_BASE_URL}/api/vendor/wilayah-referensi/provinsi`)
      .then(r => r.ok ? r.json() : [])
      .then(setProvinsiList)
      .catch(() => {});
  }, []);

  // cascade kota when province changes
  useEffect(() => {
    const matched = provinsiList.find(
      p => p.nama.toLowerCase() === (form.province || '').toLowerCase()
    );
    if (matched) {
      fetch(`${API_BASE_URL}/api/vendor/wilayah-referensi/kota?parent_id=${matched.id}`)
        .then(r => r.ok ? r.json() : [])
        .then(setKotaList)
        .catch(() => {});
    } else {
      setKotaList([]);
    }
  }, [form.province, provinsiList]);

  if (!open) return null;

  const parentOptions = tenants.filter(t => {
    if (form.tenant_type === 'RW')        return t.tenant_type === 'Kelurahan';
    if (form.tenant_type === 'RT')        return t.tenant_type === 'RW';
    return false;
  });

  const handleSubmit = async (e) => {
    e.preventDefault();
    if (!form.name.trim()) { setError('Nama harus diisi'); return; }
    setSaving(true); setError('');
    try {
      const body = {
        name:        form.name.trim(),
        tenant_type: form.tenant_type,
        address:     form.address,
        city:        form.city,
        province:    form.province,
        ...(form.parent_id ? { parent_id: form.parent_id } : {}),
      };
      const url    = editData ? `${API_BASE_URL}/api/vendor/tenants/${editData.id}` : `${API_BASE_URL}/api/vendor/tenants`;
      const method = editData ? 'PATCH' : 'POST';
      const res  = await fetch(url, { method, headers: hdrs(), body: JSON.stringify(body) });
      const data = await res.json();
      if (!res.ok) throw new Error(data.detail || 'Gagal menyimpan');
      onSave();
      onClose();
    } catch (e) { setError(e.message); }
    setSaving(false);
  };

  return createPortal(
    <div className="fixed inset-0 bg-black/40 backdrop-blur-sm z-[9999] flex items-center justify-center p-4">
      <div className="bg-white  rounded-2xl shadow-2xl w-full max-w-lg">
        <div className="p-5 border-b border-gray-200  flex items-center justify-between">
          <h3 className="font-bold text-gray-800  text-lg">
            {editData ? 'Edit Tenant' : 'Tambah Tenant Baru'}
          </h3>
          <button onClick={onClose} className="text-gray-400 hover:text-gray-600"><X size={18} /></button>
        </div>

        <form onSubmit={handleSubmit} className="p-5 space-y-4">
          {error && (
            <div className="flex items-center gap-2 bg-red-50 border border-red-200 rounded-lg p-3 text-sm text-red-600">
              <AlertTriangle size={14} />{error}
            </div>
          )}

          {/* Tipe */}
          <div>
            <label className="text-sm font-medium text-gray-700  block mb-1.5">Tipe Unit</label>
            <div className="grid grid-cols-3 gap-2">
              {['Kelurahan', 'RW', 'RT'].map(t => (
                <button key={t} type="button"
                  onClick={() => setForm(f => ({ ...f, tenant_type: t, parent_id: '' }))}
                  className={`py-2.5 rounded-xl border-2 text-sm font-semibold transition-all ${
                    form.tenant_type === t
                      ? 'border-[#ed6f5c] bg-[#ed6f5c] text-white'
                      : 'border-gray-200  text-gray-500 hover:border-[#ed6f5c]'
                  }`}>
                  {t}
                </button>
              ))}
            </div>
          </div>

          {/* Nama */}
          <div>
            <label className="text-sm font-medium text-gray-700  block mb-1.5">
              Nama {form.tenant_type} <span className="text-red-500">*</span>
            </label>
            <input value={form.name} onChange={e => setForm(f => ({ ...f, name: e.target.value }))} required
              placeholder={`contoh: ${form.tenant_type === 'Kelurahan' ? 'Kel. Cimahi Selatan' : form.tenant_type === 'RW' ? 'RW 03' : 'RT 05'}`}
              className="w-full border border-gray-200  rounded-xl px-3 py-2.5 text-sm   focus:outline-none focus:ring-2 focus:ring-violet-500" />
          </div>

          {/* Parent */}
          {(form.tenant_type === 'RW' || form.tenant_type === 'RT') && (
            <div>
              <label className="text-sm font-medium text-gray-700  block mb-1.5">
                {form.tenant_type === 'RW' ? 'Kelurahan Induk' : 'RW Induk'}
                {form.tenant_type === 'RT' && ' (opsional)'}
              </label>
              <select value={form.parent_id} onChange={e => setForm(f => ({ ...f, parent_id: e.target.value }))}
                className="w-full border border-gray-200  rounded-xl px-3 py-2.5 text-sm   focus:outline-none focus:ring-2 focus:ring-violet-500">
                <option value="">-- Pilih {form.tenant_type === 'RW' ? 'Kelurahan' : 'RW'} --</option>
                {parentOptions.map(t => {
                  if (form.tenant_type === 'RT') {
                    const kel = tenants.find(x => x.id === t.parent_id);
                    return (
                      <option key={t.id} value={t.id}>
                        {t.name}{kel ? ` — ${kel.name}` : ''}
                      </option>
                    );
                  }
                  return <option key={t.id} value={t.id}>{t.name}</option>;
                })}
              </select>
              {parentOptions.length === 0 && (
                <p className="text-xs text-amber-600 mt-1">
                  ⚠ Belum ada {form.tenant_type === 'RW' ? 'Kelurahan' : 'RW'} terdaftar. Tambahkan dulu.
                </p>
              )}
            </div>
          )}

          {/* Lokasi */}
          <div className="grid grid-cols-2 gap-3">
            <div>
              <label className="text-sm font-medium text-gray-700 block mb-1.5">Provinsi</label>
              {provinsiList.length > 0 ? (
                <select
                  value={form.province}
                  onChange={e => setForm(f => ({ ...f, province: e.target.value, city: '' }))}
                  className="w-full border border-gray-200 rounded-xl px-3 py-2.5 text-sm focus:outline-none focus:ring-2 focus:ring-violet-500 bg-white">
                  <option value="">-- Pilih Provinsi --</option>
                  {provinsiList.map(p => <option key={p.id} value={p.nama}>{p.nama}</option>)}
                </select>
              ) : (
                <input value={form.province}
                  onChange={e => setForm(f => ({ ...f, province: e.target.value, city: '' }))}
                  placeholder="Jawa Barat"
                  className="w-full border border-gray-200 rounded-xl px-3 py-2.5 text-sm focus:outline-none focus:ring-2 focus:ring-violet-500" />
              )}
            </div>
            <div>
              <label className="text-sm font-medium text-gray-700 block mb-1.5">Kota</label>
              {kotaList.length > 0 ? (
                <select
                  value={form.city}
                  onChange={e => setForm(f => ({ ...f, city: e.target.value }))}
                  className="w-full border border-gray-200 rounded-xl px-3 py-2.5 text-sm focus:outline-none focus:ring-2 focus:ring-violet-500 bg-white">
                  <option value="">-- Pilih Kota --</option>
                  {kotaList.map(k => <option key={k.id} value={k.nama}>{k.nama}</option>)}
                </select>
              ) : (
                <input value={form.city}
                  onChange={e => setForm(f => ({ ...f, city: e.target.value }))}
                  placeholder={form.province ? 'Pilih provinsi dulu' : 'Sukabumi'}
                  className="w-full border border-gray-200 rounded-xl px-3 py-2.5 text-sm focus:outline-none focus:ring-2 focus:ring-violet-500" />
              )}
            </div>
          </div>

          <div>
            <label className="text-sm font-medium text-gray-700  block mb-1.5">Alamat</label>
            <textarea value={form.address} onChange={e => setForm(f => ({ ...f, address: e.target.value }))} rows={2}
              className="w-full border border-gray-200  rounded-xl px-3 py-2.5 text-sm   focus:outline-none focus:ring-2 focus:ring-violet-500 resize-none" />
          </div>

          <div className="flex gap-3 pt-1">
            <button type="button" onClick={onClose}
              className="flex-1 border border-gray-200  rounded-xl py-2.5 text-sm font-medium hover:bg-gray-50 text-gray-700 ">
              Batal
            </button>
            <button type="submit" disabled={saving}
              className="flex-1 bg-[#ed6f5c] hover:bg-[#ed6f5c] text-white rounded-xl py-2.5 text-sm font-semibold disabled:opacity-50">
              {saving ? 'Menyimpan...' : editData ? 'Simpan Perubahan' : 'Tambah'}
            </button>
          </div>
        </form>
      </div>
    </div>,
    document.body
  );
}

// ─── Hierarchy Tree Node ──────────────────────────────────────────────────────
function TreeNode({ node, allTenants, onEdit, onToggleStatus, onDelete, onTogglePanic, depth = 0 }) {
  const [open, setOpen] = useState(false);
  const children = allTenants.filter(t => t.parent_id === node.id);
  const meta     = TYPE_META[node.tenant_type] || TYPE_META.RT;
  const Icon     = meta.icon;

  return (
    <div className={depth > 0 ? 'ml-6 border-l-2 border-gray-100  pl-4' : ''}>
      <div className="flex items-center gap-2 py-2.5 group">
        {/* Expand toggle */}
        <button onClick={() => setOpen(o => !o)}
          className={`text-gray-300  ${children.length ? 'hover:text-gray-500' : 'invisible'}`}>
          {open ? <ChevronDown size={14} /> : <ChevronRight size={14} />}
        </button>

        {/* Icon */}
        <div className={`w-7 h-7 rounded-lg flex items-center justify-center ${
          node.tenant_type === 'Kelurahan' ? 'bg-orange-100' :
          node.tenant_type === 'RW'        ? 'bg-[#fdf1ef]' :
                                             'bg-blue-100'
        }`}>
          <Icon size={13} className={
            node.tenant_type === 'Kelurahan' ? 'text-orange-600' :
            node.tenant_type === 'RW'        ? 'text-[#ed6f5c]' : 'text-blue-600'
          } />
        </div>

        {/* Info */}
        <div className="flex-1 min-w-0">
          <div className="flex items-center gap-2 flex-wrap">
            <span className="text-sm font-semibold text-gray-800  truncate">{node.name}</span>
            <Badge type={node.tenant_type} />
            <StatusBadge status={node.status} />
          </div>
          {(node.city || node.address) && (
            <p className="text-xs text-gray-400 truncate flex items-center gap-1 mt-0.5">
              <MapPin size={10} />{[node.city, node.province].filter(Boolean).join(', ') || node.address}
            </p>
          )}
        </div>

        {/* SOS Toggle — selalu terlihat, kecil */}
        <button
          onClick={() => onTogglePanic(node)}
          title={node.panic_button_enabled === false ? 'SOS OFF — klik untuk aktifkan' : 'SOS ON — klik untuk nonaktifkan'}
          className="flex items-center gap-1 flex-shrink-0 px-1.5 py-0.5 rounded hover:bg-gray-100 transition-colors"
        >
          <span className="text-[9px] font-semibold text-gray-400 uppercase">SOS</span>
          <div className={`w-6 h-3 rounded-full relative transition-colors flex-shrink-0 ${
            node.panic_button_enabled === false ? 'bg-gray-300' : 'bg-red-500'
          }`}>
            <div className={`w-2 h-2 rounded-full bg-white absolute top-[2px] shadow-sm transition-all duration-200 ${
              node.panic_button_enabled === false ? 'left-[2px]' : 'left-[14px]'
            }`} />
          </div>
        </button>

        {/* Actions — visible on hover */}
        <div className="flex items-center gap-1 opacity-0 group-hover:opacity-100 transition-opacity flex-shrink-0">
          <button onClick={() => onEdit(node)}
            className="p-1.5 rounded-lg hover:bg-[#fdf1ef] text-gray-400 hover:text-[#ed6f5c]">
            <Edit2 size={13} />
          </button>
          <button onClick={() => onToggleStatus(node)}
            className={`p-1.5 rounded-lg text-xs font-medium px-2 ${
              node.status === 'active'
                ? 'hover:bg-red-50 text-gray-400 hover:text-red-500'
                : 'hover:bg-green-50 text-gray-400 hover:text-green-600'
            }`}>
            {node.status === 'active' ? 'Suspend' : 'Aktifkan'}
          </button>
          <button onClick={() => onDelete(node)}
            className="p-1.5 rounded-lg hover:bg-red-50 text-gray-400 hover:text-red-500">
            <Trash2 size={13} />
          </button>
        </div>
      </div>

      {/* Children */}
      {open && children.length > 0 && (
        <div>
          {children.map(child => (
            <TreeNode key={child.id} node={child} allTenants={allTenants}
              onEdit={onEdit} onToggleStatus={onToggleStatus} onDelete={onDelete} onTogglePanic={onTogglePanic} depth={depth + 1} />
          ))}
        </div>
      )}
    </div>
  );
}

// ─── Main Page ────────────────────────────────────────────────────────────────
export default function VendorOnboarding() {
  const [tenants, setTenants]     = useState([]);
  const [loading, setLoading]     = useState(true);
  const [search, setSearch]       = useState('');
  const [filterType, setFilterType] = useState('');
  const [modalOpen, setModalOpen] = useState(false);
  const [editData, setEditData]   = useState(null);
  const [activeTab, setActiveTab] = useState('hierarchy'); // hierarchy | table

  const fetchTenants = useCallback(async () => {
    setLoading(true);
    try {
      const res = await fetch(`${API_BASE_URL}/api/vendor/tenants`, { headers: hdrs() });
      if (res.ok) setTenants(await res.json());
    } catch (_) {}
    setLoading(false);
  }, []);

  useEffect(() => { fetchTenants(); }, [fetchTenants]);

  const handleEdit = (tenant) => {
    setEditData(tenant);
    setModalOpen(true);
  };

  const handleAdd = () => {
    setEditData(null);
    setModalOpen(true);
  };

  const handleTogglePanic = async (tenant) => {
    const newVal = tenant.panic_button_enabled === false ? true : false;
    const tipe   = (tenant.tenant_type || '').toUpperCase();
    const cascadeNote =
      tipe === 'KELURAHAN' ? '\n\nTombol SOS di semua RW dan RT di bawah Kelurahan ini ikut terpengaruh.' :
      tipe === 'RW'        ? '\n\nTombol SOS di semua RT di bawah RW ini ikut terpengaruh.' : '';
    const msg = newVal
      ? `Aktifkan tombol SOS untuk ${tipe} "${tenant.name}"?\n\nWarga, pengurus RT/RW/Kelurahan di wilayah ini akan kembali dapat menggunakan tombol SOS.${cascadeNote}`
      : `Nonaktifkan tombol SOS untuk ${tipe} "${tenant.name}"?\n\nTombol SOS akan disembunyikan dari semua pengguna di wilayah ini.${cascadeNote}`;
    if (!await vendorConfirm(msg, newVal ? `Aktifkan SOS — ${tipe}` : `Nonaktifkan SOS — ${tipe}`)) return;
    await fetch(`${API_BASE_URL}/api/vendor/tenants/${tenant.id}`, {
      method: 'PATCH', headers: hdrs(),
      body: JSON.stringify({ panic_button_enabled: newVal }),
    });
    fetchTenants();
  };

  const handleToggleStatus = async (tenant) => {
    const newStatus = tenant.status === 'active' ? 'suspended' : 'active';
    const tipe = (tenant.tenant_type || '').toUpperCase();
    let confirmMsg;
    if (newStatus === 'suspended') {
      const cascadeNote =
        tipe === 'KELURAHAN' ? '\n\nSemua RW dan RT di bawah Kelurahan ini juga akan terblokir.' :
        tipe === 'RW'        ? '\n\nSemua RT di bawah RW ini juga akan terblokir.' : '';
      confirmMsg = `Suspend ${tipe} "${tenant.name}"?\n\nSeluruh pengguna di wilayah ini tidak dapat mengakses sistem dan akan melihat pesan "Wilayah Tidak Aktif".${cascadeNote}`;
    } else {
      confirmMsg = `Aktifkan kembali ${tipe} "${tenant.name}"?\n\nPengguna di wilayah ini akan dapat mengakses sistem kembali.`;
    }
    if (!await vendorConfirm(confirmMsg, newStatus === 'suspended' ? `Suspend ${tipe}` : `Aktifkan ${tipe}`)) return;
    await fetch(`${API_BASE_URL}/api/vendor/tenants/${tenant.id}/status`, {
      method: 'PATCH', headers: hdrs(), body: JSON.stringify({ status: newStatus }),
    });
    fetchTenants();
  };

  const handleDelete = async (tenant) => {
    if (!await vendorConfirm(`Hapus ${tenant.name}? Data yang terhubung ke tenant ini mungkin terpengaruh.`, 'Hapus Tenant')) return;
    await fetch(`${API_BASE_URL}/api/vendor/tenants/${tenant.id}`, { method: 'DELETE', headers: hdrs() });
    fetchTenants();
  };

  // Stats
  const countByType = (type) => tenants.filter(t => t.tenant_type === type).length;
  const rootNodes   = tenants.filter(t => !t.parent_id || t.tenant_type === 'Kelurahan');

  // Filter untuk table view
  const filtered = tenants.filter(t =>
    (!search || t.name.toLowerCase().includes(search.toLowerCase()) || t.city?.toLowerCase().includes(search.toLowerCase())) &&
    (!filterType || t.tenant_type === filterType)
  );

  return (
    <div className="space-y-5">
      {/* Header */}
      <div className="flex items-center justify-between flex-wrap gap-3">
        <div>
          <h1 className="text-2xl font-bold text-gray-800 ">Onboarding Wilayah</h1>
          <p className="text-sm text-gray-500 ">Kelola hierarki Kelurahan → RW → RT</p>
        </div>
        <div className="flex gap-2">
          <button onClick={fetchTenants}
            className="flex items-center gap-2 px-3 py-2 border border-gray-200  rounded-xl text-sm hover:bg-gray-50">
            <RefreshCw size={14} className={loading ? 'animate-spin' : ''} />
          </button>
          <button onClick={handleAdd}
            className="flex items-center gap-2 px-4 py-2 bg-[#ed6f5c] hover:bg-[#ed6f5c] text-white rounded-xl text-sm font-semibold">
            <Plus size={15} /> Tambah Unit Wilayah
          </button>
        </div>
      </div>

      {/* Stat cards */}
      <div className="grid grid-cols-3 gap-4">
        {[
          { label: 'Kelurahan', count: countByType('Kelurahan'), icon: Globe,    bg: 'bg-orange-100', ic: 'text-orange-600', val: 'text-orange-600' },
          { label: 'RW',        count: countByType('RW'),        icon: Building2, bg: 'bg-[#fdf1ef]', ic: 'text-[#ed6f5c]', val: 'text-[#ed6f5c]' },
          { label: 'RT',        count: countByType('RT'),        icon: Home,      bg: 'bg-blue-100',    ic: 'text-blue-600',   val: 'text-blue-600'   },
        ].map(({ label, count, icon: Icon, bg, ic, val }) => (
          <div key={label} className="bg-white  rounded-xl border border-gray-200  p-5">
            <div className="flex items-center justify-between mb-2">
              <span className="text-sm text-gray-500 ">{label}</span>
              <div className={`w-9 h-9 rounded-xl flex items-center justify-center ${bg}`}>
                <Icon size={16} className={ic} />
              </div>
            </div>
            <p className={`text-3xl font-bold ${val}`}>{count}</p>
          </div>
        ))}
      </div>

      {/* Tab + Search */}
      <div className="bg-white  rounded-2xl border border-gray-200  overflow-hidden">
        {/* Tab bar */}
        <div className="flex items-center border-b border-gray-200  px-4">
          {[
            { key: 'hierarchy', label: 'Tampilan Hierarki' },
            { key: 'table',     label: 'Tampilan Tabel' },
          ].map(tab => (
            <button key={tab.key} onClick={() => setActiveTab(tab.key)}
              className={`px-4 py-3.5 text-sm font-medium border-b-2 transition-colors ${
                activeTab === tab.key
                  ? 'border-[#ed6f5c] text-[#ed6f5c]'
                  : 'border-transparent text-gray-500  hover:text-gray-700'
              }`}>
              {tab.label}
            </button>
          ))}

          {/* Search — hanya di table view */}
          {activeTab === 'table' && (
            <div className="ml-auto flex items-center gap-2 py-2">
              <div className="relative">
                <Search size={14} className="absolute left-2.5 top-1/2 -translate-y-1/2 text-gray-400" />
                <input value={search} onChange={e => setSearch(e.target.value)}
                  placeholder="Cari nama / kota..."
                  className="pl-8 pr-3 py-1.5 border border-gray-200  rounded-lg text-sm   w-48 focus:outline-none focus:ring-2 focus:ring-violet-500" />
              </div>
              <select value={filterType} onChange={e => setFilterType(e.target.value)}
                className="border border-gray-200  rounded-lg px-2 py-1.5 text-sm   focus:outline-none">
                <option value="">Semua Tipe</option>
                <option value="Kelurahan">Kelurahan</option>
                <option value="RW">RW</option>
                <option value="RT">RT</option>
              </select>
            </div>
          )}
        </div>

        {/* Content */}
        {loading ? (
          <div className="flex justify-center py-16">
            <div className="w-8 h-8 border-4 border-[#ed6f5c] border-t-transparent rounded-full animate-spin" />
          </div>
        ) : tenants.length === 0 ? (
          <div className="py-16 text-center">
            <Building2 size={40} className="mx-auto text-gray-300 mb-3" />
            <p className="text-gray-500 font-medium">Belum ada unit wilayah</p>
            <p className="text-gray-400 text-sm mt-1 mb-4">Mulai dengan menambahkan Kelurahan terlebih dahulu</p>
            <button onClick={handleAdd}
              className="px-4 py-2 bg-[#ed6f5c] text-white text-sm rounded-xl hover:bg-[#ed6f5c]">
              + Tambah Kelurahan
            </button>
          </div>
        ) : activeTab === 'hierarchy' ? (
          /* ── Hierarchy View ── */
          <div className="p-4">
            {/* Legend */}
            <div className="flex items-center gap-4 mb-4 pb-3 border-b border-gray-200 ">
              {[
                { type: 'Kelurahan', Icon: Globe,    bg: 'bg-orange-100', ic: 'text-orange-600' },
                { type: 'RW',        Icon: Building2, bg: 'bg-[#fdf1ef]', ic: 'text-[#ed6f5c]' },
                { type: 'RT',        Icon: Home,      bg: 'bg-blue-100',   ic: 'text-blue-600'  },
              ].map(({ type, Icon, bg, ic }) => (
                <div key={type} className="flex items-center gap-1.5 text-xs text-gray-500">
                  <div className={`w-5 h-5 rounded-md flex items-center justify-center ${bg}`}>
                    <Icon size={11} className={ic} />
                  </div>{type}
                </div>
              ))}
              <span className="text-xs text-gray-400 ml-auto">Hover baris untuk lihat aksi</span>
            </div>

            {/* Tree — Kelurahan jadi root, lainnya sorted by type */}
            {rootNodes.length > 0 ? (
              rootNodes.map(node => (
                <TreeNode key={node.id} node={node} allTenants={tenants}
                  onEdit={handleEdit} onToggleStatus={handleToggleStatus} onDelete={handleDelete} onTogglePanic={handleTogglePanic} />
              ))
            ) : (
              // Tampilkan flat jika tidak ada parent
              tenants.map(node => (
                <TreeNode key={node.id} node={node} allTenants={tenants}
                  onEdit={handleEdit} onToggleStatus={handleToggleStatus} onDelete={handleDelete} onTogglePanic={handleTogglePanic} />
              ))
            )}
          </div>
        ) : (
          /* ── Table View ── */
          <div className="overflow-x-auto">
            <table className="w-full text-sm">
              <thead className="bg-gray-50">
                <tr>
                  {['Nama', 'Tipe', 'Induk', 'Lokasi', 'Status', 'Aksi'].map(h => (
                    <th key={h} className="px-5 py-3 text-left text-xs font-semibold text-gray-500  uppercase">{h}</th>
                  ))}
                </tr>
              </thead>
              <tbody className="divide-y divide-gray-100">
                {filtered.length === 0 && (
                  <tr><td colSpan={6} className="px-5 py-8 text-center text-gray-400 text-sm">Tidak ada data</td></tr>
                )}
                {filtered.map(t => {
                  const parent = tenants.find(p => p.id === t.parent_id);
                  const grandparent = (t.tenant_type === 'RT' && parent)
                    ? tenants.find(p => p.id === parent.parent_id)
                    : null;
                  return (
                    <tr key={t.id} className="hover:bg-gray-50">
                      <td className="px-5 py-3 font-medium text-gray-800 ">{t.name}</td>
                      <td className="px-5 py-3"><Badge type={t.tenant_type} /></td>
                      <td className="px-5 py-3 text-gray-500">
                        {parent ? (
                          <span>
                            {parent.name}
                            {grandparent && (
                              <span className="ml-1 text-xs text-gray-400">— {grandparent.name}</span>
                            )}
                          </span>
                        ) : <span className="text-gray-300">—</span>}
                      </td>
                      <td className="px-5 py-3 text-gray-500">
                        {[t.city, t.province].filter(Boolean).join(', ') || <span className="text-gray-300">—</span>}
                      </td>
                      <td className="px-5 py-3"><StatusBadge status={t.status} /></td>
                      <td className="px-5 py-3">
                        <div className="flex items-center gap-2">
                          <button onClick={() => handleEdit(t)}
                            className="text-xs px-2.5 py-1 border border-gray-200  rounded-lg hover:bg-[#ed6f5c] hover:border-[#ed6f5c] hover:text-[#ed6f5c] text-gray-500 flex items-center gap-1">
                            <Edit2 size={11} /> Edit
                          </button>
                          <button onClick={() => handleToggleStatus(t)}
                            className={`text-xs px-2.5 py-1 rounded-lg ${
                              t.status === 'active'
                                ? 'bg-red-50 text-red-500 hover:bg-red-100'
                                : 'bg-green-50 text-green-600 hover:bg-green-100'
                            }`}>
                            {t.status === 'active' ? 'Suspend' : 'Aktifkan'}
                          </button>
                          <button onClick={() => handleDelete(t)}
                            className="p-1.5 text-gray-400 hover:text-red-500 hover:bg-red-50 rounded-lg">
                            <Trash2 size={13} />
                          </button>
                        </div>
                      </td>
                    </tr>
                  );
                })}
              </tbody>
            </table>
            <div className="px-5 py-3 border-t border-gray-200  text-xs text-gray-400">
              {filtered.length} dari {tenants.length} unit wilayah
            </div>
          </div>
        )}
      </div>

      {/* Form Modal */}
      <TenantFormModal
        open={modalOpen}
        onClose={() => { setModalOpen(false); setEditData(null); }}
        onSave={fetchTenants}
        tenants={tenants}
        editData={editData}
      />
    </div>
  );
}


