import React from 'react';
import { useNavigate } from 'react-router-dom';
import { useAuth } from '@/contexts/AuthContext';
import { Siren } from 'lucide-react';

const ADMIN_ROLES = ['admin', 'pengurus_rw', 'pengurus_kelurahan'];

export default function PanicAlertBanner({ count = 0 }) {
  const { user } = useAuth();
  const navigate  = useNavigate();

  if (!ADMIN_ROLES.includes(user?.role) || count === 0) return null;

  const path = user?.role === 'pengurus_rw' ? '/rw/panic-alerts' : '/panic-alerts';

  return (
    <button
      onClick={() => navigate(path)}
      className="w-full flex items-center justify-center gap-2 px-4 py-2 bg-red-600 hover:bg-red-700 text-white text-sm font-semibold transition-colors"
      style={{ animation: 'panic-banner-pulse 1.5s ease-in-out infinite' }}
    >
      <Siren size={16} className="flex-shrink-0" />
      <span>
        🚨 ADA ALERT DARURAT — {count} laporan aktif
        <span className="ml-2 underline underline-offset-2">→ Klik untuk lihat</span>
      </span>
      <style>{`
        @keyframes panic-banner-pulse {
          0%, 100% { opacity: 1; }
          50%       { opacity: 0.82; }
        }
      `}</style>
    </button>
  );
}
