import React, { createContext, useContext, useState, useEffect, useCallback } from 'react';
import { useAuth } from './AuthContext';
import { API_BASE_URL } from '../config/api';

const KelurahanFilterContext = createContext(null);

const KEL_ROLES = ['kelurahan', 'pengurus_kelurahan'];

export const KelurahanFilterProvider = ({ children }) => {
  const { user, token } = useAuth();
  const [rwList, setRwList] = useState([]);
  const [selectedRW, setSelectedRW] = useState(null);

  const isKelUser = user?.role && KEL_ROLES.includes(user.role);

  const fetchRWList = useCallback(async () => {
    if (!token || !isKelUser) return;
    try {
      const res = await fetch(`${API_BASE_URL}/api/kelurahan/rw-list`, {
        headers: { Authorization: `Bearer ${token}` },
      });
      if (res.ok) {
        const data = await res.json();
        setRwList(data?.rw_list || []);
      }
    } catch (_) {}
  }, [token, isKelUser]);

  useEffect(() => { fetchRWList(); }, [fetchRWList]);

  useEffect(() => {
    if (!isKelUser) {
      setSelectedRW(null);
      setRwList([]);
    }
  }, [isKelUser]);

  return (
    <KelurahanFilterContext.Provider value={{
      rwList,
      selectedRW,
      setSelectedRW,
      rwId: selectedRW?.id || null,
    }}>
      {children}
    </KelurahanFilterContext.Provider>
  );
};

export const useKelurahanFilter = () => {
  const ctx = useContext(KelurahanFilterContext);
  if (!ctx) throw new Error('useKelurahanFilter must be used within KelurahanFilterProvider');
  return ctx;
};
