import React, { useState, useEffect } from 'react';
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogFooter } from '@/components/ui/dialog';
import { Label } from '@/components/ui/label';
import { Input } from '@/components/ui/input';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { Button } from '@/components/ui/button';
import { API_ENDPOINTS } from '@/config/api';
import { useAuth } from '@/contexts/AuthContext';

export default function FundTransactionForm({ open = false, onClose = () => {}, editTrans = null }){
  const { token } = useAuth();
  const [funds, setFunds] = useState([]);
  const [fundId, setFundId] = useState('');
  const [type, setType] = useState('OUT');
  const [amount, setAmount] = useState(0);
  const [desc, setDesc] = useState('');
  const [createKeuangan, setCreateKeuangan] = useState(false);

  useEffect(() => {
    const loadFunds = async () => {
      try {
        const res = await fetch(API_ENDPOINTS.DANA_FUNDS, { headers: { Authorization: `Bearer ${token}` } });
        if (res.ok) setFunds(await res.json());
      } catch (err) { console.error(err); }
    };
    if (token) loadFunds();
  }, [token]);

  // Prefill for edit
  useEffect(() => {
    if (editTrans) {
      setFundId(editTrans.fund_id || '');
      setType(editTrans.transaction_type || 'OUT');
      setAmount(editTrans.amount || 0);
      setDesc(editTrans.description || '');
    } else {
      setFundId(''); setType('OUT'); setAmount(0); setDesc('');
    }
  }, [editTrans, open]);

  const handleSubmit = async () => {
    try {
      let res;
      if (editTrans) {
        res = await fetch(`${API_ENDPOINTS.DANA_TRANSACTIONS}/${editTrans.id}`, {
          method: 'PUT',
          headers: { 'Content-Type': 'application/json', Authorization: `Bearer ${token}` },
          body: JSON.stringify({ fund_id: fundId, transaction_type: type, amount: Number(amount), description: desc })
        });
      } else {
        res = await fetch(API_ENDPOINTS.DANA_TRANSACTIONS, {
          method: 'POST',
          headers: { 'Content-Type': 'application/json', Authorization: `Bearer ${token}` },
          body: JSON.stringify({ fund_id: fundId, transaction_type: type, amount: Number(amount), description: desc, create_keuangan: createKeuangan })
        });
      }
      if (res.ok) {
        onClose();
      } else {
        console.error(await res.json());
      }
    } catch (err) { console.error(err); }
  };

  return (
    <Dialog open={open} onOpenChange={onClose}>
      <DialogContent className="max-w-md">
        <DialogHeader>
          <DialogTitle>{editTrans ? 'Edit Transaksi Dana' : 'Catat Penggunaan Dana'}</DialogTitle>
        </DialogHeader>
        <div className="space-y-3">
          <div>
            <Label>Pilih Dana</Label>
            <Select value={fundId} onValueChange={(v) => setFundId(v)}>
              <SelectTrigger><SelectValue placeholder="-- Pilih --" /></SelectTrigger>
              <SelectContent>
                {funds.map(f => (
                  <SelectItem key={f.id} value={f.id}>{f.fund_name}</SelectItem>
                ))}
              </SelectContent>
            </Select>
          </div>

          <div>
            <Label>Tipe</Label>
            <Select value={type} onValueChange={(v) => setType(v)}>
              <SelectTrigger><SelectValue /></SelectTrigger>
              <SelectContent>
                <SelectItem value="IN">IN</SelectItem>
                <SelectItem value="OUT">OUT</SelectItem>
              </SelectContent>
            </Select>
          </div>

          <div>
            <Label>Nominal</Label>
            <Input type="number" value={amount} onChange={(e) => setAmount(e.target.value)} />
          </div>

          <div>
            <Label>Keterangan</Label>
            <Input value={desc} onChange={(e) => setDesc(e.target.value)} />
          </div>

          <div className="flex items-center gap-2">
            <input id="createKeuTrans" type="checkbox" checked={createKeuangan} onChange={(e) => setCreateKeuangan(e.target.checked)} />
            <label htmlFor="createKeuTrans" className="text-sm text-gray-600">Rekam ke Keuangan (opsional)</label>
          </div>
        </div>
        <DialogFooter>
          <Button variant="outline" onClick={onClose}>Batal</Button>
          <Button onClick={handleSubmit} className="bg-red-600">Simpan</Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}
